  FT["PH-H2615"] = {"id":"PH-H2615","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2888_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"重新划拨第2301号共和国法项下用于东内格罗斯省Jimalalud市镇礼堂建设的若干款项的法案","en":"An Act Reappropriating Certain Sums Under Republic Act Numbered Twenty-Three Hundred and One for the Construction of the Jimalalud Municipal Hall in the Province of Negros Oriental","orig":"An Act Reappropriating Certain Sums Under Republic Act Numbered Twenty-Three Hundred and One for the Construction of the Jimalalud Municipal Hall in the Province of Negros Oriental"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2888","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2888_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2615-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sums appropriated under items (c), (d) and (k) on pages 440 and 441, subparagraph 38, paragraph d, Section two of Republic Act Numbered Twenty-three hundred and one, in the total amount of twenty-five thousand pesos, are hereby reappropriated for the construction of the Jimalalud Municipal Hall in the Municipality of Jimalalud, Province of Negros Oriental."}},{"id":"PH-H2615-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reappropriating Certain Sums Under Republic Act Numbered Twenty-Three Hundred and One for the Construction of the Jimalalud Municipal Hall in the Province of Negros Oriental","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2616"] = {"id":"PH-H2616","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2889_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"免除广播电台与电视台特许经营税及特权税的法案","en":"An Act Exempting Radio Broadcasting and Television Stations from the Payment of the Franchise and Privilege Taxes","orig":"An Act Exempting Radio Broadcasting and Television Stations from the Payment of the Franchise and Privilege Taxes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 2889","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2889_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2616-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provisions of the National Internal Revenue Code and other laws to the contrary notwithstanding, all radio broadcasting and television stations, now authorized or which may henceforth be authorized to operate in the Philippines, shall be exempt from the payment of the franchise and privilege taxes."}},{"id":"PH-H2616-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nEnacted without Executive approval, June 19, 1960."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Exempting Radio Broadcasting and Television Stations from the Payment of the Franchise and Privilege Taxes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2617"] = {"id":"PH-H2617","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2890_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第1613号共和国法第4条A编第c款第208页第（24）项的法案","en":"An Act Amending Item (24), Page 208, Paragraph c, Title A, Section Four of Republic Act Numbered Sixteen Hundred and Thirteen","orig":"An Act Amending Item (24), Page 208, Paragraph c, Title A, Section Four of Republic Act Numbered Sixteen Hundred and Thirteen"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2890","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2890_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2617-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item (24), page 208, paragraph c, Title A, Section four of Republic Act Numbered Sixteen hundred and thirteen, is hereby amended to read as follows:\n\"(24) Januiay Town Hall, Iloilo—Completion ₱50,000.00.\""}},{"id":"PH-H2617-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Item (24), Page 208, Paragraph c, Title A, Section Four of Republic Act Numbered Sixteen Hundred and Thirteen","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2618"] = {"id":"PH-H2618","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2891_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将萨马省迈多隆市镇的巴洛戈村与塔贝小村划归巴朗卡延市镇的法案","en":"An Act Transferring the Barrio of Balogo and the Sitio of Tabe in the Municipality of Maydolong, Province of Samar, to the Municipality of Balangkayan","orig":"An Act Transferring the Barrio of Balogo and the Sitio of Tabe in the Municipality of Maydolong, Province of Samar, to the Municipality of Balangkayan"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2891","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2891_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2618-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The barrio of Balogo and the sitio of Tabe in the Municipality of Maydolong, Province of Samar, are separated from said municipality, and are made part of the Municipality of Balangkayan."}},{"id":"PH-H2618-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Transferring the Barrio of Balogo and the Sitio of Tabe in the Municipality of Maydolong, Province of Samar, to the Municipality of Balangkayan","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2619"] = {"id":"PH-H2619","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2892_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第2093号共和国法第2条 J 编 C 款萨马省第465页第（23）目的法案","en":"An Act to Amend Subparagraph (23) for the Province of Samar, Page 465, Paragraph C, Title J, Section Two of Republic Act Numbered Twenty Hundred and Ninety-Three","orig":"An Act to Amend Subparagraph (23) for the Province of Samar, Page 465, Paragraph C, Title J, Section Two of Republic Act Numbered Twenty Hundred and Ninety-Three"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2892","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2892_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2619-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum appropriated under item (j), subparagraph (23) for the Province of Samar, page 465, paragraph C, Title J, Section two of Republic Act Numbered Twenty hundred and ninety-three is transferred to item (i) of the same subparagraph, which is amended to read as follows:\n\"(i) Oras Breakwater, Improvement ₱25,000.00\""}},{"id":"PH-H2619-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Subparagraph (23) for the Province of Samar, Page 465, Paragraph C, Title J, Section Two of Republic Act Numbered Twenty Hundred and Ninety-Three","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2620"] = {"id":"PH-H2620","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2893_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Balangkayan市","en":"An Act Creating Certain Barrios in the Municipality of Balangkayan, Province of Samar","orig":"An Act Creating Certain Barrios in the Municipality of Balangkayan, Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2893","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2893_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2620-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Guinpoliran, Calubian, Bangon, Caisawan and Julag in the Municipality of Balangkayan, Province of Samar, are converted into barrios of said municipality, to be known as the barrios of Guinpoliran, Calubian, Bangon, Caisawan and Julag, respectively."}},{"id":"PH-H2620-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p37"};
  FT["PH-H2621"] = {"id":"PH-H2621","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2894_1960.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Labangan市","en":"An Act Creating the Barrios of Balaniog and Pulacan in the Municipality of Labangan, Province of Zamboanga del Sur","orig":"An Act Creating the Barrios of Balaniog and Pulacan in the Municipality of Labangan, Province of Zamboanga del Sur"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2894","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2894_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2621-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sitios of Bulanit, East Tawagan Norte and Dalapang in the Municipality of Labangan, Province of Zamboanga del Sur, are constituted into a distinct and independent barrio of said municipality, to be known as the barrio of Balaniog."}},{"id":"PH-H2621-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sitios of Lower Pulacan, Limpang Proper, West Limpang, Waterfalls and Lantawan in the Municipality of Labangan, same province, are constituted into a distinct and independent barrio of said municipality, to be known as the barrio of Pulacan."}},{"id":"PH-H2621-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p37"};
  FT["PH-H2622"] = {"id":"PH-H2622","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_2895_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Bobon市","en":"An Act Creating Certain Barrios in the Municipality of Bobon, Province of Samar","orig":"An Act Creating Certain Barrios in the Municipality of Bobon, Province of Samar"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 2895","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-06-19","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_2895_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2622-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The following sitios in the Municipality of Bobon, Province of Samar, are constituted as barrios of said municipality, to wit:\n1. The sitios of Palhugan, Pocdol, Mualbual, Taladtalad, Cawayan, Bantigue, Puting Sapa, Puting Bato, Dorodanlog and Palhugan Proper, into a distinct and independent barrio, to be known as the barrio of Sto. Niño;\n2. The sitios of Macarit, Soliran, Big Hayop, Pagol, Rawis, Liyo-liyo, Saranga, Pio del Pilar, the whole Cagnipa Island and the whole of Macarit Island, into a distinct and independent barrio, to be known as the barrio of Pio del Pilar;\n3. The sitios of Doce, Estanza, Sigad, Baybay, Lonoy, Mojon, Cabontoran, Once, Calagondi-an, Sapa and Bantolinawan, into a distinct and independent barrio, to be known as the barrio of Magsaysay;\n4. The sitios of Trojillo, Casapinitan, Hibo, Caaporangan, Caglibas, Angongolcol, Nabato and Marasbaras, into a distinct and independent barrio, to be known as the barrio of Trojillo;\n5. The sitios of San Pedro, Taligngan, Langoblangob, Hinablan, Panrosayan, Gitgit, Popotsan, Egot, Panlibotan, Balat, Balalatok and all the sitios within the Island of Talibngan and Langoblangob, into a distinct and independent barrio, to be known as the barrio of San Pedro;\n6. The sitios of Bangag, Nosanosa, Baybay-dagat, Guininilihanan, Lomibtong, Nahibang, Maite, Malang-og, Hinorawan, Nahibang Iraya and Caropotdupotan, into a distinct and independent barrio, to be known as the barrio of San Isidro;\n7. The sitios of Talajib, Bonifacio, Binongto-an, Pinamalatican, Homagdon and Cantapuran, into a distinct and independent barrio, to be known as the barrio of Jose Abad Santos;\n8. The sitios of Balud, Bungcag Balocawe, Caibiran, Galutan, Cawayan, Abngon, To-og, Guinevacuetan and Balat, into a distinct and independent barrio, to be known as the barrio of Balat;\n9. The sitios of Canonghan daco, Canonghan dito, Abaca, Dulag and Manlolobog, into a distinct and independent barrio, to be known as the barrio of Somoroy;\n10. The sitios within the Island of Tampipi, into a distinct and independent barrio, to be known as the barrio of MacArthur;\n11. The sitios of Basud, Cawayan, Binongtohan, Talisay, Guinsiroman, Bari-is and Guintorilan, into a distinct and independent barrio, to be known as the barrio of Kauswagan;\n12. The sitios of Casulgan, Tura, Igot and Boyo, into a distinct and independent barrio, to be known as the barrio of Jose P. Laurel;\n13. The sitios of Panikyan, Casapa, Romana, Casapanga-dito, Malarag, Iraya Malarag, Ilawod Malarag and Cagcalapi, into a distinct and independent barrio, to be known as the barrio of Quezon; and\n14. The sitios of Canibongan, Camatsili, Palanas, Minata, Marobo and Sorok-Mama Maria, into a distinct and independent barrio, to be known as the barrio of Arellano."}},{"id":"PH-H2622-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p37"};
  FT["PH-H2623"] = {"id":"PH-H2623","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_3017_1960.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"修订第4166号法（经修正，即糖业限制法）第12条的法案","en":"An Act Amending Section Twelve of Act Numbered Forty-One Hundred and Sixty-Six, as Amended, Otherwise Known as the Sugar Limitation Law","orig":"An Act Amending Section Twelve of Act Numbered Forty-One Hundred and Sixty-Six, as Amended, Otherwise Known as the Sugar Limitation Law"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 3017","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-07-26","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_3017_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2623-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section twelve of Act Numbered Forty-one hundred and sixty-six, as amended, is further amended to read as follows:\n\"Sec. 12. The Sugar Quota Administration, jointly with the representative of the National Federation of Sugarcane Planters and the representative of the Philippines Sugar Association for a term of three years to be appointed by the President of the Philippines with the consent of the Commission on Appointments, is hereby authorized to issue rules and regulations governing the issuance of allotments and licenses and such other rules and regulations as he may consider necessary for the carrying out of the purpose of this Act. Such rules and regulations and any modifications thereof or amendments thereto shall have the same force and effect as if originally forming a part of this Act; Provided, However, That the term of office of the representatives of the sugar planters and/or sugar millers shall be terminated by the President of the Philippines upon recommendation of their respective associations on the ground that they have lost confidence in their representatives. In case of any disagreement among the Sugar Quota Administrator, the representative of the National Federation of Sugarcane Planters, and the representative of the Philippine Sugar Association, then such case shall be immediately forwarded to the Secretary of Commerce and Industry for decision, without prejudice to an appeal to the Office of the President of the Philippines whose decision shall be final.\""}},{"id":"PH-H2623-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All Acts, executive orders and rules or regulations inconsistent with the provisions of this Act, are hereby repealed or modified accordingly."}},{"id":"PH-H2623-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 19, 1960."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending Section Twelve of Act Numbered Forty-One Hundred and Sixty-Six, as Amended, Otherwise Known as the Sugar Limitation Law","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2624"] = {"id":"PH-H2624","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_3018_1960.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"将从事稻米与玉米产业的权利限于菲律宾公民并为其他目的法案","en":"An Act Limiting the Right to Engage in the Rice and Corn Industry to Citizens of the Philippines, and for Other Purposes","orig":"An Act Limiting the Right to Engage in the Rice and Corn Industry to Citizens of the Philippines, and for Other Purposes"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 3018","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-08-02","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_3018_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2624-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"No person who is not a citizen of the Philippines, or association, partnership or corporation, the capital or capital stock of which is not wholly owned by citizens of the Philippines, shall directly or indirectly engage in the rice and/or corn industry except as provided in Section three of this Act.\nAs used in this Act, the term \"rice and/or corn industry\" shall mean and include the culture, milling, warehousing, transporting, exportation, importation, handling the distribution, either in wholesale or retail, the provisions of Republic Act Numbered Eleven hundred and eighty to contrary notwithstanding, or the acquisition for the purpose of trade of rice (husked or unhusked) or corn and the by-products thereof: Provided , That public utilities duly licensed and registered in accordance with law may transport corn or rice."}},{"id":"PH-H2624-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Within sixty days from the date of approval of this Act, all persons who are not citizens of the Philippines and associations, partnerships or corporations the capital or capital stock of which is not wholly owned by citizens of the Philippines, engaged and duly licensed to engage in the rice and/or corn industry as of the date of approval of this Act shall register and file under oath with the city or municipal treasurer of the place where they reside or have their principal office a verified statement in quadruplicate containing the names, addresses and nationality of the owners, partners or stockholders, the amount of their assets, the nature and the amount of their investments, the names of their principal officials and such other related matters as may be prescribed by the Secretary of Finance.\nCopies of said statement shall be sent to the provincial treasurer and the Secretary of Finance."}},{"id":"PH-H2624-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All such persons, associations, partnerships, or corporations that have complied with the requirements provided in Section two hereof, if they so apply, shall be allowed to continue to engage in their respective lines of activity in the rice and/or corn industry only for the purpose of liquidation, as follows:\n(a) Those engaged in the retail, wholesale, culture, transportation, handling, distribution or acquisition for the purpose of trade of rice and/or corn and the by-products thereof shall be allowed to continue to engage therein for a period of two years from the date of effectivity of this Act; and\n(b) Those engaged in the milling and/or warehousing of rice and/or corn and the by-products thereof shall be allowed to continue to engage therein for a period of three years from the date of effectivity of this Act:\nProvided , That upon the termination of the periods above-provided none of said alien persons or entities shall be allowed and granted a license to engage in the rice and/or corn industry: Provided, further , That the maximum amount of the capital investments of said alien persons or entities in their respective lines of activity in the industry shall be pegged to the amount of capital investments required to be declared under Section two hereof: Provided, finally , That after the date of approval of this Act no license to engage in the rice and/or corn industry in any field of activity shall be granted to any new alien applicant therefor.\nThe license to any alien to engage in the rice and/or corn industry as above-provided shall be forfeited for any violation of any provision of laws, rules, or regulations issued pursuant thereto on economic control, nationalization, monetary, foreign exchange, taxation, health, weights and measures, labor and other laws relating to trade, commerce and industry.\nFailure of any alien to renew a license for any year within the periods above-provided shall mean voluntary retirement and shall bar renewal thereof."}},{"id":"PH-H2624-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"For the purpose of this Act, the Development Bank of the Philippines shall set aside an adequate revolving fund for loan of at least fifty million pesos, which shall be lent to Filipinos with interest of not more than seven per cent per annum against secured collaterals for milling, processing, warehousing, and marketing of rice and/or corn: Provided , That rice mills or warehouses, after evaluation by the lending banks, may also be included and allowed as collateral for corresponding loans extended to Filipinos who may wish to construct or purchase ricemills or warehouses.\nLikewise, the Philippine National Bank set aside a similar adequate revolving loan fund of at least fifty million pesos for cultivation and production, including crop loans, and quedans which shall be lent to Filipinos with interest of not more than six per cent per annum against secured collaterals: Provided , That the Central Bank shall rediscount the commercial papers covering the loans contemplated in the section at the lowest possible rate in order to insure the maintenance of financial assistance to the rice and/or corn industry: Provided, further , That FaCoMAs and other cooperatives, individual farmers, small landowners and tenants engaged in the production of palay, rice and/or corn shall be given priority in the grant of such loans.\nProducers or planters of rice and/or corn shall be allowed to organize, any provisions of law to the contrary notwithstanding, irrespective of whether or not there may be any existing FaCoMas or farmers cooperative association in their places of business and as duly organized associations shall likewise be entitled to the credit facilities that shall be available from the Development Bank of the Philippines and the Philippine National Bank therein contemplated: Provided , That the said associations of producers or planters of rice and/or corn shall not be entitled to the credit facilities provided for in Republic Act Numbered Eight hundred and twenty-one: Provided, further , That in areas where established FaCoMas cannot efficiently or fully take care of the volume of operations in the rice and/or corn production and/or marketing, as certified to that effect by the Agricultural Credit and Cooperative Financing Administration, the organization of another FaCoMa may be authorized, which FaCoMa shall likewise be entitled to all the rights and privileges provided for in Republic Act Numbered Eight hundred twenty-one."}},{"id":"PH-H2624-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"There is hereby created a board, which shall be known as the Rice and Corn Board, hereinafter called the Board, which shall administer the provisions of this Act and shall study and recommend measures for the improvement and development of the rice and corn industry. It shall be composed of the Secretary of Commerce and Industry, as chairman; the Secretary of Agriculture and Natural Resources, as vice-chairman; the Governor of the Central Bank, the President of the Philippine National Bank, the Chairman of the Development Bank of the Philippines, one representative of millers and warehousemen, two representatives of planters or producers, one representative of retailers and wholesalers, one representative of consumers cooperative and one representative of labor, as members, with the representatives of the private sector to be appointed by the President of the Philippines with the consent of the Commission on Appointments. The Chairman, the Vice-Chairman and Members of the Board shall each receive a per diem of twenty-five pesos for every meeting of the Board attended by them. The Board shall have such personnel as may be necessary who shall be appointed by it and whose compensation shall be fixed by it."}},{"id":"PH-H2624-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Within thirty days from date of approval of this Act, the Rice and Corn Board shall issue such rules and regulations as may be necessary to carry out the provisions of this Act. Such rules and regulations shall take effect fifteen days after their publication in a newspaper of general circulation printed in Manila. The provisions of this Act and the rules and regulations issued thereunder shall be translated into the dialects spoken in the different regions and shall be given as wide publicity as possible in the provinces, towns and rural areas."}},{"id":"PH-H2624-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Violations of the provisions of this Act or of any rules or regulations issued thereunder shall be punished by imprisonment of not less than five years nor more than ten years, and a fine of not less than five thousand pesos nor more than ten thousand pesos, and immediate deportation after service of the sentence.\nWhenever the violation is committed by a corporation or association, the President and each one of the directors or managers of said corporation or association who shall have knowingly permitted or failed to prevent the commission of said violation shall be held liable as principals thereof.\nThe penalty hereinabove provided shall be imposed upon a Filipino citizen who has allowed himself to be used as a dummy in violation of this Act. In case the offender is a naturalized citizen he shall in addition to the penalty prescribed herein, suffer the penalty of cancellation of his naturalization certificate and its registration in the civil registry and deportation.\nIf the offender is a public officer or employee, he shall, in addition to the penalty of imprisonment and fine prescribed herein, be dismissed from office and perpetually disqualified from holding any public office."}},{"id":"PH-H2624-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Nothing contained in this Act shall in any way impair or abridge whatever rights are granted to citizens or juridical entities of the United States of America under existing treaties or agreements between that country and the Republic of the Philippines."}},{"id":"PH-H2624-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Appropriation. For the operation and maintenance of the Rice and Corn Board, the sum of five hundred thousand pesos is hereby appropriated out of any funds in the National Treasury not otherwise appropriated which sum shall immediately be placed at the disposal of the Board upon approval of this Act."}},{"id":"PH-H2624-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"All laws or parts thereof inconsistent with this Act are hereby repealed."}},{"id":"PH-H2624-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Effectivity. Except for those provisions the effectivity of which is specifically stated, this Act shall take effect on January 1, 1961.\nApproved: August 2, 1960"}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Limiting the Right to Engage in the Rice and Corn Industry to Citizens of the Philippines, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2625"] = {"id":"PH-H2625","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_3019_1960.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"反贪污与腐败行为法","en":"Anti-Graft and Corrupt Practices Act","orig":"Anti-Graft and Corrupt Practices Act"},"level":"law","status":"active","topics":["criminal"],"docNumber":"Republic Act No. 3019","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-08-17","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_3019_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2625-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Statement of policy. It is the policy of the Philippine Government, in line with the principle that a public office is a public trust, to repress certain acts of public officers and private persons alike which constitute graft or corrupt practices or which may lead thereto."}},{"id":"PH-H2625-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Definition of terms. As used in this Act, that term\n(a) \"Government\" includes the national government, the local governments, the government-owned and government-controlled corporations, and all other instrumentalities or agencies of the Republic of the Philippines and their branches.\n(b) \"Public officer\" includes elective and appointive officials and employees, permanent or temporary, whether in the classified or unclassified or exempt service receiving compensation, even nominal, from the government as defined in the preceding subparagraph.\n(c) \"Receiving any gift\" includes the act of accepting directly or indirectly a gift from a person other than a member of the public officer's immediate family, in behalf of himself or of any member of his family or relative within the fourth civil degree, either by consanguinity or affinity, even on the occasion of a family celebration or national festivity like Christmas, if the value of the gift is under the circumstances manifestly excessive.\n(d) \"Person\" includes natural and juridical persons, unless the context indicates otherwise."}},{"id":"PH-H2625-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Corrupt practices of public officers. In addition to acts or omissions of public officers already penalized by existing law, the following shall constitute corrupt practices of any public officer and are hereby declared to be unlawful:\n(a) Persuading, inducing or influencing another public officer to perform an act constituting a violation of rules and regulations duly promulgated by competent authority or an offense in connection with the official duties of the latter, or allowing himself to be persuaded, induced, or influenced to commit such violation or offense.\n(b) Directly or indirectly requesting or receiving any gift, present, share, percentage, or benefit, for himself or for any other person, in connection with any contract or transaction between the Government and any other part, wherein the public officer in his official capacity has to intervene under the law.\n(c) Directly or indirectly requesting or receiving any gift, present or other pecuniary or material benefit, for himself or for another, from any person for whom the public officer, in any manner or capacity, has secured or obtained, or will secure or obtain, any Government permit or license, in consideration for the help given or to be given, without prejudice to Section thirteen of this Act.\n(d) Accepting or having any member of his family accept employment in a private enterprise which has pending official business with him during the pendency thereof or within one year after its termination.\n(e) Causing any undue injury to any party, including the Government, or giving any private party any unwarranted benefits, advantage or preference in the discharge of his official administrative or judicial functions through manifest partiality, evident bad faith or gross inexcusable negligence. This provision shall apply to officers and employees of offices or government corporations charged with the grant of licenses or permits or other concessions.\n(f) Neglecting or refusing, after due demand or request, without sufficient justification, to act within a reasonable time on any matter pending before him for the purpose of obtaining, directly or indirectly, from any person interested in the matter some pecuniary or material benefit or advantage, or for the purpose of favoring his own interest or giving undue advantage in favor of or discriminating against any other interested party.\n(g) Entering, on behalf of the Government, into any contract or transaction manifestly and grossly disadvantageous to the same, whether or not the public officer profited or will profit thereby.\n(h) Director or indirectly having financing or pecuniary interest in any business, contract or transaction in connection with which he intervenes or takes part in his official capacity, or in which he is prohibited by the Constitution or by any law from having any interest.\n(i) Directly or indirectly becoming interested, for personal gain, or having a material interest in any transaction or act requiring the approval of a board, panel or group of which he is a member, and which exercises discretion in such approval, even if he votes against the same or does not participate in the action of the board, committee, panel or group.\nInterest for personal gain shall be presumed against those public officers responsible for the approval of manifestly unlawful, inequitable, or irregular transaction or acts by the board, panel or group to which they belong.\n(j) Knowingly approving or granting any license, permit, privilege or benefit in favor of any person not qualified for or not legally entitled to such license, permit, privilege or advantage, or of a mere representative or dummy of one who is not so qualified or entitled.\n(k) Divulging valuable information of a confidential character, acquired by his office or by him on account of his official position to unauthorized persons, or releasing such information in advance of its authorized release date.\nThe person giving the gift, present, share, percentage or benefit referred to in subparagraphs (b) and (c); or offering or giving to the public officer the employment mentioned in subparagraph (d); or urging the divulging or untimely release of the confidential information referred to in subparagraph (k) of this section shall, together with the offending public officer, be punished under Section nine of this Act and shall be permanently or temporarily disqualified in the discretion of the Court, from transacting business in any form with the Government."}},{"id":"PH-H2625-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Prohibition on private individuals. (a) It shall be unlawful for any person having family or close personal relation with any public official to capitalize or exploit or take advantage of such family or close personal relation by directly or indirectly requesting or receiving any present, gift or material or pecuniary advantage from any other person having some business, transaction, application, request or contract with the government, in which such public official has to intervene. Family relation shall include the spouse or relatives by consanguinity or affinity in the third civil degree. The word \"close personal relation\" shall include close personal friendship, social and fraternal connections, and professional employment all giving rise to intimacy which assures free access to such public officer.\n(b) It shall be unlawful for any person knowingly to induce or cause any public official to commit any of the offenses defined in Section 3 hereof."}},{"id":"PH-H2625-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Prohibition on certain relatives. It shall be unlawful for the spouse or for any relative, by consanguinity or affinity, within the third civil degree, of the President of the Philippines, the Vice-President of the Philippines, the President of the Senate, or the Speaker of the House of Representatives, to intervene, directly or indirectly, in any business, transaction, contract or application with the Government: Provided, That this section shall not apply to any person who, prior to the assumption of office of any of the above officials to whom he is related, has been already dealing with the Government along the same line of business, nor to any transaction, contract or application already existing or pending at the time of such assumption of public office, nor to any application filed by him the approval of which is not discretionary on the part of the official or officials concerned but depends upon compliance with requisites provided by law, or rules or regulations issued pursuant to law, nor to any act lawfully performed in an official capacity or in the exercise of a profession."}},{"id":"PH-H2625-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Prohibition on Members of Congress. It shall be unlawful hereafter for any Member of the Congress during the term for which he has been elected, to acquire or receive any personal pecuniary interest in any specific business enterprise which will be directly and particularly favored or benefited by any law or resolution authored by him previously approved or adopted by the Congress during the same term.\nThe provision of this section shall apply to any other public officer who recommended the initiation in Congress of the enactment or adoption of any law or resolution, and acquires or receives any such interest during his incumbency.\nIt shall likewise be unlawful for such member of Congress or other public officer, who, having such interest prior to the approval of such law or resolution authored or recommended by him, continues for thirty days after such approval to retain such interest."}},{"id":"PH-H2625-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Statement of assets and liabilities. Every public officer, within thirty days after the approval of this Act or after assuming office, and within the month of January of every other year thereafter, as well as upon the expiration of his term of office, or upon his resignation or separation from office, shall prepare and file with the office of the corresponding Department Head, or in the case of a Head of Department or chief of an independent office, with the Office of the President, or in the case of members of the Congress and the officials and employees thereof, with the Office of the Secretary of the corresponding House, a true detailed and sworn statement of assets and liabilities, including a statement of the amounts and sources of his income, the amounts of his personal and family expenses and the amount of income taxes paid for the next preceding calendar year: Provided, That public officers assuming office less than two months before the end of the calendar year, may file their statements in the following months of January."}},{"id":"PH-H2625-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Dismissal due to unexplained wealth. If in accordance with the provisions of Republic Act Numbered One thousand three hundred seventy-nine, a public official has been found to have acquired during his incumbency, whether in his name or in the name of other persons, an amount of property and/or money manifestly out of proportion to his salary and to his other lawful income, that fact shall be a ground for dismissal or removal. Properties in the name of the spouse and unmarried children of such public official may be taken into consideration, when their acquisition through legitimate means cannot be satisfactorily shown. Bank deposits shall be taken into consideration in the enforcement of this section, notwithstanding any provision of law to the contrary."}},{"id":"PH-H2625-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Penalties for violations. (a) Any public officer or private person committing any of the unlawful acts or omissions enumerated in Sections 3, 4, 5 and 6 of this Act shall be punished with imprisonment for not less than one year nor more than ten years, perpetual disqualification from public office, and confiscation or forfeiture in favor of the Government of any prohibited interest and unexplained wealth manifestly out of proportion to his salary and other lawful income.\nAny complaining party at whose complaint the criminal prosecution was initiated shall, in case of conviction of the accused, be entitled to recover in the criminal action with priority over the forfeiture in favor of the Government, the amount of money or the thing he may have given to the accused, or the value of such thing.\n(b) Any public officer violation any of the provisions of Section 7 of this Act shall be punished by a fine of not less than one hundred pesos nor more than one thousand pesos, or by imprisonment not exceeding one year, or by both such fine and imprisonment, at the discretion of the Court.\nThe violation of said section proven in a proper administrative proceeding shall be sufficient cause for removal or dismissal of a public officer, even if no criminal prosecution is instituted against him."}},{"id":"PH-H2625-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Competent court. Until otherwise provided by law, all prosecutions under this Act shall be within the original jurisdiction of the proper Court of First Instance."}},{"id":"PH-H2625-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Prescription of offenses. All offenses punishable under this Act shall prescribe in ten years."}},{"id":"PH-H2625-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Termination of office. No public officer shall be allowed to resign or retire pending an investigation, criminal or administrative, or pending a prosecution against him, for any offense under this Act or under the provisions of the Revised Penal Code on bribery."}},{"id":"PH-H2625-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Suspension and loss of benefits. Any public officer against whom any criminal prosecution under a valid information under this Act or under the provisions of the Revised Penal Code on bribery is pending in court, shall be suspended from office. Should he be convicted by final judgment, he shall lose all retirement or gratuity benefits under any law, but if he is acquitted, he shall be entitled to reinstatement and to the salaries and benefits which he failed to receive during suspension, unless in the meantime administrative proceedings have been filed against him."}},{"id":"PH-H2625-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Exception. Unsolicited gifts or presents of small or insignificant value offered or given as a mere ordinary token of gratitude or friendship according to local customs or usage, shall be excepted from the provisions of this Act.\nNothing in this Act shall be interpreted to prejudice or prohibit the practice of any profession, lawful trade or occupation by any private person or by any public officer who under the law may legitimately practice his profession, trade or occupation, during his incumbency, except where the practice of such profession, trade or occupation involves conspiracy with any other person or public official to commit any of the violations penalized in this Act."}},{"id":"PH-H2625-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Separability clause. If any provision of this Act or the application of such provision to any person or circumstances is declared invalid, the remainder of the Act or the application of such provision to other persons or circumstances shall not be affected by such declaration."}},{"id":"PH-H2625-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity. This Act shall take effect on its approval, but for the purpose of determining unexplained wealth, all property acquired by a public officer since he assumed office shall be taken into consideration.\nApproved: August 17, 1960"}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"Anti-Graft and Corrupt Practices Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2626"] = {"id":"PH-H2626","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1960/ra_3020_1960.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Ten Million Pesos for Rehabilitation of the Damages Caused by Typhoons and Floods","orig":"An Act Appropriating the Sum of Ten Million Pesos for Rehabilitation of the Damages Caused by Typhoons and Floods"},"level":"law","status":"active","topics":["company"],"docNumber":"Republic Act No. 3020","issuingBody":"Congress of the Philippines","promulgatedDate":"1960-08-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1960/ra_3020_1960.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2626-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of ten million pesos, or so much thereof as may be necessary, is appropriated out of any funds in the National Treasury not otherwise appropriated, for the rehabilitation, construction or replacement of public buildings, including temporary and P.T.A. school buildings, roads, bridges, installation and other public services damaged by typhoons and floods in the fiscal years nineteen hundred fifty-nine-sixty and nineteen hundred sixty-sixty-one: Provided, However, That of the above amount, five million pesos shall be expended in the Bicol provinces, including Masbate: And, Provided, finally, That three million pesos of this five million shall be expended in Albay.\nDisbursements of the balance of five million pesos shall be made in accordance with certifications of the district engineers as verified by the Department of Public Works and Communications simultaneously on a pro rata basis of the damage suffered by the provinces and cities affected by said typhoons and floods."}},{"id":"PH-H2626-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: August 17, 1960."}}],"pack":"ph-p37"};
  FT["PH-H2627"] = {"id":"PH-H2627","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3021_1961.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"授权印制和发行半邮政邮票为 Jose Rizal 百年庆典筹集资金并拨付必要经费的法案","en":"An Act Authorizing the Printing and Issue of Semi-Postal Stamps to Raise Funds to be Used for the Jose Rizal Centennial Celebration and Appropriating the Necessary Funds Therefor","orig":"An Act Authorizing the Printing and Issue of Semi-Postal Stamps to Raise Funds to be Used for the Jose Rizal Centennial Celebration and Appropriating the Necessary Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3021","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-02-28","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3021_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2627-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"To raise funds for the celebration of the centenary of the birth of Dr. Jose Rizal, the Postmaster General, subject to the approval of the Department Head, is hereby authorized to order the printing and issue of semi-postal stamps for a period of three years from the date of the approval of this Act, to be known as Rizal Centennial issue, of one or more denominations, with face value showing the regular postage charge and the additional amount to be fixed by said Postmaster General with the recommendation of the Jose Rizal National Centennial Commission."}},{"id":"PH-H2627-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"These postage stamps shall bear an appropriate vignette to further perpetuate the memory of the national hero."}},{"id":"PH-H2627-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The additional sum realized from sale of these postage stamps shall be deposited with the Bureau of the Treasury and shall be placed at the disposal of the Jose Rizal National Centennial Commission, created by Executive Order Numbered Fifty-two on August ten, nineteen hundred and fifty-four, subject to the usual accounting and auditing regulations."}},{"id":"PH-H2627-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"There is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of thirty thousand pesos to defray the expenses for the preparation of the designs of the stamps, transportation, insurance and other expenses."}},{"id":"PH-H2627-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: February 28, 1961."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Printing and Issue of Semi-Postal Stamps to Raise Funds to be Used for the Jose Rizal Centennial Celebration and Appropriating the Necessary Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2628"] = {"id":"PH-H2628","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3022_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"宣布4月9日为巴丹日并定为法定假日的法案","en":"An Act Proclaiming the Ninth Day of April as Bataan Day and Declaring it as a Legal Holiday","orig":"An Act Proclaiming the Ninth Day of April as Bataan Day and Declaring it as a Legal Holiday"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3022","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-04-06","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3022_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2628-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The ninth day of April is hereby proclaimed as Bataan Day, and all public officials and citizens of the Philippines are enjoined to observe such day with a one-minute silence at 4:30 o’clock in the afternoon, and to hold appropriate rites in honor of the heroic defenders of Bataan and their parents, wives and/or widows."}},{"id":"PH-H2628-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section twenty-nine of the Revised Administrative Code, as amended is hereby further amended to read as follows:\n\"Sec. 29. Legal holidays. -Thursday and Friday of Holy Week, Christmas Day, and Sundays are legal religious holidays.\n\"The legal holidays are: the first of January, the ninth of April, the first of May, the fourth of July, the thirtieth of November, the thirtieth of December, and the day appointed by law for the holding of a general election: Provided, However, That when any regular holiday of fixed date falls on Sunday, the next succeeding day shall be observed as legal holiday.\""}},{"id":"PH-H2628-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 6, 1961."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Proclaiming the Ninth Day of April as Bataan Day and Declaring it as a Legal Holiday","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2629"] = {"id":"PH-H2629","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3023_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of One Hundred Thousand Pesos to Defray the Expenses of Holding the Convention of the Asian Peoples, Anti-Communist League at Manila in the Year Nineteen Hundred and Sixty-One","orig":"An Act Appropriating the Sum of One Hundred Thousand Pesos to Defray the Expenses of Holding the Convention of the Asian Peoples, Anti-Communist League at Manila in the Year Nineteen Hundred and Sixty-One"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3023","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-04-06","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3023_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2629-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby appropriated the sum of one hundred thousand pesos, out of any funds in the National Treasury not otherwise appropriated, to defray the expenses for the holding of the Seventh International Conference of the Asian People’s Anti-Communist League at Manila on May two to five nineteen hundred and sixty one, inclusive: Provided, However, That whatever resolutions passed or communiqués agreed upon by the conferees should not necessarily be interpreted as in accordance with the foreign policy of the Republic of the Philippines.\nThe sum herein appropriated shall be made available immediately upon the approval of this Act and be at the disposal of the Department of National Defense exclusively for the Philippine Anti-Communist Movement: Provided, However, That no part of this appropriation shall be used in the purchase of equipment: And Provided, further, That any and all expenses out of this appropriation shall be subject to the usual government auditing procedure."}},{"id":"PH-H2629-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: April 6, 1961."}}],"pack":"ph-p37"};
  FT["PH-H2630"] = {"id":"PH-H2630","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3024_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Amount of Twenty-Five Thousand Pesos for the Expenses of the Nineteen Hundred Sixty-One Asian Labor Ministers’ Conference in Manila","orig":"An Act Appropriating the Amount of Twenty-Five Thousand Pesos for the Expenses of the Nineteen Hundred Sixty-One Asian Labor Ministers’ Conference in Manila"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3024","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-05-07","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3024_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2630-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of twenty-five thousand pesos is hereby appropriated, out of any funds of the National Treasury not otherwise appropriated, for the purpose of defraying the expenses of the conference of labor ministers of Asian countries to be held in Manila on May eighteen, nineteen and twenty, nineteen hundred and sixty-one, including the expenses of its secretariat, the documentation of the records of the proceedings and of the accommodation of the members of the different delegations thereto during their stay in Manila as official guests of the Government of the Republic of the Philippines."}},{"id":"PH-H2630-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount hereby appropriated shall be administered by the Secretary of Labor."}},{"id":"PH-H2630-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 17, 1961."}}],"pack":"ph-p37"};
  FT["PH-H2631"] = {"id":"PH-H2631","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3025_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Fifteen Million Pesos to Defray the Expenses of the Elections for President and Vice-President of the Philippines, Eight Senators and Members of the House of Representatives to be Held on the Second Tuesday of November, Nineteen Hundred Sixty-One","orig":"An Act Appropriating the Sum of Fifteen Million Pesos to Defray the Expenses of the Elections for President and Vice-President of the Philippines, Eight Senators and Members of the House of Representatives to be Held on the Second Tuesday of November, Nineteen Hundred Sixty-One"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 3025","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-05-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3025_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2631-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of fifteen million pesos to be spent under the exclusive authority of the Commission on Elections, for payment of the expenses which may be incurred in connection with, and incidental to, the holding of the national elections on the second Tuesday of November, nineteen hundred and sixty-one, for President and Vice-President of the Philippines, for the eight Senators who will succeed those whose terms of office will expire on December thirtieth, nineteen hundred and sixty-one, and Members of the House of Representatives, including unpaid obligations incurred by said Commission in previous elections: Provided, That this appropriation shall be available to the expenditure before July one, nineteen hundred and sixty-one and shall continue to be available after June thirty, nineteen hundred and sixty-two, exclusively for this purpose: Provided, However, That out of the fund, the sum of not more than seven hundred sixty thousand pesos shall be for the operational expenses of the Philippine Constabulary and the sum of not more than one million pesos shall be used for traveling expenses and food of ROTC cadets and officers, if called upon by the Commission on Elections to help in the maintenance of free, orderly and honest elections: Provided, finally, That out of this appropriation, twenty thousand pesos or so much as may be necessary, shall be used for the purchase and maintenance of one motor vehicle, the provisions of existing law to the contrary notwithstanding."}},{"id":"PH-H2631-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Any provision of existing law to the contrary notwithstanding, the Commission on Elections may authorize the payment of the compensation from the appropriation authorized in this Act to its officials and employees, or those assigned thereto, except the Chairman and Members of the Commission, for overtime service rendered on Saturdays, Sundays and holidays, or after twelve-thirty o’clock post meridian during half-day sessions and after five o’clock post meridian on regular working days, including overtime service rendered prior to the approval of this Act in connection with the election, at rates to be fixed by the Commission on Elections which shall not exceed the rate of their monthly compensation. Such additional compensation shall not exceed, for any one month, the equivalent of their regular compensation nor shall it exceed, for any one fiscal year, fifty per centum of such regular compensation."}},{"id":"PH-H2631-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: May 23, 1961."}}],"pack":"ph-p37"};
  FT["PH-H2632"] = {"id":"PH-H2632","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3026_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"授权向公路分区工程师、公路区工程师与市工程师分别以公共工程局当然分区工程师、区工程师与市工程师身份发放附加报酬","en":"An Act Authorizing the Payment of Additional Compensation to Highway Division Engineers, Highway District Engineers and City Engineers as Ex-Officio Division Engineers, District Engineers and City Engineers of the Bureau of Public Works, Respectively","orig":"An Act Authorizing the Payment of Additional Compensation to Highway Division Engineers, Highway District Engineers and City Engineers as Ex-Officio Division Engineers, District Engineers and City Engineers of the Bureau of Public Works, Respectively"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3026","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-05-31","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3026_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2632-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Additional compensation for highway division engineers, highway district engineers and city engineers as ex-officio division engineers, district engineers and city engineers of the Bureau of Public Works, respectively, is hereby authorized to be paid from the Engineering funds, K-26, of the district or city or from any fund of the province, subprovince or city concerned, in the following amounts, subject, however, to the availability of such funds:\n(a) Fifty pesos per month for highway division engineers;\n(b) One hundred pesos per month for highway district engineers or city engineers in first-class, second-class and third-class provinces or cities;\n(c) Eighty pesos per month for highway district engineers or city engineers in fourth-class and fifth-class provinces or subprovinces or cities; and\n(d) Sixty pesos per month for highway district engineers or city engineers in sixth-class and seventh-class provinces or subprovinces or cities.\nThe additional compensation of the highway division engineer shall be apportioned proportionately among the provinces, subprovinces and cities composing the Division."}},{"id":"PH-H2632-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All laws or parts thereof inconsistent herewith are repealed or modified accordingly."}},{"id":"PH-H2632-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon the date of effectivity of Republic Act Numbered Eighteen hundred thirty-six, which has authorized the dual functions.\nApproved: May 31, 1961."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Payment of Additional Compensation to Highway Division Engineers, Highway District Engineers and City Engineers as Ex-Officio Division Engineers, District Engineers and City Engineers of the Bureau of Public Works, Respectively","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2633"] = {"id":"PH-H2633","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3027_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将宿务市Abellana国立职业学校的名称正式变更为Abellana国立学校的法案","en":"An Act Changing the Name of the Abellana National Vocational School in the City of Cebu to Abellana National School","orig":"An Act Changing the Name of the Abellana National Vocational School in the City of Cebu to Abellana National School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 3027","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-07","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3027_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2633-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Abellana National Vocational School in the City of Cebu is hereby changed to Abellana National School. General courses as well as vocational courses shall be offered in said school."}},{"id":"PH-H2633-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 7, 1961."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Abellana National Vocational School in the City of Cebu to Abellana National School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2634"] = {"id":"PH-H2634","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3028_1961.html","fetchedAt":"2026-10-06","articleCount":96,"structureMode":"ARTICLE","title":{"zh":"将 Danao 设立为市法案","en":"An Act Creating Danao City","orig":"An Act Creating Danao City"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3028","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-07","completenessNote":"全文，共 83 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3028_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 96 条，缺 2、7、24、28、31、32、33、36、37、65、79、90、91）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2634-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"This Act shall be known as the \"Charter of Danao City.\""},"text":{"en":"Section 1. This Act shall be known as the \"Charter of Danao City.\"\nAricle I\nThe City as a Public Corporation"}},{"id":"PH-H2634-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"Territory of Danao City. -The Danao City which is hereby created shall comprise the present territorial jurisdiction of"},"text":{"en":"Section 2. Territory of Danao City. -The Danao City which is hereby created shall comprise the present territorial jurisdiction of the Poblacion and the following barrios of Baliang, Binalew, Cabungahan, Cahumayhumayan, Cambanay, Dumga, Cogon-Cruz, Dunggoan, Guinacot, Guinsay, Ibo Lamac, Lawa-an Langosig, Licos, Looc, Magtagobtob, Masaba, Maslog, Malapoc, Manlayag, Manteja, Nangka, Ogis, Pili (proper, Anislagan, Catulero), Quisol, Sabang, Sacsac, Sandayong Norte, Sandayong Sur, Santa Rosa, Santikan, Sibacan, Suba, Tabok, Togonon, Taytay, Tuburan Sur, Danasan, Bayabas, Cambubho, and all other barrios of the Municipality of Danao, Province of Cebu."}},{"id":"PH-H2634-A3","no":3,"noLabel":{"en":"Section 3."},"heading":{"en":"Corporate charter. -The Danao City constitutes a political body corporate and as such is endowed with the attribute of p"},"text":{"en":"Section 3. Corporate charter. -The Danao City constitutes a political body corporate and as such is endowed with the attribute of perpetual succession and possessed of the powers which pertain to a municipal corporation, to be exercised in conformity with the provisions of this Charter."}},{"id":"PH-H2634-A4","no":4,"noLabel":{"en":"Section 4."},"heading":{"en":"General powers. -The city shall have a common alter the same at pleasure, and may take, purchase, receive, hold, lease,"},"text":{"en":"Section 4. General powers. -The city shall have a common alter the same at pleasure, and may take, purchase, receive, hold, lease, convey, and dispose of real and personal property for the general interests of the city, condemn private property for public use, contract and be contracted with, sue and be sued, and prosecute as well as defend to final judgment and execution, actions where its interest are involved, and exercise all the powers hereinafter conferred."}},{"id":"PH-H2634-A5","no":5,"noLabel":{"en":"Section 5."},"heading":{"en":"Liability for damages. -The city shall not be liable or held for damages or injuries to persons or property arising from"},"text":{"en":"Section 5. Liability for damages. -The city shall not be liable or held for damages or injuries to persons or property arising from the failure of the Mayor, the Municipal Board or any other city officer or employee, to enforce the provisions of this Charter, or of any other law or ordinance, or from the negligence of said mayor, municipal board or other city officers or employees which enforcing or attempting to enforce said provisions: Provided, However, That nothing herein contained shall prevent any aggrieved party from filing a personal action in the proper court against any official or employee of the city government for any act or omission in the performance of his duties."}},{"id":"PH-H2634-A6","no":6,"noLabel":{"en":"Section 6."},"heading":{"en":"Jurisdiction of the City. -The jurisdiction of Danao City for police purposes only shall be co-extensive with its territ"},"text":{"en":"Section 6. Jurisdiction of the City. -The jurisdiction of Danao City for police purposes only shall be co-extensive with its territorial jurisdiction, and shall extend to three miles from the shores of the city; and for the purpose of protecting and insuring the purity of the water supply of the city, such police jurisdiction shall also extend over or within one hundred meters of any reservoir, conduit, canal, aqueduct or pumping station used in connection with the city water service. The Municipal Court of the city shall have concurrent jurisdiction with the Justice of the Peace Court of the respective municipalities to try crimes and misdemeanors committed within said drainage area, or within said spaces of one hundred meters. The court first taking jurisdiction of such an offense shall thereafter retain exclusive jurisdiction thereof. The police force of the several municipalities concerned shall have concurrent jurisdiction with the police force of the city for the maintenance of good order and the enforcement of ordinances throughout said zone, area and spaces. But any license that may be issued with said zone, area or spaces shall be granted by the proper authorities of the municipality concerned, and the fees arising therefrom shall accrue to the treasury of the said municipality concerned and not to that of the city."}},{"id":"PH-H2634-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"Article II The Mayor and the Vice-Mayor"},"heading":{"en":"The Mayor. -The Mayor shall be the chief executive of the city. He shall be elected at large by the qualified voters of"},"text":{"en":"Section 7. The Mayor. -The Mayor shall be the chief executive of the city. He shall be elected at large by the qualified voters of the city. No person shall be eligible for the position of Mayor unless at the time of the election he is at least twenty-five years of age, a resident of the city for at least ten years prior to his election, and a qualified voter therein. He shall hold office for four years, unless sooner removed, and shall receive a salary of six thousand pesos per annum. The municipal Board may appropriate such sum of money as may be necessary for the house allowance of the Mayor, not to exceed two hundred pesos monthly, or commute the same in addition to his salary."}},{"id":"PH-H2634-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"Article II The Mayor and the Vice-Mayor"},"heading":{"en":"The Vice-Mayor. -There shall be elected a Vice-Mayor who shall perform the duties and exercise the powers of the Mayor i"},"text":{"en":"Section 8. The Vice-Mayor. -There shall be elected a Vice-Mayor who shall perform the duties and exercise the powers of the Mayor in the event of the death, sickness, absence or other temporary incapacity of the Mayor, or in the event of a definite vacancy in the position of Mayor until said office shall be filled in accordance with law. The Vice-Mayor shall be elected in the same manner as the Mayor and shall at the time of his election possess the same qualifications as the Mayor.\nIf, for any reason, the Vice-Mayor is temporarily incapacitated for the performance of the duties of the office of the Mayor, or said office of the Vice-Mayor is vacant, the duties and powers of the Mayor shall be performed and exercised by a member of the Municipal Board who shall be chosen by a majority of all the members thereof. Whenever the Vice-Mayor performs the duties and exercises the powers of the Mayor, he automatically ceases to be the presiding officer of the Municipal Board. Where a member of the Municipal Board exercises the functions of the Vice-Mayor, said member ceases temporarily to take part in the deliberations of the Board except to preside. When the offices of the City Mayor and the Vice-Mayor are left vacant by virtue of the death or permanent disability of the incumbents, vacancies shall be filled by appointments by the President of the Philippines with the consent of the Commission on Appointments.\nThe Vice-Mayor shall perform such other duties as may be assigned to him by the Mayor or prescribed by law or ordinance. He shall receive a salary of three thousand pesos per annum."}},{"id":"PH-H2634-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"Article II The Mayor and the Vice-Mayor"},"heading":{"en":"General powers and duties of the Mayor. -The Mayor shall have immediate control over the executive and administrative fu"},"text":{"en":"Section 9. General powers and duties of the Mayor. -The Mayor shall have immediate control over the executive and administrative functions of the different departments of the City, subject to the supervision of the President of the Philippines. He shall have the following general powers and duties.\n(a) To comply with and enforce and give the necessary orders for the faithful enforcement and execution of the laws and ordinances in effect within the jurisdiction of the city.\n(b) To safeguard all the lands, buildings, records, moneys, credits, and other property and rights of the city, and, subject to the provisions of this Charter, have control and administration of all property owned and operated by the city.\n(c) To see that all taxes and other revenues of the city are collected and applied in accordance with appropriations to the payment of the municipal expenses.\n(d) To cause to be instituted judicial proceedings to recover property and funds of the city wherever found; to cause to be defended all suits against the city, and otherwise to protect the interest of the city.\n(e) To see that the executive officers and employees of the city properly discharge their respective duties. The Mayor may, in the interest of the service and with the approval of the Department Head or the National Government first had, transfer officers and employees not appointed by the President of the Philippines from one section, division, or service to another section, division, or service within the same department without changing the compensation they receive.\n(f) To examine and inspect the books, records and papers of all officers, agents, and employees of the city over whom he has executive supervision and control whenever occasion arises and at least once a year. For this purpose he shall be provided by the Municipal Court with such clerical or other assistance as may be necessary.\n(g) To give such information and recommend such measures to the Board as he shall deem advantageous to the city.\n(h) To attend, if he wishes to do so, either in person or by a duty authorized representative, the session of the Municipal Board and participate in its discussion, but not to vote.\n(i) To represent the city in all its business matters, and sign on its behalf all its bonds, contracts and obligations made in accordance with law and ordinances.\n(j) To submit to the Municipal Board at least two and a half months before the beginning of the ensuing fiscal year a budget of receipts and expenditures of the city.\n(k) To receive, hear, and decide as he may deem proper the petitions, complaints, and claims concerning all classes of municipal matters of an administrative or executive character.\n(l) To grant or refuse municipal licenses or permits of all classes and to revoke the same for violation of the conditions upon which they were granted, or if acts prohibited by law or municipal ordinance are being committed under the protection of such licenses or in the premises in which the business for which the same has been granted and carried on, or for any other good reason of general interest.\n(m) To exempt, after consultation with the City Superintendent of Schools, deserving poor pupils from the payment of schools fees or of any part thereof.\n(n) To take such emergency measures as may be necessary to avoid fires, floods, and to mitigate the effects of storms and other public calamities.\n(o) To perform such other duties and exercise such other powers as may be prescribed by law or ordinance."}},{"id":"PH-H2634-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"Article II The Mayor and the Vice-Mayor"},"heading":{"en":"Secretary to the Mayor. -The Mayor shall appoint one secretary who shall have the rank of a department head and who shal"},"text":{"en":"Section 10. Secretary to the Mayor. -The Mayor shall appoint one secretary who shall have the rank of a department head and who shall have charge and custody of all records and documents of the city and of any office or department thereof for which provision is not otherwise made; shall keep the corporate seal and affix the same with his signature to all ordinances and resolutions signed by the Mayor and all other official documents and papers of the government of the city as may be required by law or ordinance; shall attest all executive orders, proclamations, ordinances and resolutions signed by the Mayor and shall perform such other duties as the Mayor may require of him; shall, upon request, furnish certified copies of all city records and documents in his charge which are not of a confidential nature, and collect and receive therefor such fees as may be prescribed by law or resolution of the Municipal Board. He shall also perform such duties as are required of the heads of departments of the city government by Section twenty-one hereof. The position of the secretary shall be regarded as within the unclassified civil service but may be filled in the manner in which classified positions are filled, and if so filled, the appointee shall be entitled to all the benefits and privileges of classified employees, except that he holds office only during the term of the appointing Mayor and until a successor in the office of the secretary is appointed and qualified, unless sooner separated. He shall receive a salary of four thousand eight hundred pesos per annum."}},{"id":"PH-H2634-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"Article III The Municipal Board"},"heading":{"en":"Constitution and organization of the Municipal Board. -The Municipal Board shall be the legislative body of the City, an"},"text":{"en":"Section 11. Constitution and organization of the Municipal Board. -The Municipal Board shall be the legislative body of the City, and shall be composed of the Vice-Mayor, who shall be its presiding officer, and eight councilors who shall be elected at large by the qualified voters of the city. The Vice-Mayor shall have no right to vote except in case of a tie.\nIf the Vice-Mayor or a member of the Municipal Board shall be a candidate for office in any election, he shall be disqualified to act with said body in the performance of the duties thereof relative to such election, and if, for such reason, the number of members should be unduly reduced, the President shall appoint any disinterested voter of the city, belonging to the political party of the disqualified member, to act in his place in such matters.\nThe members of the Municipal Board shall receive a salary of one thousand eight hundred pesos each per annum."}},{"id":"PH-H2634-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"Article III The Municipal Board"},"heading":{"en":"Qualifications, election, suspension and removal of members. -The members of the Municipal Board shall, at the time of t"},"text":{"en":"Section 12. Qualifications, election, suspension and removal of members. -The members of the Municipal Board shall, at the time of their election, be qualified electors of the city, residents thereof for at least ten years immediately prior to their election and not less than twenty-three years of age. Such members may be suspended or removed from office under the same circumstances, in the same manner, and with the same effect, as elective provincial officers, and the provisions of law governing the suspension or removal of elective provincial officers are hereby made applicable in the suspension or removal of said members.\nElections for members of the Board shall be held on the date of the regular election for provincial and municipal officers, and elected members shall assume office on the first day of January next following their election, upon qualifying and shall hold office for four years and until their successors shall have been duly elected and qualified. The eight candidates receiving the greatest number of votes shall be declared elected.\nA vacancy in the Municipal Board shall be filled in accordance with the provisions of the Revised Election Code."}},{"id":"PH-H2634-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"Article III The Municipal Board"},"heading":{"en":"Secretary of the Board. -The board shall have a secretary who shall be appointed by it to serve during the term of offic"},"text":{"en":"Section 13. Secretary of the Board. -The board shall have a secretary who shall be appointed by it to serve during the term of office of the members thereof. The compensation of the secretary shall be fixed by ordinance at not exceeding four thousand one hundred twenty pesos per annum. A vacancy in the office of the secretary shall be filled temporarily for the unexpired term like manner.\nThe Secretary shall be in charge of the records of the Municipal Board. He shall keep a full record of the proceedings of the Board, and file all documents relating thereto; shall record, in a book kept for that purpose, all ordinances and all resolutions and motions directing the payment of money or creating liability, enacted or adopted by the Board, with the dates of passage of the same, and of the publication of ordinances; shall keep a seal, circular in form, with the inscription \"Municipal Board—Danao City,\" in the center of which shall be placed the arms of the city, and affix the same, with his signature, to all ordinances and other official acts of the Board, and shall present the same for signature to the preceding officer; shall cause each ordinance passed to be published as herein provided; shall, upon request, furnish certified copies of all records of public character in his charge under the seal of his office and collect and receive therefor such fees as may be prescribed by resolution of the Board; and shall keep his office and all records therein which are not of a confidential nature open to public inspection during usual business hours."}},{"id":"PH-H2634-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"Article III The Municipal Board"},"heading":{"en":"Legislative procedure. -The Board shall hold two ordinary session for the transaction of business during each week on da"},"text":{"en":"Section 14. Legislative procedure. -The Board shall hold two ordinary session for the transaction of business during each week on days which it shall fix by resolution, and such extraordinary sessions, as may be called by the Mayor. It shall sit with open doors unless otherwise ordered by the affirmative vote of a majority of all the members. If shall keep a record of all its proceedings and determine its rules of procedure not herein set forth. A majority of all the members of the Board shall constitute a quorum for the transaction of business, but a smaller number may adjourn from day to day and may compel the immediate attendance of any member who is absent without good cause by issuing to the police of the city an order for his arrest and production at the session under such penalties as shall have been previously prescribed by ordinance. The affirmative votes of a majority of all the members shall be necessary for the passage of any ordinance, or of any resolution or motion directing the payment of money or creating liability, but other measures shall prevail upon the majority votes of the members present at any session duly called and held. The ayes and nays shall be taken and recorded upon the passage of all ordinances, upon all resolutions or motions directing the payment of money or creating liability, and, at the request of approved ordinance, resolution or motion shall be sealed with the seal of the Municipal Board, and recorded in a book kept for the purpose and shall, on the day following its passage, be posted by the secretary at the main entrance of the City Hall and in at least two other public places, and shall take effect and be in force on and after the tenth day following its passage unless otherwise stated in said ordinance, resolution or motion, or vetoed by the Mayor as hereinafter provided. A vetoed ordinance, if repassed, shall take effect ten days after the veto is overridden by the required votes unless otherwise stated in the ordinance, resolution or motion or again disapproved by the Mayor.\nEach ordinance and each resolution or motion directing the payment of money or creating liability, enacted or adopted by the Board, shall be forwarded to the Mayor for his approval. Within ten days after the receipt of the ordinance, resolution or motion, the Mayor shall return it with his approval or veto. If he does not return it within that time, it shall be deemed to be approved. If he returns it with his veto, his reasons therefor in writing shall accompany it. It may then again be enacted by a two-thirds vote of all the members of the Board, and again forwarded to the Mayor for his approval, and if within ten days after its receipt he does not again return it with his veto, it shall be deemed to be approved. If within said time he again returns it with his veto, it shall be forwarded forthwith to the President for his approval, or disapproval which shall be final.\nThe Mayor shall have the power to veto any particular item or items of an appropriation ordinance, or of an ordinance, resolution or motion directing the payment of money or creating liability, but the veto shall not affect the item or items to which he does not object. The item or items objected to shall not take effect except in the manner heretofore provided in this section as to ordinances, resolutions or motions returned to the Board with his veto; but should an item or items in an appropriation ordinance be disapproved by the Mayor, the corresponding item or items in the appropriation ordinance of the previous year shall be deemed re-enacted."}},{"id":"PH-H2634-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"Article III The Municipal Board"},"heading":{"en":"Legislative powers. -The Municipal Board shall have the following legislative powers:"},"text":{"en":"Section 15. Legislative powers. -The Municipal Board shall have the following legislative powers:\n(a) To provide for the levy and collection of taxes for general and special purposes in accordance with law, including specifically the power to levy real property tax not to exceed one and one-half per centum ad valorem; Provided, That the said maximum rate of one and one-half per centum shall not be imposed during the first five years of the effectivity of this Act.\n(b) To fix with the approval of the Department Head of the National Government the number and salaries of officials and employees of the city not otherwise provided for in this act.\n(c) To authorize the free distribution of medicine to the employees and laborers of the city whose salary or wage does not exceed one hundred and twenty pesos per month or four pesos per day, and of evaporated or fresh native milk to indigent mothers, residing in the city and or bread and light meals to indigent children ten years or less of age residing in the city, the distribution to be made under the direct supervision and control of the Mayor.\n(d) To fix the tariff of fees and charges for all services rendered by the city or any of its departments, branches or officials.\n(e) To provide for the erection and maintenance or the rental, in case of need, of the necessary buildings for the use of the city.\n(f) To provide for the establishment and maintenance of public schools; and, except as otherwise provided by law, to fix, with the approval of the Director of Public School, reasonable matriculation and/or tuition fees for intermediate and secondary instruction therein and to acquire sites for schoolhouses for primary and intermediate classes through purchases or conditional or absolute donation.\n(g) To establish and maintain or aid in the establishment and maintenance of vocational schools and institutions of higher learning conducted by the National Government or any of its subdivisions or agencies; and, with the approval of the Director of Public Schools, to fix reasonable tuition fees for instruction in the vocational schools and in the institutions of higher learning supported by the city.\n(h) To provide for and maintain an efficient police force for the maintenance of law and order in the city, and make all necessary police ordinances, with a view to the confinement and reformation of vagrants, disorderly persons, mendicants, prostitutes and persons convicted of violating any of the ordinances of the city.\n(i) To maintain the municipal court established by law which shall have jurisdiction of all criminal cases under the ordinances of the city, and such further jurisdiction as may be herein or hereafter conferred.\n(j) To provide for and maintain a city fire department and to establish and maintain engine houses, fire engines, hose trucks, hooks and ladders, and other equipment for the prevention and extinguishment of fires, and to regulate the management and use of the same.\n(k) To establish fire zones, determine the kinds of buildings or structures that may be erected within their limits, regulate the manner of constructing and repairing the same, and fix the fees for permits for the construction, repair, or demolition of buildings and other structures.\n(l) To regulate the use of lights in stables, shops, and other buildings and places and to regulate and restrict the issuance of permits for the building of bonfires and rockets, and other pyrotechnic displays, and to fix the fees for such permits.\n(m) To make regulation to protect the public from conflagrations and to present and mitigate the effects of famine, floods, storage and other public calamities, and provide reliefs to victims thereof.\n(n) To tax, regulate and fix the amount of the license fees for the following: hawkers, peddlers, hucksters, not including hucksters or peddlers who sell only native vegetables, fruits, or foods, personally carried by the hucksters or peddlers, barbers, collecting agencies, manicurists, hair dressers, tattooers, jugglers, acrobats, wrestlers and boxers; shooting galleries, slot machines, merry-go-rounds and other similar riding devices, and the keeping, preparation, and sale of meat, poultry, fish, game, butter, cheese, lard, vegetable, bread, and other provisions; and to impose a municipal occupation tax, not to exceed fifty pesos per annum, on lawyers, medical practitioners, land surveyors, architects, public accountants, civil, electrical, chemical, mechanical, or mining engineers, radio engineers or technicians, veterinarians, dental surgeons, opticians and optometrists, insurance agents and sub-agents, business agents and business consultants, professional appraisers or connoisseurs of tobacco or other domestic of foreign products, music teachers, piano tuners, nurses, and midwives, auctioners, plumbers, electrical contractors, building contractors, massagists, physical culture instructors, chiropodists, money changers, real estate, commercial and other brokers, and persons engaged in the transportation of passengers or freight by hire, including common carriers and transportation contractors: Provided, That persons exercising their profession or occupation only as salaried employees and not as independent practitioners shall be exempt from the municipal occupation tax herein prescribed.\n(o) To tax, fix the license fee and regulate the business of hotels, restaurants, refreshment places, cafes, lodging houses, brewers, distillers, rectifiers, laundries, dyeing, and cleaning establishments, beauty parlors, physical or beauty culture and fashion schools, clubs, livery garages, public warehouses, pawnshops, theaters, cinematographs, and the letting or subletting of lands and buildings, whether used for commercial, industrial or residential purposes; and further to fix the location of, and to tax, fix the license fee on, and regulate the business of, livery stables, boarding stables, embalmers, public billiard tables, public pool tables, bowling alleys, dance halls, public dancing halls, cabarets, night clubs, circuses, and other similar parades, public vehicles, public ferries, cockpits, dealers in second hand material or merchandise, junk dealers, theatrical performances, boxing contests, public exhibitions, blacksmith shops, foundries, steam boilers, lumber yards, shipyards, the storage and sale of gunpowder, tar, pitch, resin, coal, oil, gasoline, benzine, turpentine, hemp, cotton, nitroglycerin, petroleum or any of the products thereof and of all other highly combustible or explosive materials, and other establishments likely to endanger the public safety or give rise to conflagrations or explosions, and subject to the provisions of ordinances issued by the Bureau of Health in accordance with law, tanneries, renderies, tallow chandleries, bone factories, soap factories: Provided, That no license shall be granted to any theater or cinematograph unless the applicant for said license agrees to exhibit pictures made in the Philippines to the extent of five per centum of their annual exhibitions: And Provided, further, That any violation of this condition shall cause the revocation of said license.\n(p) To tax and fix the license fees on printers or bookbinders or both, tailor shops, milliners, manufacturers of jewelry, embroideries, sail or awnings or both, rope, paper, leather goods, including shoes, slippers, sandals, harnesses and valises or bags, sporting goods, rubber goods, plastics and celluloid products, hardware including glasswares, cooking utensils, electrical goods, and construction materials, chemical products including drugs, perfumes, toilet articles, paints, dyes and inks, textiles, shell lamps or lamp shades or both, statuettes or tombstones or both, sacks, furniture of all kinds, including rattan goods, wire, brass beds or both, clothing, hats, eyeglasses or optical goods or both, fertilizers and buttons.\nManufacturers above-mentioned shall not be subject to the payment of any municipal tax or license fee as retail dealers of their own products: Provided, That any manufacturing conducted solely by the immediate members of a family at their own home shall not be subject to any tax or license fee.\n(q) To tax and fix the license fee on dealers in general merchandise, including importers and indentors, except those dealers who may be expressly subject to the payment of some other municipal tax under the provisions of this section.\nDealers in general merchandise shall be classified as (a) wholesale dealers and (b) retail dealers. For purposes of the tax on retail dealers, general merchandise shall be classified into four main classes: namely: (1) luxury articles, (2) semi-luxury articles, (3) essential commodities, and (4) miscellaneous articles. A separate license shall be prescribed for each class but where commodities of different classes are sold in the same establishment, it shall not be compulsory for the owner to secure more than one license if he pays the higher or highest rate of tax prescribed by ordinance. Wholesale dealers shall pay the license tax as such, as may be provided by ordinance.\nFor purposes of this section, the term \"general merchandise\" shall include poultry and livestock, agricultural products, fish and other allied products.\n(r) To tax, fix the license fees on and regulate the sale, trading in or disposal of alcoholic or malt beverages, wines, and mixed or fermented liquors, including tuba, basi, tapuy, offered for retail sale.\n(s) To impose a tax on all products or commodities manufactured or produced in the city and removed therefrom.\n(t) To impose a sales tax of not exceeding one per centum of the gross value in money of all articles sold, bartered, exchanged or transferred within the city.\n(u) To regulate the method of using steam engines and boilers, and all other motive powers other than marine, or belonging to the Government of the Philippines; to provide for the inspection thereof, and fix a reasonable fee for such inspection and to regulate and fix the fees for the licenses of the engineers engaged in operating the same.\n(v) To provide for the prohibition and suppression of riots, affrays, disturbances, and disorderly assemblies; houses of ill-fame and other disorderly houses; gaming houses, gambling and all fraudulent devices for the purpose of obtaining money or property; prostitution, vagrancy, intoxication, fighting, quarreling, and all disorderly conduct; and printing, circulation, exhibition, possession or sale of obscene pictures, books, or publications, and for the maintenance and preservation of peace and good morals.\n(w) To prohibit or regulate and fix the license fees for the keeping of dogs, and to authorize their impounding and destruction when running at large contrary to ordinances, and to tax and regulate the keeping or training of fighting cocks.\n(x) To establish and maintain municipal pounds; to regulate, restrain, and prohibit the running at large of domestic animals, and provide for the distraining, impounding, and sale of the same for the penalty incurred, and the cost of the proceedings; and to impose penalties upon the owners of said animals for the violation of any ordinance in relation thereto.\n(y) To prohibit, and provide for the punishment of, cruelty to animals.\n(z) To require property owners by ordinance to construct or repair, at their expense, sidewalks along the street or streets adjacent to their lots in accordance with the specifications of the city engineer as to quality, width and grade, and subject to his supervision and approval, providing that, in case of failure or inability of the property owners to comply with the requirement within a specified period of time after demand, the city engineer shall cause the work to be done and the cost thereof collected as a special assessment from such owners, who may choose to pay the same in full, or in ten equal yearly installments which shall be due and payable to Danao City in the same manner as the annual tax levied on real estate, and shall be made subject to the same penalties for delinquency, and enforceable by the same remedies, as such annual tax; and all said sums and amounts shall, from the day in which they are assessed, constitute liens on the property against which the same were assessed and shall take precedence over any and all other liens which may exist upon such property excepting only such as may be have been attached as a result of the non-payment of said annual tax.\n(aa) To regulate the inspection, weighing, and measuring of brick, lumber, coal and other articles or merchandise.\n(bb) Subject to the provisions of existing law, to provide for the laying out, construction and improvement, and to regulate the use of streets, avenues, alleys, sidewalks, wharves, piers, parks, cemeteries, and other public places; to provide for lighting, cleaning, and sprinkling of streets, and public places; to regulate, fix license fees for and prohibit the use of the same for processions, signs, signposts, awning, awning posts, and the carrying or displaying of banners, placards, advertisements, or handbills, or the flying of signs, flags or banners whether along, across, over or from buildings along the same; to prohibit the placing, throwing, depositing, or leaving of obstacles of any kind, garbage, refuse, or other offensive matter or matters liable to cause damage in the street and other public places and to provide for the collection and disposition thereof; to provide for the inspection of, fix the license fees for and regulate the openings in the same for the laying of water, sewer and other pipes, the building and repair tunnels, sewers and drains, and all structures in and under the same and the erecting of poles and the stringing of wires therein; to provide for and regulate cross-walks, curbs and gutters thereon; to name streets without a name and provide for and regulate the numbering of houses and lots fronting thereon or in the interior of the blocks; to regulate traffic and sales upon the streets and other public places; to provide for the abatement of nuisances in the same and punish the authors or owners thereof; to provide for the construction and maintenance, and regulate the use of bridges, viaducts, and culverts; to prohibit and regulate ball playing, kite flying, hoop rolling, and other amusements which may annoy persons using the streets and public places, or frighten horses or other animals; to regulate the speed of horse and other animal driven vehicles within the limits of the city.\n(cc) To provide for the construction and maintenance of, and regulate the navigation on, canals and water courses within the city and provide for the cleansing and purification of the same; unless otherwise provided by law, to provide for the construction and maintenance, and regulate the use of public landing places, wharves, piers, docks, and levees, and those of private ownership; and to provide for or regulate the drainage and filling of private premises when necessary in the enforcement of sanitary rules and regulations issued in accordance with law.\n(dd) Subject to the provisions of the Public Service Law, to fix the charges to be paid by all watercraft landing at or using public wharves, docks, levees, or landing places owned, operated, managed or controlled by the city.\n(ee) Any provision of law to the contrary notwithstanding, to provide for the maintenance of waterworks for the purpose of supplying water to the inhabitants of the city, and for the purification of the source of water supply and the places through which the same passes, and to regulate the consumption and use of water; to fix, subject to the provisions of the Public Service Law, and provide for the collection of rents therefor and to regulate the construction, repair and use of hydrants, pumps, cisterns and reservoirs.\n(ff) To provide for the establishment and maintenance and regulate the use of public drains, sewers, latrines and cesspools.\n(gg) Subject to the rules and regulations issued by the Director of Health Services in accordance with law, to provide for the establishment, and maintenance and to fix the fees for the use of, and regulate public stables, laundries and baths, and public markets and prohibit the establishment or operation within the city limits of public markets by any person, entity, association, or corporation other than the city.\n(hh) To establish or authorize the establishment of slaughterhouses, to provide for their veterinary or sanitary inspection, to regulate the use of the name, and to charge reasonable slaughter fees. No fees shall be charge for veterinary or sanitary inspection of meat from large cattle or domestic animals slaughtered outside the city, when such inspection was had at the place where the animals were slaughtered.\n(ii) To regulate, inspect and provide measures preventing any discrimination or the exclusion of any race or races in or from any institution, establishments, or service open to the public within the city limits, or in the sale and supply of gas or electricity, or in the telephone service; to fix and regulate charges therefor where the same has not been fixed by national law, to regulate and provide for the inspection of all gas, electric and telephone, conduits, mains, meters, and other apparatus, and provide for the condemnation, substitution or removal of the same when defective or dangerous.\n(jj) To declare, prevent and provide for the abatement of nuisances; to regulate the ringing of bells and the making of loud or unusual noises; to provide that owners, agents, or tenants of buildings or premises keep and maintain the same in sanitary condition, and that, in case of failure to do so within sixty days from the date a written notice is served, the city health officer shall cause the same to be kept in a sanitary condition, and the cost thereof to be assessed against the owner to the extent of not to exceed sixty per centum of the assessed value, which cost shall constitute a lien against the property; and to regulate and/or prohibit, or fix the license fees for the use of property on or near public ways, grounds, or places, or elsewhere within the city, for display by electric signs or the erection or maintenance of billboards or structures of whatever materials erected, maintained, or used for the display of posters, signs, or other pictorial or reading matter, except signs displayed at the place or places where the profession or business advertised thereby is in whole or in part conducted.\n(kk) To provide for the enforcement of the rules and regulations issued by the Director of Health Services; and by ordinance to prescribe penalties for violation of such rules and regulations.\n(ll) To extend its ordinances over all waters within the city, and over any boat or other floating structures thereon and for the purpose of protecting and insuring the purity of the water supply of the city, over all territory within the drainage area of such water supply, and within one hundred meters of any reservoir, conduit, canal, aqueduct, or pumping station used in connection with the city water service.\n(mm) To regulate any other business or occupation being conducted within the city not specifically mentioned in the preceding paragraphs, and to impose a license fee upon all persons engaged in the same or who enjoy privileges in the city.\n(nn) To fix and regulate the size, speed, and operation of motor and other vehicles within the city; to regulate the lights used on such vehicles; to establish bus stops and terminals; and prohibit and regulate the entrance of provincial public utility vehicles into the city, except those passing through the city.\n(oo) To grant fishing and fishery privileges subject to the provisions of the Fisheries Act.\n(pp) To fix the date of the holding of a fiesta in the city not oftener than once a year and to alter, not oftener than once in three years, the date fixed for the celebration thereof.\n(qq) To enact all ordinances it may deem necessary and proper for the sanitation and safety, the furtherance of the prosperity, and the promotion of the morality, peace, good order, comfort, convenience, and general welfare of the city and its inhabitants, and such others as may be necessary to carry into effect and discharge the powers and duties conferred by this Charter; and to fix penalties for the violation of ordinances, which shall not exceed a two hundred pesos fine or six months imprisonment, or both such fine and imprisonment for a single offense.\n(rr) To exercise the power of eminent domain without the approval of the Department Head concerned or the President of the Philippines, for the following purposes; the construction or extension of roads, streets, sidewalks, bridges, ferries, levees, wharves, or piers, air fields, the construction of public buildings including schoolhouses and the making of necessary improvements in connection therewith; the establishment of parks, playgrounds, plazas, market places, artesian wells, or systems for the supply of water, irrigation, canals and dams, and the establishment of nurseries, breeding centers for animals, health centers hospitals, cemeteries, crematories, drainage systems, cesspools, or sewage system and abattoirs.\n(ss) To dispose by lease or otherwise all lands of the public domain ceded to it by the National Government pursuant to the provisions of Section ninety of this Charter."}},{"id":"PH-H2634-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"Article III The Municipal Board"},"heading":{"en":"Restrictive provisions. -No commercial sign, signboard, or billboard shall be erected or displayed on public lands, prem"},"text":{"en":"Section 16. Restrictive provisions. -No commercial sign, signboard, or billboard shall be erected or displayed on public lands, premises, or buildings. If, after due investigation, and having given the owners on opportunity to be heard, the Mayor should consider any sign, signboard, or billboard displayed or exposed to public view as offensive to the sight or is otherwise a nuisance, he may order the removal of such sign, signboard, or billboard, and if same is not removed within ten days after he has issued such order, he may himself cause its removal, and the sign, signboard, or billboard shall thereupon be forfeited to the city and expenses incident to the removal of the same shall become a lawful charge against any person or property liable for the erection of display thereof."}},{"id":"PH-H2634-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"Article IV Barrio Councils"},"heading":{"en":"Barrio Councils. -In each barrio there shall be organized a barrio council which shall be composed of a barrio lieutenan"},"text":{"en":"Section 17. Barrio Councils. -In each barrio there shall be organized a barrio council which shall be composed of a barrio lieutenant who shall be its chairman, a sub-barrio lieutenant who shall assist the barrio lieutenant in the discharge of his duties, a councilman for livelihood, a councilman for education, and a councilman for health who, in addition to their other duties, will look after the enforcement of laws, ordinances, and resolutions, pertaining to matters comprised within their respective offices and the promotion of the welfare of the barrio. They shall be elected at a meeting to be attended by at least one-third of all the residents of the barrio who are qualified voters. The decision shall take place annually not earlier than the third Saturday of January and not later than the second Saturday of February. The councilor assigned to the barrio shall convoke and preside over the meeting. He shall appoint a board of inspectors and canvassers to conduct the election. The manner of election shall be by secret ballot. Those who obtain the highest number of votes for the position for which they are candidates shall be declared elected and shall assume office immediately: Provided, However, That no person shall be eligible as a candidate for the barrio council unless he has been a resident of the barrio for at-least six months immediately prior to the election, at least twenty years of age at the time of the election, able to read and write and possess the necessary training, experience, and fitness for the position. Any person who is a resident of the barrio and is twenty-one years of age or over and is able to read and write is eligible to vote in the election, provided he has been a resident of the barrio for at least three months prior to the election.\nThe members of the barrio council shall hold office for one year or until their successors are duly elected and qualified. But in no case can he be re-elected for more than four consecutive terms, unless two years have elapsed from the expiration of his last term, in which case he shall again be eligible for election to any barrio office. The councilor may, for cause, recommend to the municipal board the suspension or dismissal of any of the members of the barrio council. They shall not receive any compensation or emolument of any kind.\nThe barrio council shall have the power to promulgate rules not inconsistent with law or ordinances of the municipal board and, subject to the approval of the latter, shall be operative within the barrio. The council shall be responsible for the planning, budgeting and spending of funds belonging to the barrio treasury and shall have the following powers and duties: (a) to represent the barrio in cases in which such representation is not incompatible with the personality of the municipal board; (b) to hold a regular session once a month; (c) to make their own rules of procedure which shall be approved by the councilor concerned; (d) to submit to the municipal board, through said councilor, such suggestions or recommendations as they may see fit for improvements in their place or for the welfare of the inhabitants thereof; (e) to provide for the publication by town crier or such other means as they see fit, of new laws and municipal ordinances; (f) to organize at least three times a year civic lectures tending to generalize information concerning the duties and rights of citizenship; and (g) to cooperate with the government for the success of measures of general interest in their respective barrios. The barrio councilmen may hold their session in the public school building of the barrio during hours when there are no classes, or in any house or lot in the barrio, the provisional or permanent use of which may be granted to them for said purpose free of charge; and shall elect from among their number a secretary who shall prepare short minutes of the proceedings of the council and draft the recommendations or suggestions to be submitted by the same to the municipal council, in either of the official languages of the country or in the local dialect. The barrio council shall also elect from among their number a treasurer who shall collect all fees and contributions due the barrio treasury for which he shall issue the proper receipts. He shall be the custodian of the barrio funds and shall deposit all collections with the City Treasurer within a period of one week after receipt of such fees and contributions. He shall disburse the same in the accordance with resolutions of the municipal board, upon vouchers signed by the payee and approved by the barrio lieutenant with the approval of the municipal board and subject to availability of funds in the barrio treasury. The barrio council may provide for necessary traveling expenses for the barrio lieutenant or any member of the council.\nFor the purposes of this Charter, the poblacion shall be considered a barrio."}},{"id":"PH-H2634-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"Article IV Barrio Councils"},"heading":{"en":"Duties of barrio lieutenants. -The barrio lieutenant shall assist the councilor assigned to such barrio in the performan"},"text":{"en":"Section 18. Duties of barrio lieutenants. -The barrio lieutenant shall assist the councilor assigned to such barrio in the performance of his duties. In the absence or incapacity of the barrio lieutenant, his duties shall be performed by the sub-barrio lieutenant."}},{"id":"PH-H2634-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"Article IV Barrio Councils"},"heading":{"en":"Barrio police force. -There shall be a barrio police force whose members shall be appointed by the Mayor and who, togeth"},"text":{"en":"Section 19. Barrio police force. -There shall be a barrio police force whose members shall be appointed by the Mayor and who, together with the members of the barrio council, shall be deemed agents of person in authority."}},{"id":"PH-H2634-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"Article V Departments and Offices of the City"},"heading":{"en":"City Departments. -There shall be the following city departments over which the Mayor shall have direct control and supe"},"text":{"en":"Section 20. City Departments. -There shall be the following city departments over which the Mayor shall have direct control and supervision, any existing law to the contrary notwithstanding:\n1. Department of Finance\n2. Department of Engineering and Public Works\n3. Law Department\n4. Department of Health\n5. Police Department\n6. Fire Department\n7. Department of Assessment\nThe Municipal Board may from time to time make such readjustment of the duties of the several departments as the public interest may demand, and, with the approval of the President, may consolidate any department, division or office of the city with any other department, division or office."}},{"id":"PH-H2634-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"Article V Departments and Offices of the City"},"heading":{"en":"Powers and duties of heads of departments. -Each head of department of the city government shall be in control of such d"},"text":{"en":"Section 21. Powers and duties of heads of departments. -Each head of department of the city government shall be in control of such department under the direction and supervision of the Mayor, and shall possess such powers that may be prescribed herein or by ordinances. He shall certify to the correctness of all payrolls and vouchers of his department covering the payment of money before payment, except as herein otherwise expressly provided. At least four months before the beginning of each fiscal year, he shall prepare and present to the Mayor an estimate of the receipts and appropriation necessary for the operation of his department for the ensuing fiscal year, and shall submit therewith such information for purposes of comparison as the Mayor may desire. He shall submit to the Mayor as often as required reports covering the operation of his department.\nIn case of the absence or sickness, or inability to act for any other reason, of the head of one of the city departments, or in case of temporary vacancy, the officer next in rank of that department shall perform the duties of the department head concerned."}},{"id":"PH-H2634-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"Article V Departments and Offices of the City"},"heading":{"en":"Appointment and removal of officials and employees. -The President of the Philippines, with the consent of the Commissio"},"text":{"en":"Section 22. Appointment and removal of officials and employees. -The President of the Philippines, with the consent of the Commission of Appointments, shall appoint the judge and auxiliary judge, the city treasurer, the city engineer, the city fiscal and his assistants, the chief of police, the city health officer, the city assessor, the chief of the fire department, the city superintendent of schools, and other heads of such city departments as may be created. Said officers shall not be suspended nor removed except in the manner and for causes provided by law.\nSubject to the provisions of the Civil Service Law, the Mayor shall appoint all other officers and employees paid out of city funds, and they shall be suspended or removed in accordance with law."}},{"id":"PH-H2634-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"Article V Departments and Offices of the City"},"heading":{"en":"Officers not to engage in certain transactions. -It shall be unlawful for any city officer, individually or as a member"},"text":{"en":"Section 23. Officers not to engage in certain transactions. -It shall be unlawful for any city officer, individually or as a member of a firm, to engage in any business transaction with the city, or with any of its authorized officials, boards, agents or attorneys, whereby money is to be paid, out of the resources of the city to such person or firm; or to purchase any real estate or other property belonging to the city, or which shall be sold for taxes or assessments, or by virtue of legal process at the suit of the city; or to be surety for any person having a contract or doing business with the city, for the performance of which security may be required; or to be surety on the official bond of any officer of the city; and shall not be financially interested in any transaction or contract in which the national government or any sub-division or instrumentality thereof is an interested party."}},{"id":"PH-H2634-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"Article VI Relation to Bureau and Offices"},"heading":{"en":"The General Auditing Office. -The Auditor General shall receive and audit all accounts of the city in accordance with th"},"text":{"en":"Section 24. The General Auditing Office. -The Auditor General shall receive and audit all accounts of the city in accordance with the provisions of law relating to government accounts and accounting. The city auditor shall be appointed by the Auditor General and shall receive a salary of four thousand eight hundred pesos per annum to be paid by the national government."}},{"id":"PH-H2634-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"Article VI Relation to Bureau and Offices"},"heading":{"en":"The Bureau of Public Schools. -The Director of Public Schools shall exercise the same jurisdiction and powers in the cit"},"text":{"en":"Section 25. The Bureau of Public Schools. -The Director of Public Schools shall exercise the same jurisdiction and powers in the city as elsewhere in the Philippines, and the city superintendent of schools shall have all the powers and duties in respect to the schools of the city as are vested in division superintendents in respect to schools of their division: Provided, That the salaries of the City Superintendent, teachers and other operational expenses of primary, intermediate, vocational and other public schools shall be borne by the national government."}},{"id":"PH-H2634-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"Article VI Relation to Bureau and Offices"},"heading":{"en":"The Bureau of Supply Coordination. -The Director of Supply Coordination shall purchase and supply in accordance with law"},"text":{"en":"Section 26. The Bureau of Supply Coordination. -The Director of Supply Coordination shall purchase and supply in accordance with law all supplies, equipment, materials and property of every kind, except real estate for the use of the city and any of its departments or offices. But contracts for completed work of any kind for the use of the city or any of its departments or offices, involving both labor and materials where the materials are furnished by the contractor shall not be deemed to be within the purview of this section."}},{"id":"PH-H2634-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"Article VI Relation to Bureau and Offices"},"heading":{"en":"Reports to the Mayor concerning schools. -The city superintendent of schools shall make a quarterly report of the condit"},"text":{"en":"Section 27. Reports to the Mayor concerning schools. -The city superintendent of schools shall make a quarterly report of the conditions of the schools and school buildings of the city to the Mayor, and such recommendations as seem to him wise relative to improving the schools or school buildings in the city."}},{"id":"PH-H2634-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"Article VII Department of Finance"},"heading":{"en":"The City Treasurer—His powers and duties. -There shall be a city treasurer who shall have charge of the department of fi"},"text":{"en":"Section 28. The City Treasurer—His powers and duties. -There shall be a city treasurer who shall have charge of the department of finance and shall act as chief fiscal officer and financial adviser of the city and custodian of its funds. He shall receive a salary of four thousand eight hundred pesos per annum. He shall have the following general powers and duties:\n(a) He shall collect all taxes due the city, all licenses authorized by law or ordinance, all rents due for lands, markets and other property owned by the city, and all further charges of whatever nature fixed by law or ordinance; shall administer markets and slaughterhouses, and shall receive and issue receipts for all costs, fees, fines and forfeitures imposed by the municipal court.\n(b) He shall collect all miscellaneous charges made by the engineering department and by the other departments of the city government, and all charges made by the city engineer for inspections, permits, licenses, and the installations, maintenance, and services rendered in the operation of the private privy system.\n(c) Unless otherwise specifically provided by law or resolution, he shall perform in and for the city the duties imposed by law or resolution upon provincial treasurers in general as well as other duties imposed upon him by law.\n(d) He shall purchase and issue all supplies, equipment or other property required by the city, through the purchasing agent, or otherwise, as may be authorized, subject to the general provisions of law relating thereto.\n(e) He shall be accountable for all funds and property of the city and shall render such accounts in connection therewith as may be prescribed by the Auditor General.\n(f) He shall deposit all city funds and collections in any bank duly designated as Government depository in accordance with the existing rules and regulations.\n(g) He shall disburse the funds of the city in accordance with duly authorized appropriations, upon properly executed vouchers bearing the approval of the chief of the department concerned, and on or before the twentieth day of each month he shall furnish the Mayor and the Municipal Board, for their information, a statement of the appropriation, expenditures, and balances of all funds and accounts as of the last day of the month preceding.\n(h) He shall be the custodian of all moneys released for public works for the city and the first representative district of Cebu, and shall disburse the same."}},{"id":"PH-H2634-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"Article VIII Department of Engineering and Public Works"},"heading":{"en":"The City Engineer—His powers and duties. -There shall be a city engineer who shall have charge of the Department of engi"},"text":{"en":"Section 29. The City Engineer—His powers and duties. -There shall be a city engineer who shall have charge of the Department of engineering and public works. He shall also be ex-officio district highway engineer for the first representative district of the Province of Cebu. He shall receive a salary of four thousand eight hundred pesos per annum. He shall have the following powers and duties:\n(a) He shall have charge of all the surveying and engineering works of the city and the first representative district of the Province of Cebu, care, cleaning and sprinkling of streets, canals and esteros, parks and public grounds, bridges, recreation and playgrounds and shall perform such services in connection with public improvements, or any work entered upon or projected by the city and the first representative district of the Province of Cebu, or any department thereof, as may require the skill and experience of a civil engineer.\n(b) He shall ascertain, record, and establish monuments of the city survey and from thence extend the surveys of the city, and locate, establish, and survey all city and district property, and also private property abutting on the same, whenever directed by the Mayor.\n(c) He shall prepare and submit plans, maps, specifications and estimates for buildings, streets, bridges, docks, and other public works, and supervise the construction and repair of the same.\n(d) He shall make such test and inspection of engineering materials used in construction and repair as may be necessary to protect the city and the district from the use of materials of a poor or dangerous quality.\n(e) He shall have the care of all public buildings, when erected, including markets and slaughterhouses and all buildings rented for city purposes, and of any system now or hereafter established by the city for lighting the streets, public places, or public buildings.\n(f) He shall have the care of all public streets, parks and bridges, and shall maintain and regulate the use of the same for all purposes as provided for by ordinance or law; shall collect and dispose of all garbage, refuse, the contents of closets, vaults, and cesspools, and all other offensive and dangerous substances within the city and, in the event the disposal and collection of such garbage, refuse and other offensive substances has been awarded to a private contractor, the disposal and collection thereof shall be under the supervision of the city engineer.\n(g) He shall have the care and custody of all public docks, wharves, piers, levees, and landing places owned by the city and the district.\n(h) He shall prevent the encroachment of private buildings and fences on the streets and public places of the city and district.\n(i) He shall have general supervision and inspection of all private docks, wharves, piers, levees, and landing places, and other property bordering on the harbor, river, esteros, and waterways of the city and district, and shall issue permits for the construction, repair and removal of the same, and enforce all ordinances relating to the same.\n(j) He shall have the care and custody of the public system of waterworks and sewers, and all sources of water supply, and shall control, maintain, and regulate the use of the same, in accordance with the ordinance relating thereto; shall inspect and regulate the use of all private system for supplying water to the city and district and its inhabitants, and all private sewers and their connections with the public sewers systems.\n(k) He shall supervise the laying of mains and connections for the purpose of supplying gas to the inhabitants of the city district.\n(l) He shall inspect and report upon the conditions of public property and public works whenever required by the Mayor or the Department of Public Works and Communications.\n(m) He shall supervise and regulate the location and use of engines, boilers, forges, and other manufacturing and heating appliances in accordance with law and ordinance relating thereto. He is authorized to charge fees, at rates to be fixed by the Municipal Board, for the sanitation and transportation services and supplies furnished by his department.\n(n) He shall inspect and supervise the construction, repair, removal, and safety of private buildings, and regulate and enforce the numbering of houses in accordance with the ordinances of the city.\n(o) With the previous approval of the Mayor in each case, he shall order the removal of buildings and structures erected in violation of the ordinances; shall order the removal of materials employed in the construction or repair of any building or structure made in violation of said ordinances; and shall cause buildings and structures dangerous to the public to be made secure or torn down.\n(p) He shall file and preserve all maps, plans, notes, surveys and other papers and documents pertaining to his office."}},{"id":"PH-H2634-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"Article VIII Department of Engineering and Public Works"},"heading":{"en":"Execution of authorized public works and improvements. -All repair or construction of any work or public improvements, e"},"text":{"en":"Section 30. Execution of authorized public works and improvements. -All repair or construction of any work or public improvements, except parks, boulevards, streets or alleys, involving an estimated cost of three thousand pesos or more shall be awarded by the Mayor upon the recommendation of the city engineer to the lowest responsible bidder after public advertisement by posting notices of the call for bids in conspicuous places in the City Hall and by publication in the Official Gazette, both for not less than ten days: Provided, However, That the city engineer may, with the approval of the President of the Philippines, upon the recommendation of the Secretary of Public Works and Communications, execute by administration any such public work costing three thousand pesos or more.\nIn case of public works involving an expenditure of less than three thousand pesos, it shall be discretionary with the city engineer either to proceed with the work himself or to let the contract to the lowest bidder after such publication and notice as shall be deemed appropriate or as may be, by regulations, prescribed."}},{"id":"PH-H2634-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"Article IX Law Department"},"heading":{"en":"The City Fiscal—His powers and duties. -There shall be a city fiscal who shall discharge his duties under the general su"},"text":{"en":"Section 31. The City Fiscal—His powers and duties. -There shall be a city fiscal who shall discharge his duties under the general supervision of the Secretary of Justice.\nThe City Fiscal shall receive a salary of four thousand eight hundred pesos per annum. There shall be an assistant City Fiscal who shall receive a salary of four thousand two hundred pesos per annum. The City Fiscal shall be the chief legal adviser of the city and all offices and departments thereof. He shall have the following powers and duties.\n(a) He shall, personally or through any assistant, represent the city in all civil cases wherein the city or any officer thereof, in his official capacity, is a party, and shall prosecute and defend all civil actions related to or connected with any city office or interest.\n(b) He shall, when directed by the Mayor, institute and prosecute in the city’s interest a suit on any bond, or contract, and upon any breach or violation thereof.\n(c) He shall, when requested, attend meetings of the Board, draw ordinances, contracts, bonds, leases, and other instruments involving any interest of the city, and inspect and pass upon any such instruments already drawn.\n(d) He shall give his opinion in writing, when requested by the Mayor or the Board or any of the heads of the city departments, upon any question relating to the city or the rights, or duties of any city officer thereof.\n(e) He shall, whenever it is brought to his knowledge that any city officer or employee is guilty of neglect or misconduct in office, or that any person, firm, or corporation holding or exercising any franchise or public privilege from the city, has failed to comply with any condition, or to pay any consideration mentioned in the grant of such franchise or privilege, investigate or cause to be investigated the same and report to the Mayor.\n(f) He shall have charge of the prosecution of all crimes and violations of the city ordinances, in the municipal court of the city or the Court of First Instance and shall discharge all the duties in respect to criminal prosecution as are enjoined by law upon provincial fiscals.\n(g) The city fiscal shall cause to be investigated all charges of crimes, misdemeanors, and violations of laws and city ordinances and have the necessary informations or complaints prepared or made against the accused. He or any of his assistants may conduct such investigations by taking oral evidence of reputed witnesses, and for this purpose may issue subpoena to summon witnesses to appear and testify under oath before him, and subpoena duces tecum for the production of documents and other evidence. The attendance of an honest or recalcitrant witness may be enforced by application for a warrant of arrest to the municipal court or to the Court of First Instance.\n(h) The city fiscal shall also cause to be investigated the cause of sudden deaths which have not been satisfactorily explained and when there is suspicion that the cause arose from the unlawful acts or omissions of other persons, or from foul play. For that purpose, he may cause autopsies to be made in case it is deemed necessary and shall be entitled to demand and receive for the purpose of such investigations or autopsies the aid of the city health officer.\n(i) He shall at all times render such professional services as the Mayor or the Municipal Board may require, and shall have such powers and perform such duties as may be prescribed by law or ordinance.\n(j) He shall act as register of deeds for the city."}},{"id":"PH-H2634-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"Article X Department of Health"},"heading":{"en":"The City Health Officer—His powers and duties. -There shall be a city health officer who shall have charge of the depart"},"text":{"en":"Section 32. The City Health Officer—His powers and duties. -There shall be a city health officer who shall have charge of the department of health and shall receive a salary of four thousand eight hundred pesos per annum. He shall have the following powers and duties:\n(a) He shall have general supervision over the health and sanitary condition of the city, including the cleaning of crematories, cemeteries, stockyards, slaughterhouses, and markets.\n(b) He shall execute and enforce all laws, ordinances and regulations relating to the public health.\n(c) He shall recommend to the Municipal Board the passage of such ordinances as he may deem necessary for the preservation of the public health.\n(d) He shall cause to be prosecuted all violations of sanitary laws, ordinances, or regulations.\n(e) He shall make sanitary inspections and may be aided therein by such members of the police force of the city or the national police as shall be designated as sanitary police by the chief of police or proper national police officer and such sanitary inspectors as may be authorized by law.\n(f) He shall keep a civil register for the city and shall record therein all births, marriages and deaths with their respective dates.\n(g) He shall have control and supervision over puericulture centers and social services of the city.\n(h) He shall perform such other duties, not repugnant to law or ordinance, with reference to the health and sanitation of the city as the Director of Health Services shall direct. In case of epidemic or when the inhabitants of the city are menaced by any infectious or contagious diseases, the Director of Health Services shall assume full control of the health and sanitation services of the city until such condition shall have ceased to exist."}},{"id":"PH-H2634-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"Article XI Police Department"},"heading":{"en":"The Chief of Police—His powers and duties. -There shall be a chief of police who shall have charge of the police departm"},"text":{"en":"Section 33. The Chief of Police—His powers and duties. -There shall be a chief of police who shall have charge of the police department and shall receive a salary of four thousand eight hundred pesos per annum. No person shall be appointed as Chief of Police unless he is or has been a regular or reserve officer of the Armed Forces of the Philippines with a rank of captain at least. He shall have the following powers and duties:\n(a) He may issue supplementary regulations not incompatible with law or general regulations promulgated by the proper department head of the national government, in accordance with law, for the government of the city police and detective force.\n(b) He shall quell riots, disorders, disturbances of the peace, and shall arrest and prosecute through the city fiscal, violators of law or ordinances; shall exercise exclusive police supervision over all land and water within the police jurisdiction of the city; shall be charged with the protection of the rights of persons and property wherever found within the jurisdiction of the city, and shall arrest when necessary to prevent the escape of offenders and violators of any law or ordinance, and all who obstruct or interfere with him in the discharge of his duty; shall have charge of the city prison; and shall be responsible for the safekeeping of all prisoners until they shall be released from custody, in accordance with law, or delivered to the warden of the proper prison or penitentiary.\n(c) He may take good and sufficient bail for the appearance before the judge of the municipal court of any person arrested for violation of any city ordinance: Provided, However, That he shall not exercise this power in cases of violations of any penal law, except when the fiscal of the city shall also recommended and fix the bail to be required of the person arrested.\n(d) He shall have authority, within the police limits of the city, to serve and execute criminal processes of any court.\n(e) He shall be the deputy sheriff of the city, and as such he shall, personally or the representative, attend the sessions of the municipal court, and shall execute promptly and faithfully all writs and processes of said court.\n(f) He shall exercise supervision over the police training school established in accordance with the rules and regulations of the police departments.\n(g) He shall have such further powers and perform such further duties as may be prescribed by law or ordinance."}},{"id":"PH-H2634-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"Article XI Police Department"},"heading":{"en":"Secret Service. -The Chief of Police shall be ex officio chief of the secret service. He shall take charge of the detect"},"text":{"en":"Section 34. Secret Service. -The Chief of Police shall be ex officio chief of the secret service. He shall take charge of the detective work of the department and of the detective force of the city, and shall perform such other duties as may be assigned to him by law or ordinance."}},{"id":"PH-H2634-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"Article XI Police Department"},"heading":{"en":"Peace officers—their powers and duties. -The Mayor, the chief of police, and all officers and members of the city police"},"text":{"en":"Section 35. Peace officers—their powers and duties. -The Mayor, the chief of police, and all officers and members of the city police and detective force shall be peace officers. Such peace officers are authorized to serve and execute all processes of the municipal court and criminal processes of all other courts to whomsoever directed within the jurisdictional limits of the city or within the police limits as hereinbefore defined; within the same territory, to pursue and arrest, without warrant, any person found in suspicious places or under suspicious circumstances reasonably tending to show that such person has committed, or is about to commit, a crime or breach of the peace; to arrest or cause to be arrested, without warrant, any offender when the offense is committed in the presence of a peace officer or within his view; and, in such pursuit or arrest, to enter any building, ship, boat, or vessel or take into custody any person therein suspected of being concerned in such crime or breach of the peace, and any property suspected of having been stolen; and to exercise such other powers and perform such other duties as may be prescribed by law or ordinance. They shall detain an arrested person only in accordance with the provisions of existing laws relative to such detention. Whenever the Mayor shall deem it necessary to avert danger or to protect life and property, in case of riot, disturbance, or public calamity, or when he has reason to fear any serious violation of law and order, he may call upon the provincial commander or other members of the Armed Forces of the Philippines. Except upon the occurrence of any such conditions, police jurisdiction and supervision and the preservation of peace and order shall pertain exclusively to the peace officers herein mentioned, existing law to the contrary notwithstanding."}},{"id":"PH-H2634-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"Article XII Fire Department"},"heading":{"en":"Chief of Fire Department. -There shall be a chief of fire department who shall have the management and control of all ma"},"text":{"en":"Section 36. Chief of Fire Department. -There shall be a chief of fire department who shall have the management and control of all matters relating to the administration, organization, government, discipline, and disposition of the fire forces. He shall receive a salary of four thousand two hundred pesos per annum. The chief of police shall act as Chief of the Fire Departments ex officio until the Municipal Board, by ordinance, provides otherwise, at which time the Chief of the Fire Department shall be appointed as heretofore provided. The Chief of the Fire Department shall have the following powers:\n(a) He shall issue supplementary regulations not incompatible with law or general regulations issued by the proper department head of the national government in accordance with law, for the governance of the fire force.\n(b) He shall have charge of the fire-engine houses, the fire engines, hose trucks, hooks and ladders, trucks and all other fire apparatus.\n(c) He shall have full police powers in the vicinity of fires.\n(d) He shall have authority to remove or demolish any building or other property whenever it shall become necessary to prevent the spreading of fire or to protect adjacent property.\n(e) He shall investigate and report to the Mayor upon the origin and cause of all fires occurring within the city.\n(f) He shall inspect all buildings erected or under construction or repair within the city and determine whether they provide sufficient protection against fire and comply with the ordinances relating thereto.\n(g) He shall have charge of the city telegraph, telephone and fire alarm service.\n(h) He shall have exclusive power, notwithstanding any provision of law to the contrary, to supervise and regulate stringing, grounding, and installation of wires for all electrical connections with a view to avoiding conflagrations, interference with public traffic or safety, or the necessary operation of the fire department.\n(i) He shall condemn all defective electrical installations and shall take the necessary steps to effect immediate corrective action, informing the Mayor of the action thus taken.\n(j) He shall supervise the manufacture, storage, and use of petroleum, gas, acetylene, gunpowder, and other highly combustible matter and explosives.\n(k) No permit for the construction or repair of buildings within the city shall be granted unless the plans relative thereto have been approved by the chief of the fire department. He shall have the power to alter or disapprove such plans as do not provide for adequate protection against the occurrence of fires.\n(l) He shall have such other powers and perform such duties as may further be prescribed by law or ordinance."}},{"id":"PH-H2634-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"The City Assessor—His powers and duties. -There shall be a city assessor who shall have charge of the department of asse"},"text":{"en":"Section 37. The City Assessor—His powers and duties. -There shall be a city assessor who shall have charge of the department of assessment and who shall receive a salary of four thousand eight hundred pesos per annum. The city treasurer shall act as a city assessor ex officio until the Municipal Board, by ordinance, provides otherwise, at which time the city assessor shall have the following powers and duties:\n(a) The city assessor and his authorized deputies are empowered to administer any oath to be administered in connection with the valuation of real estate for the assessment and collection of taxes.\n(b) He shall make a list of the taxable real estate in the city, arranging in the order of the lot and block numbers the names of the owners thereof, with a brief description of the property opposite each such name and the cash value thereof. In making this list, the city assessor shall take into consideration any sworn statement made by the owners of the property, but shall not be prevented thereby from considering any other evidence on the subject and exercising his own judgment in respect thereto. For the purpose of completing this list, he and his representatives may enter upon the real estate for the purpose of examining and measuring it, and may summon witnesses, administer oaths to them, and subject them to examination concerning the ownership and the amount of real estate and its cost value.\n(c) He may, if necessary, examine the records of the register of deeds of the province showing the ownership of real estate in the city."}},{"id":"PH-H2634-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Real estate exemption from taxation. -The following shall be exempted from taxation:"},"text":{"en":"Section 38. Real estate exemption from taxation. -The following shall be exempted from taxation:\n(a) Lands or buildings owned by the National Government or Danao City, and burying grounds, churches, and adjacent parsonages and convents, and lands or buildings used exclusively for religious, charitable, scientific, or educational purposes, and not for profit.\n(b) Lands or buildings which are the only real property of the owner, and the value of which does not exceed four hundred pesos.\n(c) Machinery which term shall embrace machines, mechanical contrivances, instruments, appliances, and apparatus attached to the real estate, used for industrial, agricultural or manufacturing purposes, during the first two years of the operation of the machinery."}},{"id":"PH-H2634-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Declaration to be made by persons acquiring or improving real estate. -It shall be the duty of each person who, at any t"},"text":{"en":"Section 39. Declaration to be made by persons acquiring or improving real estate. -It shall be the duty of each person who, at any time, acquires real estate in the city, and of each person who constructs or adds to any improvements on real estate owned by him in the city, to prepare and present to the city assessor within a period of sixty days next following such acquisition, construction or addition, a sworn declaration setting forth the value of the real estate acquired or the improvement constructed or addition made by him and a description of such property sufficient to enable the city assessor readily to identify the same. Any person having acquired real estate who fails to make and present the declaration herein required within the period of sixty days shall be deemed to have waived his right to notice of the assessment of such property and the assessment of the same in the name of its former owner shall in all cases, be valid and binding on all persons interested, and for all purposes, as though the same has been assessed in the name of its present owner."}},{"id":"PH-H2634-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Action when owner makes no returns, or is unknown, or ownership is in dispute or in doubt, or when land and improvements"},"text":{"en":"Section 40. Action when owner makes no returns, or is unknown, or ownership is in dispute or in doubt, or when land and improvements are separately owned. -If the owner of any parcel of real estate shall fail to make a return thereof, or if the city assessor is unable to discover the owner of any real estate, he shall nevertheless list the same for taxation, and charge the tax against the true owner, if known, and if unknown, then as against an unknown owner. In case of doubt or dispute as to the ownership of real estate, the taxes shall be levied against the possessor or possessors thereof. When it shall appear that there are separate owners of the land and the improvements thereon, a separate assessment of the property shall be made."}},{"id":"PH-H2634-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Action in case of estate has escaped taxation. -If it shall come to the knowledge of the city assessor that any taxable"},"text":{"en":"Section 41. Action in case of estate has escaped taxation. -If it shall come to the knowledge of the city assessor that any taxable real estate in the city has escaped listing, it shall be his duty to list and value the same at the time and in the manner provided in the next succeeding section and to charge against the owner thereof the taxes due for the current year and the last preceding one year, and the taxes thus assessed shall be legal and collectible by all the remedies herein provided, and if the failure of the city assessor to assess such taxes at the time when they should have been assessed was due to any fault or negligence on the part of the owner of such property, the penalties shall be added to such back taxes as though they had been assessed at the time when they should have been assessed."}},{"id":"PH-H2634-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"When assessment may be increased or reduced. -The city assessor shall, during the first fifteen days of January of each"},"text":{"en":"Section 42. When assessment may be increased or reduced. -The city assessor shall, during the first fifteen days of January of each year, add to his list of taxable real estate in the city the value of the improvements placed upon such property during the preceding year, and any property which is taxable and which was theretofore escaped taxation. He may during the same period revised and correct the assessed value of any or all parcels of real estate in the city which are not assessed at their true money value, by reducing or increasing the existing assessment as the case may be."}},{"id":"PH-H2634-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Publication of complete list and proceedings thereon. -The city assessor shall, after the list shall have been completed"},"text":{"en":"Section 43. Publication of complete list and proceedings thereon. -The city assessor shall, after the list shall have been completed, inform the public by notice published for seven days in a newspaper of general circulation in the city, if any, and by notice posted for seven days at the main entrance of the City Hall, that the list is one file in his office and may be examined by any persons interested therein, and that upon the date fixed in the notice, which shall not be later than the tenth day of February, the city assessor will be in his office for the purpose of hearing complaints as to the accuracy of the listing of the property and the assessed value thereof. He shall further notify in writing each person the amount of whose tax will be changed by such proposed revision by delivering or mailing at least thirty days in advance of the date fixed in the notice, such notification to such person or his authorized agent at the last known address of such owner or agent in the Philippines.\nIt shall be his duty carefully to preserve and record in his office copies of said notice. On the day fixed in the notice, and for five days thereafter, he shall be present in his office to hear all complaints filed within the period by persons against whom taxes have been assessed as owners of real estate, and he shall make his decision forthwith and enter the same in a well-bound book, to be kept by him for that purpose, and if he shall determine that injustice had been done or errors have been committed he is authorized to amend the list in accordance with his findings."}},{"id":"PH-H2634-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"City Assessor to authenticate list of real estate assessed. -The city assessor shall authenticate each list of real esta"},"text":{"en":"Section 44. City Assessor to authenticate list of real estate assessed. -The city assessor shall authenticate each list of real estate valued and assessed by him as soon as the same is completed, by signing the following certificate at the foot thereof:\n\"I hereby certify that the foregoing list contains a true statement of the piece or pieces of taxable real estate belonging to each person named in the list, and its true cash value, and that no real estate taxable by law in Danao City has been omitted from the list, according to the best of my knowledge and belief.\n____________________\n(Signature of City Assessor)\""}},{"id":"PH-H2634-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Time and manner of appealing to City Board of Tax Appeals. -There shall be a city Board of Tax Appeals which shall be co"},"text":{"en":"Section 45. Time and manner of appealing to City Board of Tax Appeals. -There shall be a city Board of Tax Appeals which shall be composed of five members to be appointed by the President of the Philippines with the consent of the Commission on Appointments. Three members of the Board shall be selected from among government officials in the city other than those in charge of assessment and they shall serve without additional compensation.\nThe two other members shall be selected from among property owners in the city and they shall each receive a compensation of ten pesos for each day of session actually attended. The Chairman of the Board shall be designated in the appointment and shall have the power to designate any city official or employee to serve as the secretary of the Board without additional compensation.\nThe members of the City Board of Tax Appeals shall hold office for a term of two years unless sooner removed by the President of the Philippines."}},{"id":"PH-H2634-A46","no":46,"noLabel":{"en":"Section 46."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Oath to be taken by member of the City Board of Tax Appeals. -Before organizing as such, the members of the City Board o"},"text":{"en":"Section 46. Oath to be taken by member of the City Board of Tax Appeals. -Before organizing as such, the members of the City Board of Tax Appeals shall take the following oath before the Municipal Judge or any other officer authorized to administer oaths:\n\"I do solemnly swear (or affirm) that I will bear and determine well and truly all matters and issues between taxpayers and the city assessor submitted for my decision. So help me God. (In case of affirmation the last words are to be stricken out.)\n____________________\n(Signature)\n\"Subscribed and sworn to (or affirm) before me this ________ day ____________________________, 19_______\n____________________\n(Signature and title of officer administering oath)\""}},{"id":"PH-H2634-A47","no":47,"noLabel":{"en":"Section 47."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Proceedings before the City Board of Tax Appeals and the Department Head. -The City Board of Tax Appeals shall hold such"},"text":{"en":"Section 47. Proceedings before the City Board of Tax Appeals and the Department Head. -The City Board of Tax Appeals shall hold such number of sessions as may be authorized by the Secretary of Finance, and shall hear and decide all appeals duly transmitted to it. It shall have authority to cause to be amended the listing and valuation of the property in respect to which any appeal has been perfected by order signed by the Board or a majority thereof, and transmit it to the city assessor who shall amend the tax list in conformity with said order. It shall also have the power to revise and correct, with the approval of the Department Head first had, any and all erroneous or unjust assessments and valuations for taxation, and make a correct and just assessment and state the true valuation, in each case when it decides that the assessment previously made is erroneous or unjust. The assessment when so corrected shall be as lawful and valid for all purposes as through the assessment had been made within the time herein prescribed. Such reassessment and revaluation shall be made on due notice to the individual concerned who shall be entitled to be heard by the City Board of Tax Appeals before any reassessment or revaluation is made. The decision of the City Board of Tax Appeals shall be final unless the Department Head declares the decision reopened for review by him, in his case, he may make such revision or revaluation as in his opinion the circumstances justify. Such revision when approved by the President of the Philippines shall be final."}},{"id":"PH-H2634-A48","no":48,"noLabel":{"en":"Section 48."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Taxes on real estate—Extension and remission of the tax. -A tax, the rate of which shall not exceed one and one-half per"},"text":{"en":"Section 48. Taxes on real estate—Extension and remission of the tax. -A tax, the rate of which shall not exceed one and one-half per centum ad valorem to be determined by the Municipal Board, shall be levied annually on the assessed value of all real estate in the city subject to taxation. All taxes on real estate for any year shall be due and payable annually on the first day of January and from this date such taxes together with all penalties accruing thereto shall constitute a lien on the property subject to such taxation.\nSuch lien shall be superior to all other liens, mortgages or encumbrances of any kind whatsoever; and shall be enforceable against the property whether in the possession of the delinquent or any subsequent owner, and can only be removed by the payment of the tax and penalty.\nAt the option of the taxpayer, the tax for any year may be paid in two installments to be fixed annually by the Municipal Board simultaneously with the rate per centum ad valorem taxation: Provided, That the time limit for the first and second installments shall be set at not later than the thirty-first day of May and the thirty-first day of October of each year, respectively.\nAny person, who on the last day set for the payment of the real estate tax as provided in the preceding paragraphs, shall be within the premises of the City Hall willing and ready to pay the tax but is unable to effect it on account of the large number of taxpayers therein present, shall be furnished a properly prescribed card which will entitle him to pay the tax without penalty on the following day.\nThe words \"paid under protest\" shall be written on the face of the real estate tax receipt upon the request of any person willing to pay the tax under protest. Confirmation in writing of an oral protest shall be made within thirty days.\nAt the expiration of the time for the payment of the real estate tax without penalty, the taxpayer shall be subject, from the first day of delinquency, to the payment of a penalty at the rate of two per centum for each full month of delinquency that has expired, on the amounts of the original tax due, until the tax shall have been paid in full or until the property shall have been forfeited to the city as provided in this Act: Provided, That in no case shall the total penalty exceed twenty-four per centum of the original tax due.\nIn the event that the crop is extensively damaged or that a great lowering of prices of products is registered in any year, or that a similar disaster extends throughout the province, or for other good and sufficient reason, the Municipal Board may, by resolution passed on or before the thirty-first day of December of each year, extend the time for the collection of the tax on real estate in the city for a period of not to exceed three months, or remit wholly or in part the payment of the tax penalty for the ensuing year, but such resolution shall have to specify clearly the grounds for such extension or remission and shall not take effect until it shall have been approved by the Department Head.\nThe President of the Philippines may, in his discretion, remit or reduce the real estate taxes for any year in the city if he deems this to be in the public interest."}},{"id":"PH-H2634-A49","no":49,"noLabel":{"en":"Section 49."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Seizure of the personal property for delinquency in payment of the tax. -After a property shall have become delinquent i"},"text":{"en":"Section 49. Seizure of the personal property for delinquency in payment of the tax. -After a property shall have become delinquent in the payment of taxes and said taxes and the corresponding penalty or penalties shall remain unpaid ninety days after payment thereof shall have become due, the city treasurer or his deputy, if he desires to compel payment through seizure of any personal property of any delinquent person or persons, shall issue a duly authenticated certificate, based on the records of his office, showing the fact of delinquency and the amount of the tax and penalty due from said delinquent person or persons or from each of them. Such certificate shall be sufficient warrant for the seizure of the personal property belonging to the delinquent person or persons in question not exempt from seizure; and these proceedings may be carried out by the city treasurer, his deputy, or any other officer authorized to carry out legal proceedings."}},{"id":"PH-H2634-A50","no":50,"noLabel":{"en":"Section 50."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Personal property exempt from seizure and sale for delinquency. -The following personal property shall be exempt from se"},"text":{"en":"Section 50. Personal property exempt from seizure and sale for delinquency. -The following personal property shall be exempt from seizure, sale and execution for delinquency in the payment of the real estate tax:\n(a) The tools and implements necessarily used by the delinquent in his trade or employment.\n(b) Two horses or two cows, or two carabaos, or other beasts of burden, such as the delinquent may select, and necessarily used by him in his ordinary occupation.\n(c) His necessary clothing and that of his family.\n(d) Household furniture and utensils necessary for housekeeping, and used for that purpose by the delinquent, such as he may select, of a value not exceeding two hundred pesos.\n(e) Provisions for individual or family sufficient for three months.\n(f) The professional libraries of lawyers, judges, physicians, pharmacists, dentists, engineers, surveyors, clergymen, school teachers, and music teachers, not exceeding five hundred pesos in value.\n(g) One fishing boat and net, the property of any fisherman, by the lawful use of which he earns a livelihood.\n(h) So much of the earnings of the delinquent for his personal services within the month preceding the levy as are necessary for the support of his family.\n(i) Lettered gravestones.\n(j) All moneys, benefits, privileges, or annuities accruing or in any manner growing out of any life insurance, if the annual premiums paid do not exceed five hundred pesos, and if they exceed that sum, a like exemption shall exist which shall bear the same proportion to the moneys, benefits, privileges, and annuities so accruing or growing out of such insurance that said five hundred pesos bears to the whole annual premiums paid.\n(k) Any article or material which forms part of a home or of any improvements on any real estate."}},{"id":"PH-H2634-A51","no":51,"noLabel":{"en":"Section 51."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"The owner may redeem personal property before sale. -The owner of the personal property seized may redeem the same from"},"text":{"en":"Section 51. The owner may redeem personal property before sale. -The owner of the personal property seized may redeem the same from the collecting officer at any time after seizure and before sale by tendering to him the amount of the tax, the penalty, and the costs incurred up to the time of tender. The cost to be charged in making such seizures and sale shall only embrace the actual expense of seizure and preservation of the property pending the sale, and no charge shall be imposed for the services of the collecting officer or his deputy."}},{"id":"PH-H2634-A52","no":52,"noLabel":{"en":"Section 52."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Sale of seized personal property. -Unless redeemed as hereinbefore provided, the property seized through proceedings und"},"text":{"en":"Section 52. Sale of seized personal property. -Unless redeemed as hereinbefore provided, the property seized through proceedings under Section forty-nine hereof, shall, after due advertisement, be exhibited for sale at public auction and so much of the same as shall satisfy the tax, penalty and cost of seizure and sale, shall be sold to the highest bidder. The purchaser at such sale shall acquire an indefeasible title to the property sold.\nThe advertisement shall state the time, place and cause of sale, and be posted for ten years prior to the date of the auction, at the main entrance of the City Hall and at a public and conspicuous place in the district where the property was seized.\nThe sale shall take place, at the discretion of the city treasurer or his deputy, either at the main entrance of the City Hall or at the district where the property was seized. If no satisfactory bid is offered in the aforementioned place another auction shall be had upon notice published anew."}},{"id":"PH-H2634-A53","no":53,"noLabel":{"en":"Section 53."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Return of officer—Disposal of surplus. -The officer directing the sale under the preceding section shall forthwith make"},"text":{"en":"Section 53. Return of officer—Disposal of surplus. -The officer directing the sale under the preceding section shall forthwith make return of his proceedings, and note thereof shall be made by the city treasurer in his records. Any surplus resulting from the sale over and above the tax, penalty and cost, and any property remaining in possession of the officer shall be returned to the taxpayer on account of whose delinquency the sale has been made."}},{"id":"PH-H2634-A54","no":54,"noLabel":{"en":"Section 54."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Vesting title to real estate in the city government. -Upon the expiration of one year from the date on which the taxpaye"},"text":{"en":"Section 54. Vesting title to real estate in the city government. -Upon the expiration of one year from the date on which the taxpayer became delinquent, and in the event of continued default in the payment of the tax and penalty, all private rights, titles and interest in and to the real estate on which said tax is delinquent, shall be indefeasibly vested in the city government, subject only to the rights of redemption and repurchase hereinafter provided for: Provided, That the title acquired by said city government to real estate shall not be superior to the title thereto of the original owner prior to the seizure thereof."}},{"id":"PH-H2634-A55","no":55,"noLabel":{"en":"Section 55."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Redemption of real estate before seizure. -At any time after the delinquent shall have occurred, but not after the expir"},"text":{"en":"Section 55. Redemption of real estate before seizure. -At any time after the delinquent shall have occurred, but not after the expiration of ninety days from the date of the publication of the advertisement provided for in the next succeeding section, the owner or his lawful representative, or any person having any lien, right, or any other legal or equitable interest in said property, may pay the taxes and penalties accrued and thus redeem the property. Such redemption shall operate to divest the city government of its title to the property in question and to revert the same to the original owner, but when such redemption shall be made by a person other than the owner, the payment shall constitute a lien on the property, and the person making such payment shall be entitled to recover the same from the original owner, or if he be a lessee, he may retain the amount of said payment from the proceeds of any income due to the owner of such property: Provided, That the person exercising the right of redemption shall not acquire a title to said property better than that of the original owner prior to the seizure."}},{"id":"PH-H2634-A56","no":56,"noLabel":{"en":"Section 56."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Notice of seizure of real estate. -Notice of the seizure of real estate shall be given by posting notices at the main en"},"text":{"en":"Section 56. Notice of seizure of real estate. -Notice of the seizure of real estate shall be given by posting notices at the main entrance of the city hall, the provincial capitol building, and all the municipal buildings in the Province of Cebu, in English and Spanish and in the dialect commonly used in the locality, and a copy of said notice shall be sent by registered mail to the owner of the property. A copy of said notice shall also be posted in the property subject to seizure. Such notices shall state the name of the delinquent person, the date on which such delinquency commenced, the amount of the taxes and penalties then due, and shall state that unless such taxes and penalties are paid within ninety days from the date of publication of such notice, the forfeiture of the delinquent real estate to the city government shall become absolute."}},{"id":"PH-H2634-A57","no":57,"noLabel":{"en":"Section 57."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Ejectment of occupants of seized property. -After the expiration of ninety days from the date of the publication of the"},"text":{"en":"Section 57. Ejectment of occupants of seized property. -After the expiration of ninety days from the date of the publication of the notice of delinquency provided for in the next preceding section, the city treasurer, or his deputy, may issue to the Mayor or to other officers authorized by law to execute and enforce the laws a certificate describing the parcel of real estate on which the taxes have been declared delinquent, stating the amount of taxes due, and the penalties and costs accrued by reason of the delinquency, and requesting him to eject from said property all the tenants and occupants thereof. Upon receiving such certificate, the Mayor or any other official authorized to enforce the law shall forthwith have all the tenants and occupants who refused to recognize the title of the city expelled from the property in question, and to that end he may use the police force: Provided, However, That if the property so seized is, or includes, a residential home, the occupant thereof shall be given sufficient time, not exceeding ten days from the date of the notice of ejectment, to vacate the premises."}},{"id":"PH-H2634-A58","no":58,"noLabel":{"en":"Section 58."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Redemption of real property before sale. -After the time to the property shall have become vested in the city government"},"text":{"en":"Section 58. Redemption of real property before sale. -After the time to the property shall have become vested in the city government in the manner provided for in the preceding sections, and at any time prior to the sale or the execution of the contract of sale by the city treasurer to a third party, the original owner or his authorized representative or any person having any lien, right, or other legal interest or equity in said property, shall have the right to redeem the entire property in question, by paying the full amount of taxes and penalties due thereon at the time of the seizure, and if the city treasurer shall have entered into a lease of the property, the redemption shall be made subject to such lease: Provided, That the payment of the price of sale, may, at the discretion of the purchaser, be made in installments, extending over a period not exceeding twelve months, but the initial payment, which must be made on the date of the filing of the application for redemption, and every subsequent payment, shall not be less than twenty-five per centum of the entire sum due, and shall in no case be less than two pesos, unless the total or the balance of the amount due on all seized property in the name of the taxpayer is less than two pesos. The purchaser may occupy the property after paying the first installment, and the usual taxes on the property shall be payable in the year after that in which the application for redemption was approved. Any failure of the purchaser to pay an installment on the date it is due shall have the effect of a forfeiture to the city government of any partial payment made by said purchaser, and in case he has taken possession of the property, he will forthwith surrender the same to the city government. In case the purchaser should fail to relinquish possession of said property, the city treasurer or his deputy shall forthwith adopt measures to eject therefrom all the tenants or occupants thereof as provided for in this Act: Provided, That the original owner of any real estate seized prior to the approval of this Act, who redeems the same within six months subsequent to its approval, is hereby released from any obligation he may have to the government for rent for the use of such property: Provided, further, That the provisions of this section shall apply to redemption of real estate seized for delinquency in the payment of taxes thereon and not redeemed up to the date of the approval of this Act."}},{"id":"PH-H2634-A59","no":59,"noLabel":{"en":"Section 59."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Notice of sale of real estate at public auction. -At any time after the forfeiture of any real estate shall have become"},"text":{"en":"Section 59. Notice of sale of real estate at public auction. -At any time after the forfeiture of any real estate shall have become absolute, the treasurer pursuant to the rules of procedure to be promulgated by the Department Head, may announce the sale of the real estate seized on account of delinquency for the payment of taxes thereon, for the redemption of which no application has been filed. Such announcement shall be made by posting a notice for three consecutive weeks at the main entrance of the City Hall and all the municipal buildings of the province, in either English or Spanish, and in the dialect commonly used in the locality, and by publishing the same once a week for three consecutive weeks in a newspaper of general circulation in the city. Copies of such notice shall be sent immediately by registered mail to the delinquent taxpayer at the latter’s home address, if known. The notice shall state the amount of the taxes and penalties due, the time and place of sale, the name of the taxpayer against whom the taxes are levied, and the appropriate area, the lot number and the location by district and street and the street number and district or barrio where the real estate to be sold is located."}},{"id":"PH-H2634-A60","no":60,"noLabel":{"en":"Section 60."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Sale of real estate—Conditions. -At any time during the sale or prior thereto, the taxpayer may stay the proceedings by"},"text":{"en":"Section 60. Sale of real estate—Conditions. -At any time during the sale or prior thereto, the taxpayer may stay the proceedings by paying the taxes and penalties to the treasurer or his deputy. Otherwise the sale shall proceed and shall be held either at the main entrance of the City Hall or on the premises of the real estate to be sold as the city treasurer or his deputy may determine. The payment of the sale price may, at the option of the purchaser, be made in installments covering a period of not more than twelve months, but the initial payment which shall be made at the time of the sale, and each subsequent payment shall not be less than twenty-five per centum of the sale price, and shall in no case be less than two pesos, unless the total or the balance of the amount due on all seized property in the name of the taxpayer is less than two pesos. The purchaser may occupy the property after paying the first installment, and the usual taxes on the property shall be payable in the year following that in which the sale took place. Any failure of the purchaser to pay the total price of the sale within twelve months from the date thereof shall be sufficient ground for its cancellation, and any part payment made shall revert to the government and if the purchaser has taken possession of the property he shall forthwith surrender the same to the city government. In case the purchaser should fail to relinquish possession of the property, the city treasurer or his deputy shall immediately take steps to object the tenants or occupants of the property in accordance with the procedure prescribed in Section fifty-seven of this Act.\nThe city treasurer or his deputy shall make a report of the sale to the Municipal Board within five days after the sale and shall make the same appear on its record. The purchaser at this sale shall receive from the city treasurer or his deputy a certificate showing the proceedings of the sale, describing the property sold, stating the name of the purchaser, the sale price, the conditions of payment, the amount paid and the exact amount of the taxes and penalties."}},{"id":"PH-H2634-A61","no":61,"noLabel":{"en":"Section 61."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Redemption of real estate after sale. -Within one year from and after the date of the sale the delinquent taxpayer or an"},"text":{"en":"Section 61. Redemption of real estate after sale. -Within one year from and after the date of the sale the delinquent taxpayer or any other person in his behalf, shall have the right to redeem the property sold by paying to the city treasurer or his deputy the amount of the taxes, penalties, costs and interest at the rate of twelve per centum per annum on the purchase price, if paid in whole or on any portion thereof as may have been paid by the purchaser, and such payment shall invalidate the certificate of sale issued to the purchaser, if any, and shall entitle the person making such payment to a certificate to be issued by the city treasurer or his deputy, stating that he has thus redeemed the property, and the city treasurer or his deputy, upon the return by the purchaser of the certificate of sale previously issued to him, shall forthwith refund to the purchaser the entire sum paid by him with interest at twelve per centum per annum, as provided for herein, and such property shall thereafter be free from the lien of such taxes or penalties."}},{"id":"PH-H2634-A62","no":62,"noLabel":{"en":"Section 62."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Execution of deed of final sale. -In case the delinquent taxpayer shall not redeem the property sold as herein provided"},"text":{"en":"Section 62. Execution of deed of final sale. -In case the delinquent taxpayer shall not redeem the property sold as herein provided within one year from the date of the sale, and the purchaser shall then have paid the total purchase price, the city treasurer, as grantor, shall execute a deed in form and effect sufficient to convey to the purchaser so much of the real estate against which the taxes have been assessed as has been sold, free from all liens or encumbrances of any kind whatsoever, and said deed shall succinctly recite all the proceedings upon which the validity of the sale depends. Any balance remaining from the proceeds of the sale, after deducting the amount of the taxes and penalties due, and the costs, if any, shall be returned to the original owner or his representatives."}},{"id":"PH-H2634-A63","no":63,"noLabel":{"en":"Section 63."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Taxes and penalties which shall be paid upon redemption or repurchase. -The taxes and penalties to be paid by way of red"},"text":{"en":"Section 63. Taxes and penalties which shall be paid upon redemption or repurchase. -The taxes and penalties to be paid by way of redemption or repurchase, shall comprise in all cases only the original tax by virtue of the failure to pay which the seizure was made, and its incidental penalties, up to the date of the forfeiture of the real estate to the government."}},{"id":"PH-H2634-A64","no":64,"noLabel":{"en":"Section 64."},"chapter":{"en":"Article XIII Department of Assessment"},"heading":{"en":"Taxes—Legal procedure.—"},"text":{"en":"Section 64. Taxes—Legal procedure.—\n(a) Assessment of a tax shall constitute a lawful indebtedness of the taxpayer to the city which may be enforced by civil action in any court of competent jurisdiction, and this remedy shall be in addition to all remedies provided by law.\n(b) No court shall entertain any suit assailing the validity of a tax assessed under this Charter until the taxpayer shall have paid, under protest, the taxes assessed against him; nor shall any court declare any tax invalid by reason of irregularities or informalities in the proceedings of the officers charged with the assessment or collection of taxes or of a failure to perform their duties within the time specified for their performance, unless such irregularities, informalities, or failure shall have impaired the substantial rights of the taxpayer.\n(c) No court shall entertain any suit assailing the validity of the tax sale of land under this Charter until the taxpayer shall have paid into the court the amount for which the land was sold, together with interest at the rate of twelve per centum per annum upon the sum from the date of the sale to the time of instituting the suit. The money so sold into the court shall belong and be delivered to the purchaser at the tax sale, if the deed is declared invalid, and shall be returned to the depositor, should he fail in his action.\n(d) No court shall declare any such sale invalid by reason of any irregularities or informalities in the proceeding of the officer charged with the duty of making the sale, or by reason of failure by him to perform his duties within the time herein specified for their performance, unless such irregularities, informalities, or failure shall have impaired the substantial rights of the taxpayer."}},{"id":"PH-H2634-A65","no":65,"noLabel":{"en":"Section 65."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Allotment of internal revenue and other taxes. -On the internal revenue accruing to the National Treasury under Chapter"},"text":{"en":"Section 65. Allotment of internal revenue and other taxes. -On the internal revenue accruing to the National Treasury under Chapter II, Title XII of Commonwealth Act Numbered Four hundred and sixty-six, and other taxes collected by the National Government and allotted to the various provinces, as well as the national aid for schools, the city shall receive a share equal to what it would receive if it were a regularly organized province."}},{"id":"PH-H2634-A66","no":66,"noLabel":{"en":"Section 66."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Power to levy special assessments for certain purposes. -The Municipal Board may, by ordinance, provide for the levying"},"text":{"en":"Section 66. Power to levy special assessments for certain purposes. -The Municipal Board may, by ordinance, provide for the levying and collection, by special assessment of the land comprised within the district or section of the city specially benefited, or a part not to exceed sixty per centum of the cost of laying out, opening, constructing, straightening, widening, extending, grading, paving, curbing, walling, deepening, or otherwise establishing, repairing, enlarging, or improving public avenues, roads, streets, alleys, sidewalks, parks, plazas, bridges, landing places, wharves, piers, docks, levees, reservoirs, waterworks, water mains, water courses, esteros, canals, drains, and sewers, including the cost of acquiring the necessary land and public improvements thereon, as hereinafter provided.\nIn case of national public works the Municipal Board, as an agency of the National Government, shall, when the President of the Philippines so direct it, provide for the levying and collection by special assessment of the lands within the section or district of the city specially benefited of the cost or a part thereof to be determined by the President, of laying out, opening, constructing, straightening, widening, extending, grading, paving, curbing, walling, or deepening, or otherwise repairing, enlarging, or improving national roads and other national public works within the city, including the cost of acquiring the necessary land and improvements thereon."}},{"id":"PH-H2634-A67","no":67,"noLabel":{"en":"Section 67."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Basis of apportionment. -The amount of the special assessment shall be apportioned and computed according to the assesse"},"text":{"en":"Section 67. Basis of apportionment. -The amount of the special assessment shall be apportioned and computed according to the assessed valuations of such lands as shown in the books of the city assessor. If the property has not been declared for taxation purposes, the city assessor shall immediately declare it for the owner and assess its value, and such value shall be the basis of the apportionment and computation of the special assessment due thereon."}},{"id":"PH-H2634-A68","no":68,"noLabel":{"en":"Section 68."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Property subject to special assessment. -All lands comprised within the section or district benefited, except those owne"},"text":{"en":"Section 68. Property subject to special assessment. -All lands comprised within the section or district benefited, except those owned by the Republic of the Philippines, shall be subject to the payment of the special assessment."}},{"id":"PH-H2634-A69","no":69,"noLabel":{"en":"Section 69."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Ordinance levying special assessment. -The ordinance providing for the levying and collection of a special assessment sh"},"text":{"en":"Section 69. Ordinance levying special assessment. -The ordinance providing for the levying and collection of a special assessment shall describe with reasonable accuracy the nature, extent, and location of the work to be undertaken; the probable cost of the work; the percentage of the cost to be defrayed by special assessment; the district or section which shall be subject to the payment of the special assessment and shall describe with reasonable accuracy metes and bounds if practicable, and by other reasonable accurate means if otherwise and the period, which shall be not less than five nor more than ten years, in which said special assessment shall be payable without interest. One uniform rate per centum for all lands in the entire district or section subject to the payment of all the special assessment need not be established, but different rates for different parts or sections of the city according as said property will derive greater or less benefit from the proposed work, may be fixed.\nIt should be the duty of the city engineer to make the plans, specifications, and estimates of the public works contemplated to be undertaken."}},{"id":"PH-H2634-A70","no":70,"noLabel":{"en":"Section 70."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Publication of proposed ordinance levying special assessment. -The proposed special assessment ordinance shall be publis"},"text":{"en":"Section 70. Publication of proposed ordinance levying special assessment. -The proposed special assessment ordinance shall be published, with a list of the owners of the lands affected thereby, once a week for four consecutive weeks in any newspaper published in the city, one in English, one in Spanish, and one in the local dialect, if there be any, and in default of local papers, in any newspaper of general circulation in the city. The said ordinance in English, Spanish, and the local dialect shall also be posted in places where public notices are generally posted in the city and also in the district or section where the public improvement is constructed or contemplated to be constructed.\nThe Secretary of the Municipal Board shall, on publication, furnish a copy of the proposed ordinance to each landowner affected, or his agent and shall, if possible, send to all of them a copy of said proposed ordinance by ordinary mail or otherwise."}},{"id":"PH-H2634-A71","no":71,"noLabel":{"en":"Section 71."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Protest against special assessment. -Not later than thirty days after the last publication of the ordinance and the list"},"text":{"en":"Section 71. Protest against special assessment. -Not later than thirty days after the last publication of the ordinance and the list of landowners, as provided in the preceding section, the landowners affected may file with the Municipal Board a protest against the enactment of the ordinance. The protest shall be duly signed by them and shall set forth the addresses of the signers and the arguments in support of their objection or protest against the special assessment established in the ordinance. If no protest is filed within the time and under the condition above specified, the ordinance shall be considered approved as published."}},{"id":"PH-H2634-A72","no":72,"noLabel":{"en":"Section 72."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Hearing of protest. -The Municipal Board shall designate a date and place for the hearing of the protest filed in accord"},"text":{"en":"Section 72. Hearing of protest. -The Municipal Board shall designate a date and place for the hearing of the protest filed in accordance with the next preceding section and shall give reasonable time to all protestants who have given their addresses and to all landowners affected by any protest or protests, and shall order the publication once a week for two consecutive weeks, of a notice of the place and date of the hearing in the same manner herein provided for the publication of the proposed special assessment ordinance. All pertinent arguments and evidences presented by the landowners’ interest or their attorney shall be attached to the proper records. After the hearing, the Municipal Board shall either modify its ordinance or approve it in toto and send notice of its decision to all interested parties who have given their addresses, and shall order the publication of the ordinance as approved finally together with a list of the owners of the parcels of land affected by the special assessment, three times weekly, for three consecutive weeks, in the same manner hereinabove prescribed. The ordinance finally passed by said body shall be sent to the Mayor with all the papers pertaining thereto, for his approval or veto as in the case of other city ordinances. If the Mayor approves it, the ordinance shall be published as above provided, but if he vetoes it, the procedure in similar cases provided in this Charter shall be observed."}},{"id":"PH-H2634-A73","no":73,"noLabel":{"en":"Section 73."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"When ordinance is to take effect. -Upon the expiration of thirty days from the date of the last publication of the ordin"},"text":{"en":"Section 73. When ordinance is to take effect. -Upon the expiration of thirty days from the date of the last publication of the ordinance as finally approved, the same shall be effective in all respects, if no appeal therefrom is taken to the proper authorities in the manner hereinafter prescribed."}},{"id":"PH-H2634-A74","no":74,"noLabel":{"en":"Section 74."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Appeals. -Any time before the ordinance providing for the levying and collection of special assessment becomes effective"},"text":{"en":"Section 74. Appeals. -Any time before the ordinance providing for the levying and collection of special assessment becomes effective in accordance with the preceding section, appeals from such assessment may be filed with the President of the Philippines in the case of public works undertaken or contemplated to be undertaken by the national government, and with the Secretary of Finance in the case of public works undertaken or contemplated to be undertaken by the city. In all cases, the appeal shall be in writing and signed by at least a majority of the owners of the lands situated in the special assessment zone whose holdings represent more than one-half of the total assessed value of the lands affected. The appellant or appellants shall immediately give the Municipal Board a written notice of the appeal, and the Secretary of the Municipal Board shall, within thirty days after receipt of the notice of appeal, forward to the officer who has jurisdiction to decide the appeal an excerpt from the minutes of the Board relative to the proposed special assessment and all the documents in connection therewith."}},{"id":"PH-H2634-A75","no":75,"noLabel":{"en":"Section 75."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Decision of the appeal. -Only appeals made within the time and in the manner prescribed in this Act shall be entertained"},"text":{"en":"Section 75. Decision of the appeal. -Only appeals made within the time and in the manner prescribed in this Act shall be entertained, and the officer to whom the appeal is made may call for further hearing or decide the same in accordance with its merits as shown in the papers or documents submitted to him. All appeals shall be decided within sixty days after receipt by the appellate officer of the docket of the case, and such decision shall be final."}},{"id":"PH-H2634-A76","no":76,"noLabel":{"en":"Section 76."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Fixing of amount of special assessment. -As soon as the ordinance is in full force and effect, the city treasurer shall"},"text":{"en":"Section 76. Fixing of amount of special assessment. -As soon as the ordinance is in full force and effect, the city treasurer shall determine the amount of the special assessment which the owner of each parcel of land comprised within the zone described in the ordinance levying the same is to pay each year during the prescribed period, and shall send to each landowner a notice thereof by ordinary mail. If upon completion of the public works it should appear that the actual cost thereof is smaller or greater than the estimated cost, the city treasurer shall without delay proceed to correct the assessment by increasing or decreasing, as the case may be, the special tax on each parcel of land affected, for the balance of the unpaid annual installments. If all annual installments have already been paid, the city treasurer shall fix the amount of credit to be allowed to, or the additional special tax to be levied upon, the land as the case may be. In all cases, he shall give notice of such rectifications to the parties interested."}},{"id":"PH-H2634-A77","no":77,"noLabel":{"en":"Section 77."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Payment of special assessment. -All sums due from any landowner or owners as the result of any action taken pursuant to"},"text":{"en":"Section 77. Payment of special assessment. -All sums due from any landowner or owners as the result of any action taken pursuant to this Article shall be payable to the city treasurer in the same manner as the annual ordinary tax levied upon real property, and shall be subject to the same penalties for delinquency and be enforced in the same manner as said annual ordinary tax; and all said sums together with any of said penalties shall, from the dates on which they are assessed, constitute special liens on sail land, with the sole exception of the lien for the nonpayment of the ordinary real property tax. If, upon recomputation of the amount of the special assessment in accordance with the next preceding section, it appears that the landowner has paid more than what is correctly due from him, the amount paid in excess shall be refunded to him immediately upon demand; in the other case, the landowner shall have one year within which to pay without penalty the amount still due from him. Said period shall be counted from the date the landowner received the proper notice."}},{"id":"PH-H2634-A78","no":78,"noLabel":{"en":"Section 78."},"chapter":{"en":"Article XIV Tax Allotments and Special Assessment for Public Improvements"},"heading":{"en":"Disposition of proceeds. -The proceeds of the special assessment and penalties thereon shall be applied exclusively to t"},"text":{"en":"Section 78. Disposition of proceeds. -The proceeds of the special assessment and penalties thereon shall be applied exclusively to the purpose or purposes for which the assessment were levied. It shall be the duty of the city treasurer to turn over to the National Treasury all collections made by him from special assessment levies from national public works."}},{"id":"PH-H2634-A79","no":79,"noLabel":{"en":"Section 79."},"chapter":{"en":"Article XV City Budget"},"heading":{"en":"Annual Budget. -At least four months before the beginning of each fiscal year, the city treasurer shall present to the M"},"text":{"en":"Section 79. Annual Budget. -At least four months before the beginning of each fiscal year, the city treasurer shall present to the Mayor a certified detailed statement by department of all receipts and expenditures of the city pertaining to the preceding fiscal year, and to the first seven months of the current fiscal year together with an estimate of the receipts and expenditures for the remainder of the current fiscal year; and he shall submit with this statement a detailed estimate of the revenues and receipts of the city from all sources for the ensuing fiscal year. Upon receipt of this statement and estimate and the estimates of department heads as required by Section twenty-one of this Charter, the Mayor shall formulate and submit to the Municipal Board at least two and a half months before the beginning of the ensuing fiscal year, a detailed budget covering the estimated necessary expenditures for the said ensuing fiscal year, which shall be the basis of the annual appropriation ordinance: Provided, However, That in no case shall the aggregate amount of such appropriation exceed the estimate of revenues and receipts submitted by the city treasurer as provided above."}},{"id":"PH-H2634-A80","no":80,"noLabel":{"en":"Section 80."},"chapter":{"en":"Article XV City Budget"},"heading":{"en":"Supplemental budget. -Supplemental budget formulated in the same manner as the annual budget may be adopted when special"},"text":{"en":"Section 80. Supplemental budget. -Supplemental budget formulated in the same manner as the annual budget may be adopted when special or unforeseen circumstances make such action necessary."}},{"id":"PH-H2634-A81","no":81,"noLabel":{"en":"Section 81."},"chapter":{"en":"Article XV City Budget"},"heading":{"en":"Failure to enact an appropriation ordinance. -Whenever the Municipal Board fails to enact an appropriation ordinance for"},"text":{"en":"Section 81. Failure to enact an appropriation ordinance. -Whenever the Municipal Board fails to enact an appropriation ordinance for any fiscal year before the end of the current fiscal year, the appropriation ordinance for such year shall be deemed reenacted, and shall go into effect on the first day of July of the new fiscal year as the appropriation ordinance for that year."}},{"id":"PH-H2634-A82","no":82,"noLabel":{"en":"Section 82."},"chapter":{"en":"Article XVI The Municipal Court"},"heading":{"en":"Regular, auxiliary, and acting judges of municipal courts. -There shall be a municipal court for Danao City for which th"},"text":{"en":"Section 82. Regular, auxiliary, and acting judges of municipal courts. -There shall be a municipal court for Danao City for which there shall be appointed a municipal judge and an auxiliary municipal judge. The Municipal Board may, when the circumstances so warrant and subject to the approval of the Secretary of Justice, appropriate the necessary amount for the establishment of another branch thereof to be appointed as herein provided.\nThe municipal judge may, upon proper application to the Secretary of Justice, be allowed a vacation of not more than thirty days every year with salary. The auxiliary municipal judge shall discharge the duties of the municipal judge in case of absence, incapacity, or inability of the latter until he assumes his post, or until a new judge shall have been appointed. During his incumbency, the auxiliary municipal judge shall enjoy the powers, emoluments and privileges of the municipal judge who shall not receive any remuneration therefor except the salary to which he is entitled by reason of his vacation provided for in this Charter.\nIn case of absence, incapacity or inability, of both the municipal judge and the auxiliary municipal judge, the Secretary of Justice shall designate the justice of the peace of any of the adjoining municipalities to preside over the municipal court, and he shall hold office temporarily until the regular incumbent or the auxiliary judge thereof shall have assumed office, or until another judge shall have been appointed in accordance with the provisions of this Charter. The justice of the peace so designated shall receive his salary as justice of the peace plus fifty per cent of the salary of the municipal judge whose office he has temporarily assumed. The municipal judge shall receive a salary of four thousand eight hundred pesos per annum."}},{"id":"PH-H2634-A83","no":83,"noLabel":{"en":"Section 83."},"chapter":{"en":"Article XVI The Municipal Court"},"heading":{"en":"Clerk and employees of the Municipal Court. -There shall be a clerk of the municipal court who shall be appointed by the"},"text":{"en":"Section 83. Clerk and employees of the Municipal Court. -There shall be a clerk of the municipal court who shall be appointed by the municipal judge in accordance with Civil Service Law, rules and regulations, and who shall receive a compensation of one thousand eight hundred pesos per annum. He shall keep the seal of the court and affix it to orders, judgments, certificates, records, and other documents issued by the court, in which he shall record in a summary manner the names of the parties and the various proceedings in civil cases, and in criminal cases, the name of the defendant, the charge against him, the names of the witnesses, the date of the arrest, the appearance of the defendant, together with the fines and costs adjudged or collected in accordance with the judgment. He shall have the power to administer oaths.\nThe clerk of the municipal court shall at the same time be sheriff of the city and shall have, as such, the same powers and duties conferred by existing law upon sheriffs. The Municipal Board may provide for such number of clerks in the office of the clerk of the municipal court as the needs of the service may demand. Said clerks shall be appointed by the Mayor subject to civil service rules and regulations."}},{"id":"PH-H2634-A84","no":84,"noLabel":{"en":"Section 84."},"chapter":{"en":"Article XVI The Municipal Court"},"heading":{"en":"Jurisdiction of municipal court. -The municipal court shall have the same jurisdiction in civil and criminal cases and t"},"text":{"en":"Section 84. Jurisdiction of municipal court. -The municipal court shall have the same jurisdiction in civil and criminal cases and the same incidental powers as conferred by law upon municipal courts of chartered cities. In addition, the Municipal Court shall have jurisdiction to hear and decide expropriation, land registration and cadastral cases. The proceedings thereof shall be recorded and decisions therein shall be appealable direct to the Court of Appeals or the Supreme Court, as the case may be.\nUpon the approval of this Act, all land registration and cadastral cases affecting lands in the Municipality of Danao, Province of Cebu, and pending in the Court of First Instance of Cebu shall be transferred to, and decided by, the municipal court of Danao City."}},{"id":"PH-H2634-A85","no":85,"noLabel":{"en":"Section 85."},"chapter":{"en":"Article XVI The Municipal Court"},"heading":{"en":"Procedure in municipal court in prosecutions for violations of laws and ordinances. -In a prosecution for the violation"},"text":{"en":"Section 85. Procedure in municipal court in prosecutions for violations of laws and ordinances. -In a prosecution for the violation of any ordinance, the first process shall be a summons; except that a warrant for the arrest of the offender may be issued in the first instance upon the affidavit of any person that such ordinance has been violated; and that the person making the complaint has reasonable grounds to believe that the party charged is guilty thereof, which warrant shall conclude: \"Against the ordinance of the city in such cases made and provided.\" All proceedings and prosecutions for offenses against the laws of the Philippines shall conform to the rules relating to process, pleading, practice, and procedure for the judiciary of the Philippines, and such rules shall govern the municipal court and its officers in all cases insofar as the same may be applicable. An appeal from the municipal court to the Court of First Instance shall be governed by the provisions of the Rules of Court."}},{"id":"PH-H2634-A86","no":86,"noLabel":{"en":"Section 86."},"chapter":{"en":"Article XVI The Municipal Court"},"heading":{"en":"Preliminary examinations in the city fiscal’s office, municipal court and Court of First Instance. -Every person arreste"},"text":{"en":"Section 86. Preliminary examinations in the city fiscal’s office, municipal court and Court of First Instance. -Every person arrested shall, without necessary delay, be brought before the city fiscal, the municipal court or the Court of First Instance for preliminary hearing, release on bail, or trial. In cases triable in the municipal court the defendant shall not be entitled as of right to a preliminary examination, except to summary one to enable the court to fix the bail, in any case where the prosecution announces itself ready and is ready for trial within three days, not including Sundays, after the request for an examination is presented. In cases triable only in the Court of First Instance the defendant shall not be entitled as of right to preliminary examination in any case where the fiscal of the city, after a due examination of the facts, shall have presented an information against him in proper form. But the Court of First Instance may make such summary investigation into the case as it may deem necessary to enable it to fix the bail or determine whether the offense is bailable.1âшphi1"}},{"id":"PH-H2634-A87","no":87,"noLabel":{"en":"Section 87."},"chapter":{"en":"Article XVI The Municipal Court"},"heading":{"en":"Costs, fees, fines and forfeitures in municipal court. -There shall be taxed against and collected from the defendant, i"},"text":{"en":"Section 87. Costs, fees, fines and forfeitures in municipal court. -There shall be taxed against and collected from the defendant, in case of his conviction in the municipal court, such costs and fees as may be prescribed by law in criminal cases in justice of the peace courts. All costs, fees, fines and forfeitures shall be collected by the clerk of court, who shall keep a docket of those imposed and of those collected, and shall pay collections of the same to the city treasurer, for the benefit of the city, on the next business day after the same are collected, and take receipts therefor. The municipal judge shall examine said docket each day, compare the same with the amount receipted for by the city treasurer and satisfy himself that all such costs, fees, fines and forfeitures have been duly accounted for."}},{"id":"PH-H2634-A88","no":88,"noLabel":{"en":"Section 88."},"chapter":{"en":"Article XVI The Municipal Court"},"heading":{"en":"Commitment to prison. -No person shall be confined in the prison by sentence of the municipal court until the warden or"},"text":{"en":"Section 88. Commitment to prison. -No person shall be confined in the prison by sentence of the municipal court until the warden or officer in charge of the prison shall receive a written commitment showing the offense for which the prisoner was tried, the date of the trial, the exact terms of the judgment or sentence, and the date of the order of the commitment. The clerk shall, under seal of the court issue such commitment in each case of sentence of imprisonment."}},{"id":"PH-H2634-A89","no":89,"noLabel":{"en":"Section 89."},"chapter":{"en":"Article XVII Ownership of Waterworks System, Roads, Streets, Etc."},"heading":{"en":"Ownership of waterworks system, roads, streets, etc. -Notwithstanding the provisions of Republic Act Numbered Thirteen h"},"text":{"en":"Section 89. Ownership of waterworks system, roads, streets, etc. -Notwithstanding the provisions of Republic Act Numbered Thirteen hundred eighty-three, all existing waterworks systems shall be owned by the city and all revenues therefrom shall accrue to the general fund of the city. All existing municipal, provincial and national roads, streets, bridges, docks, piers, wharves, machineries, equipment and other public works improvements shall be owned by the city."}},{"id":"PH-H2634-A90","no":90,"noLabel":{"en":"Section 90."},"chapter":{"en":"Article XVIII Ownership of Lands of the Public Domain within the City"},"heading":{"en":"Ownership of lands of the public domain within the city. -The National Government hereby cedes to Danao City the ownersh"},"text":{"en":"Section 90. Ownership of lands of the public domain within the city. -The National Government hereby cedes to Danao City the ownership and possession to all lands of the public domain within the city."}},{"id":"PH-H2634-A91","no":91,"noLabel":{"en":"Section 91."},"chapter":{"en":"Article XIX Final and Transitory Provisions"},"heading":{"en":"Change of government. -The incumbent mayor, vice-mayor and members of the municipal council of the Municipality of Danao"},"text":{"en":"Section 91. Change of government. -The incumbent mayor, vice-mayor and members of the municipal council of the Municipality of Danao shall continue in office as the mayor, vice-mayor, and members of the Municipal Board of the city, respectively, until the expiration of their present terms of office."}},{"id":"PH-H2634-A92","no":92,"noLabel":{"en":"Section 92."},"chapter":{"en":"Article XIX Final and Transitory Provisions"},"heading":{"en":"Election of Provincial Governor and Members of the Provincial Board of the Province of Cebu. -The voters of Danao City s"},"text":{"en":"Section 92. Election of Provincial Governor and Members of the Provincial Board of the Province of Cebu. -The voters of Danao City shall be qualified and entitled to vote in the election of the Provincial Governor and the members of the Provincial Board of the Province of Cebu."}},{"id":"PH-H2634-A93","no":93,"noLabel":{"en":"Section 93."},"chapter":{"en":"Article XIX Final and Transitory Provisions"},"heading":{"en":"Representative district. -The Danao City shall continue as part of the first representative district of the Province of"},"text":{"en":"Section 93. Representative district. -The Danao City shall continue as part of the first representative district of the Province of Cebu."}},{"id":"PH-H2634-A94","no":94,"noLabel":{"en":"Section 94."},"chapter":{"en":"Article XIX Final and Transitory Provisions"},"heading":{"en":"Separability clause. -If any part or section of this Charter should be declared unconstitutional, such declaration shall"},"text":{"en":"Section 94. Separability clause. -If any part or section of this Charter should be declared unconstitutional, such declaration shall not invalidate the other provisions hereof."}},{"id":"PH-H2634-A95","no":95,"noLabel":{"en":"Section 95."},"chapter":{"en":"Article XIX Final and Transitory Provisions"},"heading":{"en":"Repealing clause. -All Acts, executive orders, administrative orders and proclamations or parts thereof inconsistent wit"},"text":{"en":"Section 95. Repealing clause. -All Acts, executive orders, administrative orders and proclamations or parts thereof inconsistent with any of the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H2634-A96","no":96,"noLabel":{"en":"Section 96."},"chapter":{"en":"Article XIX Final and Transitory Provisions"},"heading":{"en":"This Act shall take effect upon its approval."},"text":{"en":"Section 96. This Act shall take effect upon its approval.\nApproved: June 7, 1961."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating Danao City","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"},"recrawled":"2026-10-24 从 https://lawphil.net/statutes/repacts/ra1961/ra_3028_1961.html 重抓，96 → 96 条"};
  FT["PH-H2635"] = {"id":"PH-H2635","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3029_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"对《国家国内税收法典》的修改","en":"An Act to Amend Section One Hundred and Eighty-Five of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended, and for Other Purposes","orig":"An Act to Amend Section One Hundred and Eighty-Five of Commonwealth Act Numbered Four Hundred and Sixty-Six, Otherwise Known as the National Internal Revenue Code, as Amended, and for Other Purposes"},"level":"law","status":"active","topics":["tax"],"docNumber":"Republic Act No. 3029","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-07","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3029_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2635-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section One hundred and eighty-five of Commonwealth Act Numbered Four hundred and sixty-six, as amended, is hereby further amended by repealing subsections (e), (f), and (m)."}},{"id":"PH-H2635-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A new section is inserted between sections one hundred eighty-five and one hundred eighty-six of Commonwealth Act Numbered Four hundred and sixty-six, as amended, to read as follows:\n\"Section 185-A. Percentage tax on sales of refrigerators, air-conditioners, beverage coolers, ice cream cabinets, and others. -There shall be levied, assessed and collected once only on every original sale, barter, exchange, or similar transaction intended to transfer ownership of, or title to, the articles hereinbelow enumerated a tax equivalent to thirty per centum of the gross selling price or gross value in money of the articles so sold, bartered, exchanged or transferred, such tax to be paid by the manufacturer or producer: Provided, However, That where the articles hereinbelow enumerated are locally manufactured and come under the classification of non-integrated manufactured products as hereinafter defined, the tax shall be fifteen per centum: Provided, further, That where the articles hereinbelow enumerated are locally manufactured and come under the classification of integrated manufactured products as hereinafter defined, the tax shall be seven per centum: Provided, still further, That where the articles enumerated hereinbelow are manufactured out of materials subject to tax under this section, the total cost of such materials, as duly established, shall be deductible from the gross selling price or gross value in money of such manufactured articles:\n\"(a) Refrigerators of all types;\n\"(b) Beverage coolers, ice cream cabinets, water coolers, food and beverage storage cabinets, ice-making machines, and mild cooler cabinets, each such article having, or being primarily designated for use with, a mechanical refrigerating unit operated by electricity, gas, kerosene, or other means; and \"(c) Air-conditioning units.\n\"Any part or accessory of the above-mentioned articles shall be taxed at the same rate as the finished articles.\n\"The words ‘integrated manufactured products’ mean articles manufactured in a manufacturing enterprise which undertakes the operations of processing and/or physically converting raw materials such as metal sheets, plastic pellets, wires, rods, extrusion tubings, castings, forgings, and chemical compounds into various intermediate components and parts, and subsequently assembling or fitting them together into completed and finished articles: Provided, However, That not less than eighty per centum of the total quantity, including the compressor unit, if any, of all the aforementioned intermediate components and parts of said products are manufactured by and within the said manufacturing enterprise.\n\"The words ‘non-integrated manufactured products’ means articles manufactured in a manufacturing enterprise which undertakes the operations of a manufacturing plant as defined in the preceding paragraph: Provided, However, That not less than eighty per centum of the total quantity of all the aforementioned intermediate components and parts of said products are manufactured by and within the said manufacturing enterprise.\""}},{"id":"PH-H2635-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 7, 1961."}}],"pack":"ph-p37"};
  FT["PH-H2636"] = {"id":"PH-H2636","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3030_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第1613号共和国法（B）编附录（A）第464-A页Number (B-224.79) 项目的法案","en":"An Act to Amend Project Number (B-224.79), Page 464-A, Appendix (A), Title (B) of Republic Act Numbered Sixteen Hundred and Thirteen","orig":"An Act to Amend Project Number (B-224.79), Page 464-A, Appendix (A), Title (B) of Republic Act Numbered Sixteen Hundred and Thirteen"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3030","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-08","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3030_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2636-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Project Number (B-224.79), page 464-A, Appendix (A), Title (B) of Republic Act Numbered Sixteen hundred and thirteen is amended to read as follows:\nB-224.79 Tiniclan Creek GOB 50.00 To Bridge Minabitasan Road (50.00) To replace temporary Talembong-Na bridge with permanent one (50.00)"}},{"id":"PH-H2636-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 8, 1961."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Project Number (B-224.79), Page 464-A, Appendix (A), Title (B) of Republic Act Numbered Sixteen Hundred and Thirteen","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
