  FT["PH-H2638"] = {"id":"PH-H2638","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3032_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第1613号共和国法第208页（A）目第（21）项的法案","en":"An Act to Amend Item (21), Page 208, Title (A) of Republic Act Numbered Sixteen Hundred and Thirteen","orig":"An Act to Amend Item (21), Page 208, Title (A) of Republic Act Numbered Sixteen Hundred and Thirteen"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3032","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-08","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3032_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2638-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Item (21), page 208, Title (A) of Republic Act Numbered Sixteen hundred and thirteen is amended to read as follows:\n\"(21) Dumangas Municipal Building, Iloilo ₱20,000 \"(21a) Dumangas Public Market, Iloilo 40,000 \"(21b) Dumangas Public Plaza or Park, Iloilo 20,000.\""}},{"id":"PH-H2638-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 8, 1961."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Item (21), Page 208, Title (A) of Republic Act Numbered Sixteen Hundred and Thirteen","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2639"] = {"id":"PH-H2639","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3033_1961.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Calinog市","en":"An Act Converting the Puericulture Center in the Municipality of Calinog, Province of Iloilo, into a Maternity and Children’s Hospital","orig":"An Act Converting the Puericulture Center in the Municipality of Calinog, Province of Iloilo, into a Maternity and Children’s Hospital"},"level":"law","status":"active","topics":["civil","health","culture"],"docNumber":"Republic Act No. 3033","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3033_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2639-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Calinog Puericulture Center in the Municipality of Calinog, Province of Iloilo, is hereby converted into a maternity and children’s hospital to be known as the Calinog Maternity and Children’s Hospital."}},{"id":"PH-H2639-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The sum of fifty thousand pesos is hereby appropriated out of any funds in the National Treasury not otherwise appropriated, for the construction of the necessary buildings and purchase of equipment."}},{"id":"PH-H2639-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The maternity and children’s hospital established under this Act shall be financed in accordance with the provisions of Republic Act Numbered Nineteen hundred and thirty-nine."}},{"id":"PH-H2639-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 8, 1961."}}],"pack":"ph-p37"};
  FT["PH-H2640"] = {"id":"PH-H2640","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3034_1961.html","fetchedAt":"2026-10-06","articleCount":45,"structureMode":"ARTICLE","title":{"zh":"设立民答那峨发展管理局，规定其权力、职能与职责，为此提供资金并为其他目的法案","en":"An Act Creating the Mindanao Development Authority, Prescribing its Powers, Functions and Duties, Providing Funds Therefor, and for Other Purposes","orig":"An Act Creating the Mindanao Development Authority, Prescribing its Powers, Functions and Duties, Providing Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3034","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-17","completenessNote":"全文，共 45 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3034_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2640-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of policy. It is hereby declared to be the policy or Congress to foster the accelerated and balanced growth of the Mindanao, Sulu and Palawan region, hereinafter referred to as the region, within the context of national plans and policies for social and economic development, through the leadership, guidance and support of the government. To achieve this end, it is recognized that a government corporation should be created for the purpose of drawing up the necessary plans for regional development; providing leadership in the setting up of pioneering or ground-breaking industrial and agricultural enterprises; coordinating or integrating the diverse efforts of the various public and private entities directly engaged in implementing plans and projects affecting power, manufacturing, mining transportation and communication, conservation, resettlement, education, extension work, health and other activities leading to the rapid socio-economic growth of the region; and extending or facilitating the extension of financial, management and technical support to worthwhile industrial and commercial ventures within the region."}},{"id":"PH-H2640-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Mindanao Development Authority Created. There is hereby created a body corporate to be known as the Mindanao Development Authority, hereinafter referred to as the Authority, which shall be organized within sixty days after the approval of this Act. The Authority shall execute the powers and functions herein vested and conferred upon it in such manner as will, in its judgment, aid to the fullest possible extent in carrying out the aims and purposes set forth below. This Act may be cited as the Mindanao Development Authority Act of 1961."}},{"id":"PH-H2640-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Incorporation. The members of the Board of Directors first appointed shall be deemed the incorporators and the incorporation shall be held to have been effected from the date of the first meeting of such Board."}},{"id":"PH-H2640-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Location of principal office. The Authority shall maintain its principal office at a convenient place within the region, but it may have branch offices in other places as are necessary for the proper conduct of its business. After the selection of the location of its principal office, or in the event it later makes a change in such location, the Authority shall publish notice of such selection or change in the Official Gazette.\nPURPOSES"}},{"id":"PH-H2640-A5","no":5,"noLabel":{"en":"Section 5."},"chapter":{"en":"CHAPTER II"},"text":{"en":"Purposes. The Authority shall have the following purposes:\na) To make a comprehensive survey of the physical and natural resources and potentialities of the region, including its social conditions, values and institutions, and special regional problems and, on the basis thereof, to draft a comprehensive and detailed plan designed to promote the region's rapid social and economic development along the general lines set forth by the National Economic Council: Provided , That the said plan shall first be referred to the President who shall act upon it within a period of three months from the date of submission.\nb) To provide the machinery for extending the necessary planning, management and technical assistance to prospective and existing investors in the area.\nc) To make recommendations to the proper agencies on the peso or dollar financing, technical support, physical assistance and, generally, the level of priority to be accorded industrial and agricultural projects soliciting or requiring direct help from or through the government or any of its instrumentalities.\nd) To coordinate and/or integrate such projects or operations of local governments, governmental agencies, public corporations and, where clearly necessary and feasible, those of private entities, as bear directly upon the plans and activities of the Authority so as to make possible the accelerated and balanced development of the region within the context of the guidelines formulated by the National Economic Council; for this purpose, to set up a compact and well-trained staff for effective liaison and consultation or joint planning and/or implementation with such government and private entities: Provided , That disputes involving jurisdiction between the Authority and any department, bureau, office, agency, or instrumentality of the government within the area covered by this Act, and those arising in the coordination or integration of government plans, projects, or operations in the area shall be settled by decision of the President of the Philippines.\ne) To engage in industry, agriculture, or other enterprises within the region which may be necessary or directly contributory to the socio-economic development of the region and, for this purpose, whether by itself or in cooperation with private persons or entities, to organize, finance, invest in, and operate subsidiary corporations when such an arrangement is clearly necessary to implement the powers granted to it by this Act: Provided , That the Authority shall engage only in those activities as are in the nature of pioneering ventures or are demonstrably beyond the scope, capacity, or interest of purely private enterprise due to considerations of geography, technical or capital requirements, returns on investments, and risk.\nf) To advise and cooperate in the readjustment, relocation, or resettlement of population in any part of the country that may be displaced or affected by the socio-economic measures of the government in cooperation with the national, provincial city and municipal agencies organized towards that end.\ng) To make a report annually to the National Economic Council and the Congress through the President, based upon its continuing assessment and evaluation, in the light of the Authority's approved plans and objectives, of the progress of its activities including those done in collaboration with the various government and private entities engaged in the implementation of socio-economic plans and projects in the region, including in such report, among other items, a general survey of the social and economic conditions of the region, socio-economic problems having special reference to the work of the Authority, a comparison of the development targets set for the year ending and the manner in which actual accomplishments measure up to such targets, and appropriate administrative and legislative recommendations.\nCORPORATE POWERS"}},{"id":"PH-H2640-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"CHAPTER III"},"text":{"en":"Powers functions, eminent domain, etc. Except as otherwise specifically provided in this Act, the Authority shall have the following powers and functions:\na) To succeed on its corporate name.\nb) To sue and be sued in such corporate name.\nc) To adopt, alter, and use a corporation sale, which shall be judicially noticed.\nd) To make contracts of any kind and description to enable it to discharge its functions under this Act.\ne) To adopt, amend, and repeal its by-laws.\nf) To acquire, lease, or hold such personal and real property as it deems necessary or convenient in the transaction of its business and may lease, mortgage, sell, alienate, or otherwise dispose any such personal and real property held by it, but it may not sell its properties and products for delivery or use outside of the Philippines without the approval of the President.\ng) To hold agricultural lands in excess of the areas permitted to private corporations or associations by the Constitution.\nh) To exercise the right of eminent domain in the name of the Republic of the Philippines, and in the acquisition of real estate by condemnation proceedings, the title to such real estate shall be taken in the name of the Republic of the Philippines, and thereupon all such real estate shall be entrusted to the Authority as the agent of the Republic of the Philippines to accomplish the aims and purposes of this Act.\n(i) To make such regulations as are necessary to execute the powers and functions vested in it by this Act.\nj) To borrow funds from any local or foreign financial institution independent of the bonds it has issued or may still issue, to finance its projects: Provided , That the total loan outstanding pursuant to this provision shall not exceed one hundred million pesos at any one time.\nk) To purchase, hold, alienate, mortgage, pledge, or otherwise dispose of the shares of the capital stock of, or any bond, security, or other evidence of indebtedness created by any other corporation or copartnership of this or any other country, and while the owner of said stock, to exercise all the rights of ownership, including the right to vote thereon.\nl) For carrying on its business, or for the purpose of attaining or furthering any of its objects, to perform and all acts which a corporation, copartnership, or natural person is authorized to perform under the laws now existing or which may be enacted hereafter.\nCAPITALIZATION AND FINANCING"}},{"id":"PH-H2640-A7","no":7,"noLabel":{"en":"Section 7."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Capitalization. The Authority shall have an authorized capital of three hundred million pesos (P300,000,000.00) which shall be fully subscribed by the Republic of the Philippines and shall be paid out as follows:\na) The sum of thirty million pesos, which is hereby appropriated out of any general fund in the National Treasury not otherwise appropriated, and from proceeds of bond issues, loans and from any other sources of income of the National Government, upon approval of this Act;\nb) The sum of thirty million pesos for every fiscal year thereafter for a period of nine years, from the same sources mentioned in paragraph (a) hereof, which is hereby authorized to be appropriated and to be included in the General Appropriations Act for such subsequent years beginning with the fiscal year 1962-1963. The authorized capital of three hundred million pesos shall constitute a revolving fund for the purpose of financing its business transaction, except as herein provided for."}},{"id":"PH-H2640-A8","no":8,"noLabel":{"en":"Section 8."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Operating expenses. For the operating expenses of the Authority in fiscal year 1961-1962, the sum of five hundred thousand pesos is hereby appropriated out of any general fund in the National Treasury not otherwise appropriated. For the succeeding fiscal years, the Board of Directors may appropriate out of the Authority's paid-in capital a sum not exceeding one million pesos during each fiscal year for operating expenses and a standing annual appropriation is hereby made out of any general fund in the National Treasury of such sum as may be necessary to reimburse the Authority of the total amount actually expended out of the said one million pesos for overhead expenses at the end of each fiscal year, which reimbursement shall accrue to the revolving fund. The unexpended balance of the appropriation for overhead expenses at the end of each fiscal year shall automatically revert to the said revolving fund and whatever earnings of the Authority, if any, shall also accrue to the revolving fund."}},{"id":"PH-H2640-A9","no":9,"noLabel":{"en":"Section 9."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Power to issue bonds. Whenever the Board of Directors may deem it necessary for the Authority to incur an indebtedness or to issue bonds to carry out the provisions of this Act, it shall, by resolution, so declare and state the purpose for which the proposed debt is to be incurred. In order that such resolution be valid, it shall be passed by the affirmative vote of at least three members of such Board and approved by the President of the Philippines upon the recommendation of the Secretary of Finance, after consultation with the National Economic Council and the Monetary Board of the Central Bank."}},{"id":"PH-H2640-A10","no":10,"noLabel":{"en":"Section 10."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Bond limits. The bonds issued under this provision shall in no case exceed the amount of fifty million pesos: Provided , That no single issue shall exceed ten million pesos and that no further issue shall be made if eighty per centum of the immediately proceeding issue is not yet sold.\nThe bonds shall be issued in such amounts as will be needed at any one time, taking into account the rate at which said bonds may be absorbed by the buying public and the fund requirements of projects ready for execution, and considering further a proper balance between productive and non productive projects so that inflation shall be held to the minimum."}},{"id":"PH-H2640-A11","no":11,"noLabel":{"en":"Section 11."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Form, rates of interest, etc. of bonds. The Secretary of Finance, in consultation with the Monetary Board, shall prescribe the form, the rates of interest, the denominations, maturities, negotiability, convertibility, call and redemption features, and all other terms and conditions of issuance, placement, sale, servicing, redemption, and payment of all bonds issued under the authority of this Act.\nThe bonds issued by virtue of this Act may be made payable both as to principal and interest in Philippine currency or any readily convertibly foreign currency. Said bonds shall be receivable as security in any transaction with the Government in which such security is required."}},{"id":"PH-H2640-A12","no":12,"noLabel":{"en":"Section 12."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Exemption from tax. The Authority shall be exempt from all taxes incidental to its operations: Provided , That its subsidiary corporations shall be subject to all said taxes, five years after their establishment under a graduated scale as follows: twenty per centum of all said taxes during the sixth year, forty per centum of all said taxes during the seventh year, sixty per centum of all said taxes during the eighth year, eighty per centum of all said taxes during the ninth year, and one hundred per centum of all said taxes during the tenth year; after said establishment. Such exemption shall include any tax or fee imposed by the government on the sale, purchase or transfer of foreign exchange. All notes, bonds and debentures and other obligations issued by the Authority shall be exempt from all taxes, both as to principal and interest, except inheritance and gift taxes."}},{"id":"PH-H2640-A13","no":13,"noLabel":{"en":"Section 13."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Sinking fund. A sinking fund shall be established in such manner that the total annual contributions thereto, accrued at such rate of interest as may be determined by the Secretary of Finance in consultation with the monetary Board, shall be sufficient to redeem at maturity the bonds issued under this Act. Said fund shall be under the custody of the Central Bank of the Philippines which shall invest the same in such manner as the Monetary Board may approve; charge all expenses of such investments to said sinking fund, and credit the same with the interest on investments and other income belonging to it."}},{"id":"PH-H2640-A14","no":14,"noLabel":{"en":"Section 14."},"chapter":{"en":"CHAPTER IV"},"text":{"en":"Guarantee by the government. The Republic of the Philippines hereby guarantees the payment by the Authority of both the principal and the interest of the bonds, debentures, collaterals, notes or such other obligations issued by the Authority by virtue of this Act, and shall pay such principal and interest in case the Authority fails to do so. In the event that the Authority shall be unable to pay the said principal and interest the Secretary of Finance shall pay the amount thereof which is hereby appropriated out of any funds in the National Treasury not otherwise appropriated, and thereupon, to the extent of the amounts so paid, the Government of the Republic of the Philippines shall succeed to all the rights of the holders of such bonds, debentures, collaterals, notes or other obligations unless the sums so paid by the Republic of the Philippines shall be refunded by the Authority within a reasonable time.\nMANAGEMENT AND PERSONNEL"}},{"id":"PH-H2640-A15","no":15,"noLabel":{"en":"Section 15."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Board of Directors: composition. The corporate powers of the Authority shall be vested in and exercised by a Board of Directors, hereinafter referred to as the Board, which shall be composed of five members appointed by the President with the consent of the Commission on Appointments. The President shall designate from among the members of the Board its Chairman, who shall at the same time be the General Manager of the Authority, notwithstanding any provision of law to the contrary."}},{"id":"PH-H2640-A16","no":16,"noLabel":{"en":"Section 16."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Acting Chairman-General Manager. In case of vacancy in the position of Chairman-General Manager and the President has not yet filled the same in accordance with the preceding section, or in the absence or incapacity of the Chairman-General Manager, the most senior member of the Board in point of length of service as member thereof who meets the qualifications set forth in Section 27 of this Act shall act as Chairman General Manager."}},{"id":"PH-H2640-A17","no":17,"noLabel":{"en":"Section 17."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Appointment and tenure. The term of office of the first members of the Board shall expire as designated by the President at the time of nomination: one at the end of the second year; two at the end of the fourth year; and two, including the Chairman-General Manager, at the end of the sixty year after the approval of this Act. A successor to a member of the Board shall be appointed in the same manner as the original members and shall have a term of office expiring six years from the date of the expiration of the term for which his predecessor was appointed."}},{"id":"PH-H2640-A18","no":18,"noLabel":{"en":"Section 18."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Vacancy before expiration of term. Any member appointed to fill a vacancy in the Board occurring prior to the expiration of the term for which his predecessor was appointed shall serve only for the unexpired period."}},{"id":"PH-H2640-A19","no":19,"noLabel":{"en":"Section 19."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Effect of vacancies; quorum. Vacancies in the Board, as long as there shall be three members in office, shall not impair the power of the Board to execute the functions of the Authority; three of the members of the Board in office shall constitute a quorum for the transaction of the business of the Board."}},{"id":"PH-H2640-A20","no":20,"noLabel":{"en":"Section 20."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Qualifications of directors. All members of the Board shall be natural-born citizens of the Philippines. No person shall be appointed as a member of the Board unless he be of unquestioned integrity and familiar with the technical aspects of socio-economic development.\nEconomics, planners, financial and management experts and other technical personnel employed in other government agencies shall not be barred from serving as members of the Board and receiving per diems therefor: Provided , That their appointment is made with the consent of their respective chief of office."}},{"id":"PH-H2640-A21","no":21,"noLabel":{"en":"Section 21."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Disqualification. No member of the Board shall directly or indirectly engage in partisan political activities or practice any profession or business which may be effected by or related to the exercise of the Authority's functions and powers. Violation of this section shall constitute a ground for dismissal."}},{"id":"PH-H2640-A22","no":22,"noLabel":{"en":"Section 22."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Prohibition against \"conflict-of-interest\". No member of the Board shall be financially interested, directly or indirectly, in any contract entered into by the Authority or in any special privilege granted by the Authority during his term or office. Violation of this prohibition shall constitute a ground for dismissal."}},{"id":"PH-H2640-A23","no":23,"noLabel":{"en":"Section 23."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Removal for cause; courtesy resignation. A member of the Board may be suspended or removed by the President only for cause. No member of the Board shall be required to submit a courtesy resignation at any time during his term or office."}},{"id":"PH-H2640-A24","no":24,"noLabel":{"en":"Section 24."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Board meetings. The Board shall meet as frequently as is necessary to perform its duties, but shall meet at least once every month. The Board shall be convoked by the Chairman or upon written request signed by a majority of the members."}},{"id":"PH-H2640-A25","no":25,"noLabel":{"en":"Section 25."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Per diems. The members of the Board, except the Chairman-General Manager, shall receive for every meeting attended a per diem of one hundred pesos: Provided , That in no case will the total amount received by each exceed the sum of one thousand pesos for any one month. Members of the Board shall be reimbursed by the Authority for actual expenses (including traveling and subsistence expenses) incurred by them in the performance of their duties."}},{"id":"PH-H2640-A26","no":26,"noLabel":{"en":"Section 26."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Powers of General Manager. The General Manager shall be the chief executive of the Authority. As such, he shall have the following powers and duties:\na) To prepare the agenda for the meetings of the Board and to submit for the consideration thereof the policies and measures which he believes to be necessary to carry out the purposes and provisions of this Act;\nb) To execute and administer the policies and measures approved by the Board;\nc) To direct and supervise the operations and internal administration of the Authority. The General Manager may delegate certain of his administrative responsibilities to other officers of the Authority subject to the rules and regulations of the Board; and\nd) To exercise such other powers as may be vested in him by the Board."}},{"id":"PH-H2640-A27","no":27,"noLabel":{"en":"Section 27."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Qualifications of General Manager. In addition to the qualifications for director set forth in Section 20 of This Act, no person shall be appointed General Manager unless he be of demonstrated executive competence and experience in the field of public administration or the management of agricultural, industrial, or commercial enterprises."}},{"id":"PH-H2640-A28","no":28,"noLabel":{"en":"Section 28."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Compensation. The General Manager shall receive a compensation of twenty-four thousand pesos per annum which shall be charged against the Authority's annual appropriation for operating expenses."}},{"id":"PH-H2640-A29","no":29,"noLabel":{"en":"Section 29."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Residence requirement. The General Manager shall be required to reside in the vicinity of the Authority's principal office. He shall be prohibited from engaging in any business, calling or profession during the whole period of his office."}},{"id":"PH-H2640-A30","no":30,"noLabel":{"en":"Section 30."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Activities of the Authority: key officials. The activities of the Authority shall be carried out under the supervision of the General Manager through the following administrative officials who will be responsible directly to him:\na) An assistant General Manager who shall head a Department of Planning and Research.\nb) An assistant General Manager who shall head a Program Implementation Department which shall take charge of implementing specific projects undertaken by the Authority.\nc) A General Counsel with the rank of department head to advise and represent the Authority on legal matters, procedures, and actions.\nd) Such other officials as the Board of Directors may consider necessary for the efficient conduct of the Authority's activities."}},{"id":"PH-H2640-A31","no":31,"noLabel":{"en":"Section 31."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Merit system. All officials, agents, and employees of the Authority shall be selected and appointed on the basis of merit and fitness in accordance with a comprehensive and progressive merit system to be established by the Authority immediately upon its organization and in accordance with Civil Service rules and regulations. The recruitment, transfer, promotion, and dismissal of all Authority personnel, including temporary workers, shall be governed by such merit system."}},{"id":"PH-H2640-A32","no":32,"noLabel":{"en":"Section 32."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Appointment by Board. Division chiefs and officials of higher rank shall be appointed by the Board, upon recommendation of the General Manager."}},{"id":"PH-H2640-A33","no":33,"noLabel":{"en":"Section 33."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Appointment by General Manager. Employees and officials below the rank of division chief shall be appointed to positions in the approved budget by the General Manager upon written recommendation of the head of the department concerned using as guide the standards set forth in the Authority's merit system: Provided , That the General Manager shall submit a quarterly report to the Board regarding personnel selection, placement and training."}},{"id":"PH-H2640-A34","no":34,"noLabel":{"en":"Section 34."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Minimum Wage. All contracts entered into by the Authority which require the employment of persons shall contain provision that not less than the minimum wage fixed by law or the current rate of wage of work of a similar nature prevailing in the vicinity where such work is to be done, whichever is higher, shall be paid to such persons so employed."}},{"id":"PH-H2640-A35","no":35,"noLabel":{"en":"Section 35."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Wage dispute. In the event any dispute arises as to what are the prevailing rates of wages for a particular work in a particular vicinity, the question shall be referred to the Secretary of Labor for determination, who shall give due regard to those rates which have been secured through collective bargaining by the representatives of employees and employers."}},{"id":"PH-H2640-A36","no":36,"noLabel":{"en":"Section 36."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Provision for equivalent wages. Where such work as described in the two preceding sections is done directly by the authority, the prevailing rates of wages shall be paid in the same manner as though such work had been let by contract."}},{"id":"PH-H2640-A37","no":37,"noLabel":{"en":"Section 37."},"chapter":{"en":"CHAPTER V"},"text":{"en":"Other benefits. As far as applicable, the benefits granted by existing labor laws shall extend to persons given employment under the provisions of this Act.\nMISCELLANEOUS PROVISIONS"}},{"id":"PH-H2640-A38","no":38,"noLabel":{"en":"Section 38."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Plans to be formulated within one year. Upon its organization, the authority shall formulate and report to the President of the Philippines with the utmost expedition, but in no case longer than one year, its plans and recommendations for the accelerated and balanced development of the region within the context of the guidelines set forth by the National Economic Council and in accordance with the aims and purposes of this Act."}},{"id":"PH-H2640-A39","no":39,"noLabel":{"en":"Section 39."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Approval of plans. Upon approval by the President of the plans and recommendations referred to in the next preceding section in accordance with Chapter II, Section 5 (a) of this Act, he shall direct the Authority to implement them with dispatch and efficiency. The President shall issue such executive orders or proclamations as may be necessary to reserve or transfer such lands or public property to the Authority as are needed by it to accomplish the purposes of this Act."}},{"id":"PH-H2640-A40","no":40,"noLabel":{"en":"Section 40."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Authority directly under President. Any provision of law to the contrary notwithstanding, the Authority shall operate as an independent corporation subject only to supervision by the President of the Philippines."}},{"id":"PH-H2640-A41","no":41,"noLabel":{"en":"Section 41."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Supplies and services other than personal. All purchases of supplies or contracts for services, except for personal services, entered into by the Authority, shall be done only after the proper bidding is held: Provided , That building shall not be required when: (1) an emergency, as certified to by the General Manager, requires immediate delivery of the supplies or performance of the services, or (2) the aggregate amount involved in any purchase of supplies or procurement of services does not exceed two thousand pesos in the case of services; in which case, such purchase or procurement may be made in the usual course of business: Provided , further , That the Authority's emergency purchases of supplies and services shall not exceed the amount of five thousand pesos for any one month: Provided , lastly , That in comparing bids and in making awards, the Authority shall consider such factors as the cost and relative quality and adaptability of supplies or services; the bidder's financial responsibility, skill, experience, integrity, and ability to furnish repairs and maintenance services; the time of delivery or performance offered; and the bidder's compliance with the specifications desired."}},{"id":"PH-H2640-A42","no":42,"noLabel":{"en":"Section 42."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Auditing. The Auditor General shall be ex-officio Auditor in charge of the auditing office of the Authority. He shall appoint a representative who shall be the auditor thereof. The Auditor General shall, upon recommendation of the auditor of the Authority, appoint or remove personnel of the said auditing office in accordance with the Authority's merit system. The operating expenses of this office and the salaries and traveling expenses of these officials and employees thereof shall be fixed by the Board and paid by the Authority. Such representative shall render a semestral report on the financial condition and operations of the Authority to the Auditor General and the Board. The Auditor General shall submit to the President and the Congress an annual report covering the financial condition and operations of the Authority.\nThese auditing reports shall contain a statement of the resources and liabilities including earnings and expenses, the amount of paid-up capital stock, surplus, reserves and profits, as well as losses, bad debts and such other facts which, under auditing rules and regulations, are considered necessary to accurately describe the financial condition and operations of the Authority: Provided , That before such reports are made, the Authority shall be given reasonable opportunity to examine the exceptions and criticisms of the auditor of the Authority or the Auditor General, as the case may be, to point out, explain or answer any inaccuracies therein, if any, and to file a statement which shall be appended by the auditor of the Authority and the Auditor General in their respective reports."}},{"id":"PH-H2640-A43","no":43,"noLabel":{"en":"Section 43."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Separability clause. The provisions of this Act are hereby declared to be separable, and in the event any one or more of such provisions, are held unconstitutional, they shall not affect the validity of other provisions."}},{"id":"PH-H2640-A44","no":44,"noLabel":{"en":"Section 44."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Laws repealed. All acts, charters, executive orders, administrative orders, rules and regulations, or parts thereof in conflict with this Act are hereby repealed or modified accordingly."}},{"id":"PH-H2640-A45","no":45,"noLabel":{"en":"Section 45."},"chapter":{"en":"CHAPTER VI"},"text":{"en":"Effectivity. This Act shall take effect upon its approval.\nApproved: June 17, 1961"}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the Mindanao Development Authority, Prescribing its Powers, Functions and Duties, Providing Funds Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2641"] = {"id":"PH-H2641","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3035_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"进一步修订第103号联邦法并为其他目的法案","en":"An Act Further Amending Commonwealth Act Numbered One Hundred Three and for Other Purposes","orig":"An Act Further Amending Commonwealth Act Numbered One Hundred Three and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3035","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3035_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2641-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The fifth paragraph of Section one of the Commonwealth Act Numbered One hundred three, as amended, is further amended to read as follows:\n\"The presiding judge shall receive an annual compensation one thousand pesos more than the annual compensation of each of the four associate judges which shall be equal to that allowed or may hereafter be allowed for judges of courts of first instance. They shall be entitled to traveling expenses and per diems when performing official duties outside of the City of Manila. They shall be entitled further to the leave privileges granted under Section two hundred seventy-one of the Administrative Code, as amended by Republic Act Numbered thirteen hundred ninety-nine.\""}},{"id":"PH-H2641-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The differential pay created by the salary adjustment herein provided for shall be drawn from the savings of the Court of Industrial Relations during the fiscal year nineteen hundred sixty-one."}},{"id":"PH-H2641-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1961"}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Further Amending Commonwealth Act Numbered One Hundred Three and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2642"] = {"id":"PH-H2642","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3036_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"对《修订选举法典》的修改","en":"An Act to Amend Sections Thirty-Seven and One Hundred Forty-Nine of Republic Act Numbered One Hundred Eighty, Otherwise Known as the Revised Election Code","orig":"An Act to Amend Sections Thirty-Seven and One Hundred Forty-Nine of Republic Act Numbered One Hundred Eighty, Otherwise Known as the Revised Election Code"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 3036","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3036_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 条号自第 2 条起而非自 1 起（止于第 3 条）：本法为“修改型法条”，仅重述被修改的个别条文，条号承被修改法之后，属该体例使然。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2642-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Sub-section sixteen of Section one hundred forty-nine of the same Code is amended to read as follows:\n\"16. When there are two or more candidates for an office with the same name and/or surname, the voter shall, in order that his vote may be counted, add the correct name, surname or initial that will identify the candidate for whom he votes: Provided , That when two or more candidates have the same surname and one of them is seeking reelection, a ballot wherein only such surname is written shall be counted in favor of the candidate seeking reelection.\""}},{"id":"PH-H2642-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1961"}}],"pack":"ph-p37"};
  FT["PH-H2643"] = {"id":"PH-H2643","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3037_1961.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Two Hundred Thousand Pesos for the Purchase of the Rizal Relics","orig":"An Act Appropriating the Sum of Two Hundred Thousand Pesos for the Purchase of the Rizal Relics"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3037","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-17","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3037_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2643-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The sum of two hundred thousand pesos is hereby appropriated, out of the funds in the National Treasury not otherwise appropriated, for the purchase of the Rizal relics now exhibit at the Fort Santiago Shrine."}},{"id":"PH-H2643-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The purchase price of the Rizal relics shall be exempt from all internal revenue taxes."}},{"id":"PH-H2643-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The President of the Philippines is authorized to purchase the said Rizal relics and may form a special committee for the purpose."}},{"id":"PH-H2643-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1961."}}],"pack":"ph-p37"};
  FT["PH-H2644"] = {"id":"PH-H2644","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3038_1961.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"提高选举委员会主席与委员薪金，并授权选举委员会重组其办公室、确定下属官员与雇员薪金","en":"An Act Increasing the Salaries of the Chairman and Members of the Commission on Elections and Authorizing the Commission on Elections to Reorganize its Office and Fix the Salaries of its Subordinate Officials and Employees","orig":"An Act Increasing the Salaries of the Chairman and Members of the Commission on Elections and Authorizing the Commission on Elections to Reorganize its Office and Fix the Salaries of its Subordinate Officials and Employees"},"level":"law","status":"active","topics":["labor","administrative"],"docNumber":"Republic Act No. 3038","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-17","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3038_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2644-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The subject to the provisions of Article ten, Section one, of the Constitution of the Philippines, the Chairman of the Commission on Elections shall receive an annual salary of sixteen thousand pesos and the other Members fifteen thousand pesos each."}},{"id":"PH-H2644-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Within six months from the date of approval of this Act, the Commission on Elections may reorganize its office. It may abolish or create departments, divisions, sections or units, redistribute functions and personnel, change designations of positions and fix the salaries of its subordinate officials and employees: Provided , That the total number of existing permanent positions shall not be increased: And Provided, further , That no permanent employee already in the service of the Commission on Elections upon the approval of this Act shall be laid off or his salary reduced on account of such reorganization."}},{"id":"PH-H2644-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The provisions of any law to the contrary notwithstanding, the subordinate officials and employees of the Commission on Elections shall receive the salary rates fixed by the Commission without prejudice to whatever benefits they may receive under Reorganization Plans Numbers one-A and two-A regarding classification and pay, and other salary laws."}},{"id":"PH-H2644-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Commission on Elections is hereby authorized to use such sums as are necessary to carry out the provisions of this Act from any unexpended balances of existing certifications to accounts payable from any appropriation for the Commission on Elections. Henceforth, appropriations to cover the salaries of officials and employees of the Commission on Elections as fixed in accordance with the provisions of this Act shall be carried in the annual General Appropriation Acts."}},{"id":"PH-H2644-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect on July one, nineteen hundred sixty-one.\nApproved: June 17, 1961"}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Salaries of the Chairman and Members of the Commission on Elections and Authorizing the Commission on Elections to Reorganize its Office and Fix the Salaries of its Subordinate Officials and Employees","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2645"] = {"id":"PH-H2645","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3039_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立三宝颜市的法案","en":"An Act Creating the of City of Zamboanga","orig":"An Act Providing for the Transfer Free of Charge of All Buildings, Properties and Assets Belonging to the Former Province of Zamboanga and Located Within the City of Zamboanga to the Said City, by Amending Section Fifty of Commonwealth Act Numbered Thirty-Nine, Entitled “An Act Creating the of City of Zamboanga”"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3039","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3039_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2645-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section fifty of Commonwealth Act Numbered Thirty-nine is amended to read as follows:\n\"Sec. 50. Provincial buildings, properties and assets. All buildings, properties and assets belonging to the former Province of Zamboanga and located within the City of Zamboanga are hereby transferred, free of charge, in favor of the said City of Zamboanga.\""}},{"id":"PH-H2645-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1961"}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the of City of Zamboanga","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2646"] = {"id":"PH-H2646","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3040_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"分配菲律宾各众议员选区，为此修订《行政法典》（经修正）第116条与第123条的法案","en":"An Act to Apportion Representative Districts in the Philippines, Amending for This Purpose Section One Hundred Sixteen and One Hundred Twenty-Three of the Administrative Code, as Amended","orig":"An Act to Apportion Representative Districts in the Philippines, Amending for This Purpose Section One Hundred Sixteen and One Hundred Twenty-Three of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 3040","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3040_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2646-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one hundred sixteen of the Administrative Code, as amended, is further amended to read as follows:\n\"Sec. 116. Membership of House. The House of Representatives has one hundred twenty Members, consisting of one Member from each province of representative district hereinafter specified and apportioned as follows:\n\"Abra, one; Agusan, one; Aklan, one; Albay, three; Antique, one; Bataan, one; Batanes, one; Batangas, three; Bohol, three; Bukidnon, one; Bulacan, two; Cagayan, two; Camarines Norte, one; Camarines Sur, three; Capiz, two; Cavite, two; Catanduanes, one; Cebu, seven; Cotabato, three; Davao, three; Ilocos Norte, two; Ilocos Sur, two; Iloilo, five; Isabela, two; Laguna, two; Lanao del Norte, one; Lanao del Sur, two; La Union, two; Leyte, four; Manila, four; Marinduque, one; Masbate, one; Occidental Mindoro, one; Oriental Mindoro, one; Oriental Misamis, one; Occidental Misamis, one; Mountain Province, three; Nueva Ecija, three; Nueva Vizcaya, one; Occidental Negros, four; Oriental Negros, two; Palawan, one; Pampanga, three; Pangasinan, five; Quezon, three; Rizal, four; Romblon, one; Samar, four; Sorsogon, two; Southern Leyte, one; Sulu, one; Surigao del Norte, one; Surigao del Sur, one; Tarlac, two; Zambales, one; Zamboanga del Norte, one; and Zamboanga del Sur, two.\""}},{"id":"PH-H2646-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section one hundred twenty-three of the same Code, as amended, is further amended to read as follows:\n\"Sec. 123. Representative districts in certain provinces. The provinces entitled to elect more than one Member are divided into representative districts as follows, each of which district shall elect one Member, thus constituting the full complement of the representation of such province;\n\"Albay; First District Composed of the municipalities of Bacacay, Malilipot, Tabaco, Malinao, Tiwi, and Sto. Domingo. Second District Composed of the municipalities of Camalig, Manito, Rapu-rapu, Locsin and the City of Legaspi. Third District Composed of the municipalities of Guinobatan, Ligao, Oas, Polangui, Libon, and Jovellar.\n\"Batangas: First District Composed of the municipalities of Agoncillo, San Nicolas, Balayan, Calaca, Calatagan, Lemery, Lian, Nasugbu, San Luis, Taal, and Tuy. Second District Composed of the municipalities of Alitagtag, Batangas, Bauan, Cuenca, Ibaan, Lobo, Mabini, San Juan, Tingloy, and Taysan. Third District Composed of the municipalities of Malvar, Mataasnakahoy, Padre Garcia, Rosario San Jose, Santo Tomas, Talisay, and Tanauan, and the City of Lipa.\n\"Bohol: First District Composed of the municipalities of Antequera, Baclayon, Calape, Corella, Cortes, Dauis, Loon, Maribojoc, Panglao and Tagbilaran. Second District Composed of the municipalities of Alburquerque, Balilihan, Batuan, Bilar, Carmen, Catigbian, Clarin, Dimiao, Inabanga, Lila, Loay, Loboc, Sagbayan, Sevilla, Sikatuna, Tubigon, and Dagohoy. Third District Composed of the municipalities of Alicia, Anda, Buenavista, Candijay, Duero, Garcia-Hernandez, Guindulman, Jagna, Jetafe, Mabini, Sierra-Bullones, Talibon, Trinidad, Ubay, Valencia, San Miguel and Danao.\n\"Bulacan: First District Composed of the municipalities of Bigaa, Bocaue, Bulacan, Calumpit, Guiguinto, Hagonoy, Malolos, Paombong, Plaridel, Pandi and Pulilan. Second District Composed of the municipalities of Angat, Baliuag, Bustos, Marilao, Meycauayan, Norzagaray, Obando, Polo, San Ildefonso, San Jose del Monte, San Miguel, San Rafael, Santa Maria, and Valenzuela.\n\"Cagayan: First District Composed of the municipalities of Alcala, Amulung, Aparri, Baggao, Buguey, Calayan, Camalaniugan, Gattaran, Gonzaga, Iguig, Lal-lo, Penablanca, Sta. Ana, and Tuguegarao, Second District Composed of the municipalities of Abulug, Allacapan, Ballesteros, Claveria, Enrile, Faire, Langangan, Lasam, Pamplona, Piat, Rizal, Sanchez-Mira, Solana, and Tuao.\n\"Camarines Sur: First District Composed of the municipalities of Cabusao, Canaman, Calabanga, Camaligan, Del Gallego, Libmanan, Lupi, Magarao, Bagay, Bombon, and Sipocot, and Naga City. Second District Composed of the municipalities of Buhi, Garchitorena, Ocampo, Caramoan, Goa, Lagonoy, Pili, Sagnay, San Jose, Siruma, Tigaon, and Tinambac. Third District Composed of the municipalities of Baao, Bula, Bato, Nabua, Iriga, Balatan, Gainza, Milaor, Minalabac, Pamplona, Pasacao, and San Fernando.\n\"Capiz: First District Composed of Roxas City and the municipalities of Cuartero, Dao, Dumarao, Ivisan, Ma-ayon, Panay, Panitan, Pilar, Pontevedra, and President Roxas. Second District Composed of the municipalities of Dumalag, Jamindan, Mambusao, Sapian, Sigma, and Tapas.\n\"Cavite: First District Composed of the cities of Cavite and Trece Martires, and the municipalities of Indang, Magallanes, Maragondon, Mendez-Nunez, Naic, Noveleta, Rosario, Tanza, Alfonso, Kawit, Bailen, and Ternate. Second District Composed of the municipalities of Amadeo, Bacoor, Carmona, Dasmarinas, General Trias, Imus, and Silang, and Tagaytay City.\n\"Cebu: First District Composed of the municipalities of Bogo, Borbon, Carmen, Catmon, Danao, Pilar, Poro, San Francisco, Sogod, Tabogon, and Tudela. Second District Composed of the City of Cebu and the municipalities of Compostela, Consolacion, Cordova, Liloan, Mandawe, and Opon. Third District Composed of the municipalities of Carcar, Minglanilla, Naga, San Fernando, and Talisay. Fourth District Composed of the municipalities of Alcoy, Argao, Dalaguete, and Sibonga. Fifth District Composed of the municipalities of Alcantara, Alegria, Badian, Boljoon, Ginatilan, Malabuyoc, Moalboal, Oslob, Samboan, and Santander. Sixth District Composed of the municipalities of Aloguinsan, Barili, Dumanjug, Pinamungajan, and Ronda, and Toledo City. Seventh District Composed of the municipalities of Asturias, Balamban, Bantayan, Daanbantayan, Madridejos, Medellin, San Remegio, Santa Fe, Tabuelan, and Tuburan.\n\"Cotabato: First District Composed of the municipalities of Makilala, Kidapawan, M'lang, Kabacan, Carmen, Pagalungan, Pikit, Midsayap, Libungan, Pigkawayan, Nuling, Parang and Tumbao, and Cotabato City. Second District Composed of the municipalities of Buluan, Tantangan, Tacurong, Sultan sa Barongis, Ampatuan, Isulan, Datu Piang, Dinaig, Upi, Lebak, and Palimbang. Third District Composed of the municipalities of Norala, Banga, Koronadal, Tupi, Polomolok, General Santos, Glan, Kiamba and Maitum.\n\"Davao: First District Composed of the municipalities of Sta. Cruz, Digos, Bansalan, Matanao, Hagonoy, Padada, Sulup, Malalag, Malita, and Jose Abad Santos, Second District Composed of the municipalities of Babak and Samal, and Davao City. Third District Composed of the municipalities of Panabo, Tagum, Santo Tomas, Kapalong, Asuncion, Mawab, Nabunturan, Compostela, Monkayo, Mabini, Pantukan, Lupon, Governor Generoso, Mati, Manay, Banganga, Caraga and Cateel.\n\"Ilocos Norte: First District Composed of the municipalities of Bacarra, Bangui, Burgos, Laoag, Pagudpod, Pasuquin, Piddig, Sarrat, and Vintar, and the municipal districts of Adams, Dumalneg, and Carasi, Second District Composed of the municipalities of Badoc, Banna, Batac, Currimao, Dingras, Nueva Era, Paoay, Pinil, San Nicolas and Solsona.\n\"Ilocos Sur: First District Composed of the municipalities of Bantay, Cabugao, Caoayan, Lapog, Magsingal, Santa Catalina, Santo Domingo, San Ildefonso, San Vicente, Sinait, and Vigan. Second District Composed of the municipalities of Banayoyo, Burgos, Candon, Cervantes, Galimuyod, Lidlidda, Nagbukel, Narvacan, Salcedo, San Esteban, Santa, Santa Cruz, Santa Lucia, Santa Maria, Santiago, and Tagudin, and the municipal districts of Alilem, Angaki, Gregorio del Pilar, San Emilio, Sigay, Sugpon, and Suyo.\n\"Iloilo: First District Composed of the municipalities of Guimbal, Igbaras, Miagao, Oton, San Joaquin, Tigbauan, and Tubungan. Second District Composed of the City of Iloilo, and the municipalities of Buenavista, Jordan, Leganes, Nueva Valencia, and Pavia. Third District Composed of the municipalities of Alimodian, Cabatuan, Janiuay, Leon, New Lucena, Maasin, San Miguel, Santa Barbara, and Zarraga. Fourth District Composed of the municipalities of Barotac Nuevo, Calinog, Dingle, Dumangas, Lambunao, and Pototan. Fifth District Composed of the municipalities of Ajuy, Anilao, Balasan, Banate, Barotac Viejo, Batad, Carles, Concepcion, Duenas, Estancia, Lemery, Passi, San Dionisio, San Enrique, and Sara.\n\"Isabela: First District Composed of the municipalities of Santa Maria, San Pablo, Cabagan, Santo Tomas, Magsaysay, Tumauini, Ilagan, San Mariano, Palanan, Naguilian, Reina Mercedes, Mallig, and Quezon. Second District Composed of the municipalities of Cordon, Santiago, San Agustin, Jones, Echague, Angadanan, Alicia, Luna, Roxas, Cabatuan, San Mateo, Aurora, Callang, Gamu, and Cauayan.\n\"Laguna: First District Composed of the municipalities of Alaminos, Bay, Binan, Cabuyao, Calamba, Calauan, Los Banos, Pila, San Pedro, Santa Rosa, and Victoria, and San Pablo City. Second District Composed of the municipalities of Cavinti, Famy, Lilio, Kalayaan, Luisiana, Lumban, Mabitac, Magdalena, Majayjay, Nagcarlan, Paete, Pagsanjan, Pakil, Pangil, Rizal, Santa Cruz, Santa Maria, and Siniloan.\n\"Lanao del Sur: First District Composed of the City of Marawi, the municipalities of Tamparan, and Wao, and the municipal districts of Saguiaran, Ditsaan-Ramain, Bubong, Kapai, Marantao, Balindong, Molundo, Lumba-Bayabao, Taraka, Poona-Bayabao, and Masiu. Second District Composed of the municipalities of Balabagan, Malabang, and Ganassi, and the municipal districts of Tugaya, Bacolod Grande, Madalum, Madamba, Pualas, Tatarikan, Tubaran, Binidayan, Bayang, Lumbatan, and Butig.\n\"La Union: First District Composed of the municipalities of Bacnotan, Balaoan, Bangar, Luna, San Fernando, San Gabriel, San Juan, Santol, and Sudipen. Second District Composed of the municipalities of Agoo, Aringay, Bauang, Caba, Naguilian, Pugo, Rosario, Santo Tomas, and Tubao, and the municipal district of Bagulin, and Burgos.\n\"Leyte: First District Composed of the municipalities of Almeria, Biliran, Cabucgayan, Caibiran, Calubian, Culaba, Isabel, Kawayan, Leyte, Maripipi, Matag-ob, Merida, Naval, Palompon, San Isidro, Tabango, and Villaba. Second District Composed of the City of Ormoc and the municipalities of Albuera, Bato Baybay, Hilongos, Hindang, Inopacan, Kananga, and Matalom. Third District Composed of the municipalities of Alangalang, Barugo, Burauen, Capoocan, Carigara, Dagami, Jaro, Julita, La Paz, Pastrana, Tabontabon, and Tunga. Fourth District Composed of the municipalities of Abuyog, Babatngon, Dulag, MacArthur, Mahaplag, Mayorga, Palo, San Miguel, Santa Fe, Tanauan, and Tolosa, and the City of Tacloban.\n\"Manila: First District Composed of Tondo; Second District Composed of San Nicolas, Binondo, Quiapo and Sta. Cruz. Third District Composed of Sampaloc and San Miguel. Fourth District Composed of Intramuros, Port Area, Ermita, Malate, Paco, Pandacan, and Sta. Ana.\n\"Mountain Province: First District Composed of the municipalities of Tabuk and Pudtol and the municipal districts of Bayag, Conner, Pinukpuk, Barlig, Natonin, Kabugao, Sabangan, Tinglayan, Luna Balbalan, Lubuagan, Bontoc, Sadanga, Sagada, and Tanudan. Second District Composed of the City of Baguio, the municipalities of Itogon, La Trinidad, and Mankayan, and the municipal districts of Atok, Bakun, Baguias, Bokod, Kabayan, Kapangan, Kibungan, Sablan, Tuba, and Tublay. Third District Composed of the municipal districts of Banaue, Bauko, Besao, Burnay, Hungduan, Kiangan, Lamut, Mayoyao, Potia, and Tadian.\n\"Nueva Ecija: First District Composed of the municipalities of Cuyapo, Guimba, Licab, Lupao, Munoz, Nampicuan, Quezon, Sto. Domingo, Talavera, Talugtug and Zaragoza, Second District Composed of the municipalities of Laur, Bongabon, Rizal, Pantabangan, Carranglan, San Jose, Llanera, Gabaldon, Gen. Mamerto Natividad, and Santa Rosa and the City of Cabanatuan. Third District Composed of the municipalities of Penaranda, San Leonardo, Gapan, Aliaga, San Isidro, Cabiao, General Tinio, Jaen and San Antonio.\n\"Negros Occidental: First District Composed of the City of San Carlos, and the municipalities of Calatrava, Toboso, Escalante, Sagay, Cadiz, and Manapla. Second District Composed of the cities of Silay and Bacolod and the municipalities of Victorias, Saravia, Talisay and Murcia. Third District Composed of the municipalities of Bago, Pulupandan, Valladolid, San Enrique, La Carlota, La Castellana, Moises Padilla, and Isabela. Fourth District Composed of the municipalities of Pontevedra, Hinigaran, Himamaylan, Ilog, Kabankalan, Cauayan, Sipalay, Candoni, Hinobaan, and Binalbagan.\n\"Negros Oriental: First District Composed of the City of Dumaguete and the municipalities of Amlan, Ayungon, Bais, Bindoy, Canlaon, Guihulngan, Jimalalud, La Libertad, Mabinay, Manjuyod, Pamplona, San Jose, Sibulan, Tanjay, Tayasan, and Vallehermoso. Second District Composed of the municipalities of Bacong, Bayawan, Dauin, Enrique Villanueva, Larena, Lazi, Maria, San Juan, Santa Catalina, Siaton, Siquijor, Valencia, and Zamboanguita.\n\"Pampanga: First District Composed of the municipalities of Masantol, Macabebe, Santa Rita, Guagua, Lubao, Floridablanca, and Sexmoan. Second District Composed of the municipalities of Magalang, Arayat, Candaba, San Luis, San Simon, Santa Ana, Mexico, and San Fernando. Third District Composed of the municipalities of Mabalacat, Angeles, Porac, Apalit, Bacolor, Santo Tomas, and Minalin.\n\"Pangasinan: First District Composed of the municipalities of Agno, Aguilar, Alaminos, Anda, Bani, Bolinao, Bugallon, Burgos, Dasol, Infanta, Labrador, Lingayen, Mabini, and Sual. Second District Composed of the City of Dagupan and the municipalities of Binmaley, Mangatarem, San Carlos, and Urbiztondo. Third District Composed of the municipalities of Bayambang, Calasiao, Malasiqui, Mangaldan, Mapandan, Santa Barbara, San Fabian, and San Jacinto. Fourth District Composed of the municipalities of Alcala, Bautista, Binalonan, Manaoag, Pozorrubio, Sison, Santo Tomas, Urdaneta, and Villasis. Fifth District Composed of the municipalities of Asingan, Balungao, Natividad, Rosales, San Manuel, San Quintin, Santa Maria, Tayug, San Nicolas, and Umingan.\n\"Quezon: First District Composed of the municipalities of Mauban, Sampaloc, Lucban, Tayabas, Tiaong, Dolores, Candelaria, Lucena, Pagbilao, Padre Burgos, San Antonio, and Sariaya, Second District Composed of the municipalities of Atimonan, Agdangan, Unisan, Alabat, Aurora, Buenavista, Calauang, Catanauan, General Luna, Guinayangan, Gumaca, Macalelon, Mulanay, Plaridel, Perez, Pitogo, Quezon, San Narciso, San Andres, Lopez, and Tagkawayan. Third District Composed of the municipalities of Casiguran, Dipaculao, Maria Aurora, Baler, Dilasag, San Luis, Dingalan, General Nakar, Infanta, Real, Burdeos, Polillo, and Panukulan.\n\"Rizal: First District Composed of the municipalities of Makati, Taguig, Pateros, Paranaque, Las Pinas, and Muntinglupa, and Pasay City. Second District Composed of the municipalities of Angono, Antipolo, Baras, Binangonan, Cainta, Cardona, Jalajala, Marikina, Montalban, Morong, Pasig, Pililla, San Mateo, Tanay, Taytay, and Teresa and that portion of Quezon City which formed part of the Second District of Rizal in the general election for congressmen immediately preceding the approval of this Act. Third District Composed of the municipalities of Navotas, Malabon, and Caloocan. Fourth District Composed of the municipalities of San Juan del Monte, and Mandaluyong, and that portion of Quezon City which formed part of the First District of Rizal in the general elections for congressmen immediately preceding the approval of this Act.\n\"Samar: First District Composed of the municipalities of Bobon, Catarman, Catubig, Gamay, Lapinig, Laoang, Las Navas, Lavezares, Mondragon, Palapag, Pambujan, San Jose, and San Roque. Second District Composed of the municipalities of Basey, Calbiga, Catbalogan, Daram, Hinabangan, Jiabong, Marabut, Motiong, Pinabacdao, San Sebastian, Santa Rita, Talalora, Villareal, Wright, and Zumarraga, and the municipal districts of Matuguinao and San Jose de Buan. Third District Composed of the municipalities of Arteche, Balangiga, Balangkayan, Borongan, Can-avid, Dolores, Gen. MacArthur, Giporlas, Guiuan, Hernani, Lawa-an, Llorente, Maydolong, Mercedes, Oras, Quinapondan, Salcedo, San Julian, San Policarpio, Sulat, and Taft, and the municipal districts of Maslog and Jipapad. Fourth District Composed of the municipalities of Allen, Capul, San Antonio, San Isidro, Santa Margarita, Santo Nino, Almagro, Gandara, and Tarangnan, and the City of Calbayog.\n\"Sorsogon: First District Composed of the municipalities of Prieta Diaz, Gubat, Barcelona, Bulusan, Irosin, Matnog, Santa Magdalena, and Bulan. Second District Composed of the municipalities of Bacon, Sorsogon, Casiguran, Juban, Magallanes, Castilla, Pilar, and Donsol.\n\"Tarlac: First District Composed of the municipalities of Anao, Camiling, Gerona, Mayantoc, Moncada, Paniqui, Pura, Ramos, San Clemente, San Miguel, and Santa Ignacia. Second District Composed of the municipalities of Bamban, Capas, Concepcion, La Paz, Tarlac, and Victoria.\n\"Zamboanga del Sur: First District Composed of the municipalities of Alicia, Aurora, Dimataling, Dimas, Dumalinao, Dumingag, Ipil, Kabasalan, Kumalarang, Labangan, Lapuyan, Liargao, Malangas, Margosatubig, Molave, Olutanga, Pagadian, San Pablo, Siay, Tambulig, and Tukuran, Second District Composed of the cities of Basilan and Zamboanga.\""}},{"id":"PH-H2646-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval: Provided , That the representative districts herein apportioned shall be filled beginning with the general elections on November fourteen, nineteen hundred and sixty-one.\nApproved: June 17, 1961"}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Apportion Representative Districts in the Philippines, Amending for This Purpose Section One Hundred Sixteen and One Hundred Twenty-Three of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2647"] = {"id":"PH-H2647","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3041_1961.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"修订第2066号共和国法第1条的法案","en":"An Act to Amend Section One of Republic Act Numbered Two Thousand Sixty-Six","orig":"An Act to Amend Section One of Republic Act Numbered Two Thousand Sixty-Six"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3041","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-17","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3041_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2647-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section one of Republic Act Numbered Two thousand sixty-six, entitled \"An Act to authorize the Bureau of Posts to use a portion of its annual sales of postage stamps for the purpose of improving the postal system,\" is amended to read as follows:\n\"Sec. 1. Postmaster General is hereby authorized, subject to the approval of the Secretary of Public Works and Communications, to use not more than twenty per centum of the amount of sales of postage stamps of the Bureau of Posts in each fiscal year for the purposes hereinafter provided:\n\"(1) To employ regular postmasters and/or postal clerks in the municipalities still without post offices;\n\"(2) To employ regular postmasters and/or postal clerks in municipalities where there are no regular post-masters;\n\"(3) To employ additional postal clerks, mail carriers, money order and postal savings bank tellers, stamp tellers, and other personnel needed in the different post offices, postal stations, divisions, and other agencies and units of the Bureau of Posts;\n\"(4) To purchase or acquire lots for post-office sites and/or construct suitable post-office buildings in chartered cities, provincial capitals, municipalities and other places where such buildings or lots are needed and/or to undertake improvements, repair, or enlargement of existing post-office buildings; and \"(5) To defray traveling expenses of personnel and sundry expenses of the Bureau;\n\" Provided, That all appointments made under this Act shall be subject to civil service law, rules and regulations: Provided, further, That the Postmaster General shall also open post offices and purchase out of said amount such postal supplies, furniture and/or mechanical, vehicular, and office equipment as may be needed in various offices: Provided, furthermore, That the amounts authorized to be expended under this Act shall immediately be made available in each fiscal year, the provisions of Commonwealth Act Numbered Two hundred and forty-six and any other existing law to the contrary notwithstanding: Provided, finally, That the Postmaster General before the end of each fiscal year shall submit to the President of the Senate and the Speaker of the House of Representatives a complete report of the manner the amount herein authorized has been used or spent.\""}},{"id":"PH-H2647-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1961."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Amend Section One of Republic Act Numbered Two Thousand Sixty-Six","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2648"] = {"id":"PH-H2648","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3042_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating Annually the Sum of Four Hundred Thousand Pesos as Aid to the Music Promotion Foundation and to Cultural Groups Engaged in the Study and in the Dissemination Abroad of Filipino Folk Arts, Music and Dances","orig":"An Act Appropriating Annually the Sum of Four Hundred Thousand Pesos as Aid to the Music Promotion Foundation and to Cultural Groups Engaged in the Study and in the Dissemination Abroad of Filipino Folk Arts, Music and Dances"},"level":"law","status":"active","topics":["culture"],"docNumber":"Republic Act No. 3042","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3042_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2648-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby appropriated annually, out of any funds in the National Treasury not otherwise appropriated, the sum of four hundred thousand pesos as aid of the government to the Music Promotion Foundation in the prosecution of the objectives of the said Foundation pursuant to the provisions of Republic Act Numbered Thirteen hundred and seventy: Provided, That two hundred thousand pesos thereof shall be given as aid to Filipino cultural group engaged in the study and in the dissemination of Filipino folk arts, music and dances, which has gained national or international recognition and which may be designated by the President of the Philippines as official cultural representative of the Philippines abroad: Provided, further, That such aid to any cultural group shall be limited only to the necessary transportation expenses of the members thereof from and to the Philippines and overseas transportation expenses from one continent to another as may be necessary to fulfill contracts: Provided, finally, That no such aid shall be given unless the cultural group so applying therefor has an existing contract with a reputable impresario who has previously arranged for the performance or exhibition abroad of the cultural group, and that said impresario has guaranteed, among other things, to defray all inland travel and living and incidental expenses of the members of the cultural group while abroad."}},{"id":"PH-H2648-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Republic Act Numbered Twenty hundred and eighty-six is repealed."}},{"id":"PH-H2648-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1961."}}],"pack":"ph-p37"};
  FT["PH-H2649"] = {"id":"PH-H2649","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3043_1961.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"进一步修订第 120 号联邦法（经第 2641 号共和国法修正）的法案","en":"An Act to Further Amend Commonwealth Act Numbered One Hundred Twenty, as Amended by Republic Act Numbered Twenty-Six Hundred and Forty-One","orig":"An Act to Further Amend Commonwealth Act Numbered One Hundred Twenty, as Amended by Republic Act Numbered Twenty-Six Hundred and Forty-One"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3043","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-17","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3043_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2649-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section two-A of Commonwealth Act Numbered One hundred twenty, as such section was inserted therein by Republic Act Numbered Twenty-six hundred and forty-one, is hereby amended to read as follows:\n\"Sec. 2-A. The National Power Corporation shall have an authorized capital stock of two hundred and fifty million pesos divided into two and one-half million shares having a par value of one hundred pesos each, which shares may not be transferred, negotiated, pledged, mortgaged, or otherwise given as security for the payment of any obligation. The said capital stock shall be subscribed wholly by the Government of the Philippines and shall be paid as follows:\n\"The sum of eighty-two million pesos advanced to the National Power Corporation by the Government of the Philippines pursuant to the provisions of Republic Act Numbered Two hundred sixty-six shall be the paid-in subscription for eight hundred twenty thousand shares of stock of said capital stock;\n\"The surplus of ten million pesos of the National Power Corporation shall be capitalized, and shall also be an additional paid-in subscription of the Government of the Philippines for one hundred thousand shares of stock of the capital stock; and \"The balance of one hundred and fifty-eight million pesos shall be paid from time to time by conversion of part of existing bonded indebtedness into equity capital and from surpluses of the Corporation, and in the absence thereof, from bond issues upon request of the National Power Corporation for specific projects duly approved by the President of the Philippines. The payment of the interest of the bonded indebtedness incurred by the government to capitalize the National Power Corporation shall be paid by the National Power Corporation out of its net earnings after the completion of the project for which such indebtedness was incurred: Provided , That such interest up to July one, nineteen hundred seventy, shall be capitalized and considered as additional authorized capital of the National Power Corporation: And provided, further , That from July one, nineteen hundred seventy, the National Power Corporation shall begin redeeming the additional capital of one hundred and fifty-eight million pesos herein authorized, at a rate equal to yearly sinking fund as provided in Section four of Commonwealth Act Numbered One hundred twenty.\""}},{"id":"PH-H2649-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The National Power Corporation shall invest thirty percent of the additional capital to be raised under this Act in projects in the Visayas, thirty-five percent in projects in Luzon, and thirty-five percent in projects in Mindanao, Sulu and Palawan."}},{"id":"PH-H2649-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The National Power Corporation is hereby authorized to represent and transact for the benefit and in behalf of the public consumers, and it shall in any contract for the supply of electric power to a franchise holder require as a condition that the franchise holder, if it receives at least fifty percent of its electric power and energy from the National Power Corporation, shall not realize a net profit of more than twelve percent annually of its investments plus two-month operating expenses. The National Power Corporation shall renew all existing contracts with franchise holders for the supply of electric power and energy, in order to give effect to the provisions hereof. In the event that the net profit as verified by the Public Service Commission should exceed the said twelve percent, the Public Service Commission shall order such excess to be returned pro rata to the customers either in cash or as credit for the future electric bills."}},{"id":"PH-H2649-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All transmission lines from the National Power Corporation's power plant or main substation to the substation serving a power distributor shall be at the expense of the National Power Corporation, and no rent or charge shall be imposed for the use of said power lines without prior agreement of the corporation and the power distributor."}},{"id":"PH-H2649-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"In the purchase of machineries, equipment, supplies and materials needed to implement projects under this Act, all things being equal, priority shall be given to Filipino companies or entities manufacturing the same."}},{"id":"PH-H2649-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1961"}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Further Amend Commonwealth Act Numbered One Hundred Twenty, as Amended by Republic Act Numbered Twenty-Six Hundred and Forty-One","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2650"] = {"id":"PH-H2650","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3044_1961.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"授权菲律宾大学在菲律宾总医院设立收费病房并为此贷款的法案","en":"An Act Authorizing the University of the Philippines to Establish a Pay Pavilion in the Philippine General Hospital and to Contract Loans for Such Purpose","orig":"An Act Authorizing the University of the Philippines to Establish a Pay Pavilion in the Philippine General Hospital and to Contract Loans for Such Purpose"},"level":"law","status":"active","topics":["education","health"],"docNumber":"Republic Act No. 3044","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-17","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3044_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2650-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"To enable the University of the Philippines to meet its increasing responsibilities, said University is hereby authorized to establish a pay pavilion within the present Philippine General Hospital compound."}},{"id":"PH-H2650-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the University of the Philippines is hereby authorized to borrow for the above-stated purpose an amount not exceeding three million pesos from the Government Service Insurance System, the Social Security System, and/or other government financing entities, which are also hereby authorized to grant such loans. The construction of the building for said pay pavilion shall be under the supervision of and in accordance with the rules of the University of the Philippines, any other provision of law to the contrary notwithstanding."}},{"id":"PH-H2650-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval.\nApproved: June 17, 1961."}}],"pack":"ph-p37","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the University of the Philippines to Establish a Pay Pavilion in the Philippine General Hospital and to Contract Loans for Such Purpose","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H2651"] = {"id":"PH-H2651","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1961/ra_3045_1961.html","fetchedAt":"2026-10-06","articleCount":9,"structureMode":"ARTICLE","title":{"zh":"经费拨款法","en":"An Act Appropriating the Sum of Twenty Million Pesos for a Period of Five Years for the Development of the Abaca Industry","orig":"An Act Appropriating the Sum of Twenty Million Pesos for a Period of Five Years for the Development of the Abaca Industry"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 3045","issuingBody":"Congress of the Philippines","promulgatedDate":"1961-06-17","completenessNote":"全文，共 9 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1961/ra_3045_1961.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H2651-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act shall be known as the Abaca Development Program Act."}},{"id":"PH-H2651-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"It is hereby declared to be the national policy to rehabilitate and expand the abaca industry of the country to maintain the world supremacy and the world demand for abaca fiber and to provide adequate measures to insure permanent stability in the production of abaca."}},{"id":"PH-H2651-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Abaca Development Program envisioned in this Act shall be under the administrative supervision and control of the Secretary of Agriculture and Natural Resources, through a Board composed of the Director of the Bureau of Agricultural Extension, the Director of the Bureau of Plant Industry, the Manager of the Fiber Inspection Service, three representatives of the three abaca-producing regions and one representative of the Philippine Abaca Federation, Inc., and shall cover the following phases considered necessary to attain the primary objective to bring to at least the pre-war level the production of abaca fiber, popularly known as Manila hemp, and to reduce the cost of production in order to compete successfully with sisal, henequene and synthetic fibers; and finally, to achieve the desired level of Philippine export of abaca to the world market, as follows:\n1.Abaca seed production and distribution to rehabilitate the present depleted abaca plantations;\n2.Improvement of fiber extraction methods;\n3.Development, and promotion of cottage industries using abaca as raw material;\n4.Abaca research;\n5.Abaca foreign trade promotion, and\n6.General administration.\nThe Board shall elect its chairman."}},{"id":"PH-H2651-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"There shall be appropriated, out of any funds in the National Treasury not otherwise appropriated, the sum of twenty million pesos to be disbursed four million pesos every, fiscal year from 1961-1962 up to 1965-66 for the purpose of this Act."}},{"id":"PH-H2651-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Subject to adjustments that the Secretary of Agriculture and Natural Resources may deem necessary, upon recommendation of the Chairman of the Board, or as may be specified in the annual General Appropriation Act, the financing of the five-year Abaca Development Program shall be implemented and shall follow the following yearly schedule:\n1. For planting materials ₱900,000.00\n2. Improvement of fiber extraction methods 800,000.00\n3. Development and promotion of cottage industries using abaca as raw materials 800,000.00\n4. Abaca research 800,000.00\n5. Abaca Foreign Trade Promotion 200,000.00\n6. General Administration 500,000.00 Total ₱4,000,000.00"}},{"id":"PH-H2651-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The budget together with the production plan for each year of the Abaca Development Program shall be prepared by the Chairman of the Board who shall submit the same through the Secretary of Agriculture and Natural Resources to the President for approval. All balances at the close of each fiscal year shall be carried over for expenditure in the succeeding fiscal years."}},{"id":"PH-H2651-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Abaca Development Program shall automatically be integrated in the yearly General Appropriation Act of the Republic of the Philippines under the Bureau of Plant Industry until the completion of its fifth year operation and thereafter in order to insure its continuity."}},{"id":"PH-H2651-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The Chairman of the Board shall render a yearly report through the Secretary of Agriculture and Natural Resources to the President of the Philippines, the President of the Senate and the Speaker of the House of Representatives, on the operation of the Program."}},{"id":"PH-H2651-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 17, 1961."}}],"pack":"ph-p37"};
